(window.GIM_TS=window.GIM_TS||{})["Sukkah.1"]={"from":24,"a":[["\u0003יורדין לידי טומאה במחשבה,\u0004 שעל ידי עצם המחשבה שחושב שכבר הגיעו כלים אלה לגמר מלאכתם ושוב איננו רוצה להוסיף ולשכללם — הרי מיד הם חשובים ככלים גמורים, וראויים מיד לקבל טומאה. אולם \u0003אין\u0004 הכלים שנטמאו \u0003עולין מטומאתן אלא בשינוי מעשה,\u0004 שכלי שנחשב לגמור (ומשום כך — ראוי לקבל טומאה) אין בכח המחשבה שרצונו לעשות בכלי שכלול נוסף, כדי להוציא את הכלי מטומאתו, עד שיעשה מעשה ממשי של שינוי ותיקון בכלי. וכלל הוא כי \u0003מעשה\u0004 שעושה אדם בכלי לתקנו בצורה זו או אחרת \u0003מוציא\u0004 ומשנה את מעמדו לענין טומאה וטהרה, הן \u0003מיד מעשה\u0004 קודם שעשה בו, והן \u0003מיד מחשבה\u0004 שחשב עליו שהוא גמור או שאינו גמור. ואילו \u0003מחשבה אינה מוציאה, לא מיד מעשה\u0004 שעשה בדבר, \u0003ו\u0004אף \u0003לא מיד מחשבה\u0004 בלבד, שהחליט שהכלי הגיע כבר לידי גמר. הרי נובע מכאן שאי אפשר שיבטל קש השבולת מתורת יד לקבל טומאה על ידי מחשבה בלבד, בלא מעשה.","\u0003וכי תימא\u0004 \u0005[ואם תאמר]\u0006 שיש מקום לחלק בין המקרים; \u0003הני מילי\u0004 \u0005[דברים אלה]\u0006 שאין מחשבה מועילה לטהר אמורים דווקא ב\u0003כלים דחשיבי\u0004 \u0005[שהם חשובים],\u0006 \u0003אבל ידות\u0004 של אוכלים ש\u0003לצורך אכילה נינהו\u0004 \u0005[הם],\u0006 שמא \u0003במחשבה נעשה\u0004 חלק מהפרי כיד \u0003ובמחשבה סלקא\u0004 \u0005[עולה,\u0006 מסתלקת ממנו הטומאה\u0005].\u0006 אולם, \u0003והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]\u0006 לא כן; \u0003כל ידות האוכלין שבססן בגורן — טהורות,\u0004 שבכך הראה שאין הוא צריך להם ואינו מחשיבן. \u0003ור' יוסי מטמא.\u0004","ומעתה נברר: \u0003בשלמא למאן דאמר\u0004 \u0005[נניח\u0006 לשיטת \u0005מי שאמר\u0006 ופירש\u0005]\u0006 מה משמעות \u0003\"בססן\" — התיר אגודן,\u0004 שרק התיר את הקשרים שקושרים בהם את עומרי השבלים, הרי \u0003שפיר\u0004 \u0005[יפה]\u0006 ומובן הדבר, שהרי לא עשה מעשה בשבלים עצמן, ובכל זאת כיון שעל ידי מעשהו מראה שלא נוח לו בידות, שהרי אין משתמשים בהם אלא לאגידה והוא הראה שאינו מעונין באגידתן — ממילא בטלות הן מתורת יד. \u0003אלא למאן דאמר\u0004 \u0005[\u0006לשיטת \u0005מי שאמר]\u0006 כי \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"בססן\",\u0004 כוונתו \u0003בססן\u0004 (דרסן) \u0003ממש,\u0004 אם כן \u0003מאי איכא למימר\u0004 \u0005[מה יש לומר]?\u0006 שלפי דעה זו כל עוד אינו עושה מעשה בשבלים נחשבות ידותיהם לחלק מן האוכל ומקבלות טומאה! ומה אם כן טעם שיטת חכמים.","ומשיבים: \u0003הכא נמי,\u0004 \u0005[כאן גם כן]\u0006 כשנחלקו בסיכוך בשבלים מדובר \u0003שבססן ממש,\u0004 ולכן בטלו מלקבל את הטומאה. ושואלים: \u0003אי הכי\u0004 \u0005[אם כן]\u0006 שעשו בהן מעשה, \u0003מאי טעמייהו\u0004 \u0005[מה טעמם]\u0006 של \u0003אחרים\u0004 האוסרים את השבלים לסיכוך אפילו לאחר שבססן? ומשיבים: \u0003דאמור\u0004 \u0005[שאמרו,\u0006 סברו\u0005]\u0006 \u0003כ\u0004שיטת \u0003ר' יוסי. דתנן\u0004 \u0005[ש\u0006הרי \u0005שנינו\u0006 באותה משנה\u0005]\u0006 שאף לאחר בסיסה \u0003ר' יוסי מטמא.\u0004","ותוהים: \u0003האי מאי\u0004 \u0005[\u0006דבר \u0005זה מהו]?!\u0006 כלומר, איך אפשר כלל לומר תירוץ כעין זה? \u0003בשלמא התם\u0004 \u0005[נניח שם]\u0006 בעיקר המחלוקת בענין טומאת השבלים בגורן \u0003טעמא\u0004 \u0005[טעמו]\u0006 של \u0003ר' יוסי\u0004 שסבור שעדיין הידות מקבלות טומאה משום ש\u0003חזיא\u0004 \u0005[ראויה\u0006 יד השבולת\u0005]\u0006 \u0003ל\u0004כפי שאמר \u0003ר' שמעון בן לקיש,\u0004 שהסביר שאף לאחר דריסת השבלים והקש נוח לאדם בידות השבלים \u0003הואיל וראויות להופכן בעתר,\u0004 שידות אלה מקילות לתפוס את השבלים ולהפכן במלגז ולולא הידות היו השבלים נשמטות בין שיני המלגז.","\u0003אלא הכא\u0004 \u0005[כאן]\u0006 שהוא רוצה בקש לסיכוך \u0003למאי חזיא\u0004 \u0005[למה ראויות]\u0006 ידות אלה לאחר בסיסה? ומשיבים: \u0003חזיא לכי סתר למנקט להו בגילייהו\u0004 \u0005[ראויות הן שכאשר סותר\u0006 את הסכך \u0005לאחוז אותן בקשיהן]\u0006 ולא יתפרקו השבלים לגרגירים גרגירים לחוד. וכיון שיש לידות אלה שימוש מסויים אפילו לאחר בסיסה, יש מקום לסברת אחרים שהידות מקבלות טומאה.","כיון שהוזכרה מחלוקת חכמים ור' יוסי, מביאים אותה לדון בה ל\u0003גופא, כל ידות האוכלין שבססן בגורן\u0004 — \u0003טהורות, ור' יוסי מטמא.\u0004 ושואלים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"בססן\"? ר' יוחנן אמר: בססן ממש,\u0004 כלומר: דרס עליהן. \u0003ר' אליעזר אומר: התיר אגדן\u0004 התיר רק את האגד הקושר את עומרי השבלים.","ומעירים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 לשיטת \u0003ר' אליעזר\u0004 ש\u0003אמר\u0004 כי \u0003\"בססן\"\u0004 פירושו; \u0003התיר אגדן, היינו\u0004 \u0005[זהו]\u0006 הטעם ש\u0003מטמא ר' יוסי,\u0004 שלדעתו אין די במעשה זה כדי להוציא את הידות מלקבל טומאה. \u0003אלא\u0004 לשיטת \u0003ר' יוחנן\u0004 ש\u0003אמר\u0004 כי \u0003בססן ממש, אמאי\u0004 \u0005[מדוע]\u0006 אם כן \u0003מטמא ר' יוסי?\u0004 שהרי באופן כזה אין בהם כל חשיבות! \u0003אמר ר' שמעון בן לקיש: הואיל וראויות\u0004 השבלים \u0003להופכן בעתר\u0004 (במלגז) בצורה טובה יותר על ידי הידות, על כן אינן בטלות משימושן וחשיבותן אף לאחר בסיסה. כיון שהוזכר עתר, מביאים מאמר אגדה המזכיר עתר בהקשר אחר.","\u0003אמר ר' אליעזר: למה נמשלה תפלתן של צדיקים כעתר,\u0004 כאמור \"ויעתר יצחק לה' לנוכח אשתו כי עקרה היא ויעתר לו ה'\" (בראשית כה, כא) — \u0003לומר לך: מה עתר זה מהפך את התבואה בגורן ממקום למקום אף תפלתן של צדיקים מהפכת\u0004 (משנה) \u0003דעתו של הקדו‍ש ברוך הוא ממדת אכזריות למדת רחמנות,\u0004 ושומע לקול תפילותיהם.","\u0003מסככין בנסרים\u0004 (קורות עץ ישרות, שבכיוצא בהן עושים תיקרה לבית), אלו \u0003דברי ר' יהודה, ורבי מאיר אוסר. נתן עליה\u0004 על הסוכה \u0003נסר שהוא רחב ארבעה טפחים\u0004 — הסוכה בכללה \u0003כשרה, ובלבד שלא יישן תחתיו,\u0004 תחת נסר זה.","\u0003אמר רב: מחלוקת\u0004 זו, היא דווקא \u0003בנסרין שיש בהן\u0004 רוחב \u0003ארבעה\u0004 טפחים, שרוב תקרות הבתים עשויות מנסרים ברוחב כזה, ש\u0003ר' מאיר אית ליה\u0004 \u0005[יש לו,\u0006 מקבל\u0005]\u0006 \u0003גזרת תקרה,\u0004 שכיון שהסיכוך נראה כתיקרה רגילה, לכך אם יתירו בכך, יש לחשוש שמא יבוא אדם לישון בחג תחת תקרת ביתו. \u0003ור' יהודה לית ליה\u0004 \u0005[אין לו,\u0006 אינו מקבל\u0005]\u0006 \u0003גזרת תקרה. אבל בנסרין שאין בהן ארבעה\u0004 טפחים — \u0003דברי הכל,\u0004 אף לדעת ר' מאיר, \u0003כשרה. ושמואל אמר:\u0004 דווקא בנסרים \u0003שאין בהן\u0004 ברוחבם \u0003ארבעה\u0004 טפחים \u0003מחלוקת, אבל\u0004 בנסרים ש\u0003יש בהן ארבעה\u0004 טפחים — \u0003דברי הכל,\u0004 אף לר' יהודה, \u0003פסולה.\u0004","על דברי שמואל תוהים: לדעתו חלקו גם בנסרים ש\u0003אין בהן ארבעה,\u0004 ולכאורה הוא הדין \u0003אפילו\u0004 כשרחבים \u0003פחות משלשה\u0004 טפחים, אולם אלה \u0003הא\u0004 \u0005[הרי]\u0006 \u0003קנים בעלמא נינהו\u0004 \u0005[בלבד הם]\u0006 ומה טעם ייאסרו?","\u0003אמר רב פפא: הכי קאמר\u0004 \u0005[כך אמר],\u0006 כך יש להבין את דברי שמואל: \u0003יש בהן ארבעה\u0004 טפחים — \u0003דברי הכל פסולה, פחות משלשה — דברי הכל כשרה, מאי טעמא\u0004 \u0005[מה טעם] —\u0006 \u0003קנים בעלמא נינהו\u0004 \u0005[בלבד הם]\u0006 וכשרים. \u0003כי פליגי\u0004 \u0005[כאשר נחלקו]\u0006 במשנה, הרי זה בנסרים הרחבים \u0003משלשה עד ארבעה\u0004 טפחים. וטעמם: \u0003מר\u0004 \u0005[חכם זה,\u0006 ר' יהודה\u0005]\u0006 \u0003סבר\u0004 כי \u0003כיון דליתנהו\u0004 \u0005[שאין בהם]\u0006 \u0003שיעור\u0004 מספיק כדי להחשיבם כ\u0003מקום,\u0004 שהרי מקום חשוב הוא דווקא מארבעה טפחים ומעלה, \u0003לא גזרינן\u0004 \u0005[אין אנו גוזרים]\u0006 איסור בהם. \u0003ומר\u0004 \u0005[וחכם זה,\u0006 ר' מאיר\u0005]\u0006 \u0003סבר\u0004 כי \u0003כיון דנפקי להו\u0004 \u0005[שהם יוצאים]\u0006 \u0003מתורת לבוד,\u0004 שדין לבוד חל רק בפחות משלושה טפחים, ונסרים אלה כיון שרחבים הם משלושה טפחים, \u0003גזרינן\u0004 — יש לגזור שלא לסכך בהם. ומנסים להביא ראיות לשיטות הפירוש.","\u0003תנן\u0004 \u0005[שנינו\u0006 במשנתנו\u0005]:\u0006 \u0003נתן עליה\u0004 על הסוכה \u0003נסר שהוא רחב ארבעה טפחים\u0004 — הסוכה \u0003כשרה, ובלבד שלא יישן תחתיו. בשלמא\u0004 \u0005[נניח]\u0006 שיטת \u0003שמואל,\u0004 ש\u0003אמר\u0004 כי \u0003בשאין בהן ארבעה\u0004 טפחים \u0003מחלוקת, אבל\u0004 כש\u0003יש בהן ארבעה דברי הכל פסולה — משום הכי\u0004 \u0005[כך]\u0006 \u0003לא יישן תחתיו,\u0004 שהרי נסר זה פסול לכל הדעות. \u0003אלא\u0004 לשיטת \u0003רב\u0004 ש\u0003אמר\u0004 כי \u0003בשיש בהן ארבעה\u0004 טפחים \u0003מחלוקת, אבל\u0004 כש\u0003אין בהן ארבעה\u0004 טפחים \u0003דברי הכל כשרה,\u0004 אם כן לשיטת \u0003ר' יהודה אמאי\u0004 \u0005[מדוע]\u0006 \u0003לא יישן תחתיו?\u0004 הלא לשיטתו נסר שאינו רחב מארבעה טפחים כשר לסיכוך!","ומשיבים: \u0003מי סברת\u0004 \u0005[האם סבור אתה]\u0006 כי דברים אלה בנסר \u0003דברי הכל היא\u0004 אף לשיטת ר' יהודה? לא כן, אלא \u0003סיפא אתאן\u0004 \u0005[בסופה\u0006 של המשנה \u0005באנו,\u0006 חזרנו\u0005]\u0006 \u0003ל\u0004שיטת \u0003ר' מאיר,\u0004 ולשיטתו בלבד אסור לישון תחתיו, מה שאין כן לדעת ר' יהודה. ואם כן אין מכאן ראיה.","ומציעים; \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 הוכחה ממה ששנינו: \u0003שני סדינים\u0004 שהניחם על הסכך, \u0003מצטרפין\u0004 יחד לארבעה טפחים שהוא שיעורו של סכך פסול הפוסל את הסוכה."],["\u0003שני נסרין\u0004 על הסוכה \u0003אין מצטרפין\u0004 להיות כסכך פסול, ואינן פוסלים. \u0003ר' מאיר אומר: אף נסרין\u0004 דינם \u0003כסדינין\u0004 ומצטרפים לפסול.","ונברר את הדברים; \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003ל\u0004פי שיטת \u0003שמואל\u0004 ש\u0003אמר\u0004 כי \u0003בשאין בהן ארבעה\u0004 טפחים \u0003מחלוקת, אבל\u0004 כש\u0003יש בהן ארבעה\u0004 טפחים ל\u0003דברי הכל פסולה,\u0004 אם כן לשיטתו \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"מצטרפין\"\u0004 כאן — שגם נסרים פחותים מארבעה טפחים \u0003מצטרפין\u0004 יחד להיות כ\u0003ארבעה\u0004 טפחים לפסול.","\u0003אלא\u0004 לשיטת \u0003רב,\u0004 ש\u0003אמר\u0004 כי \u0003בשיש בהן ארבעה\u0004 טפחים \u0003מחלוקת, אבל\u0004 כש\u0003אין בהן ארבעה\u0004 טפחים \u0003דברי הכל כשרה, היכי דמי\u0004 \u0005[כיצד בדיוק\u0006 מדובר כאן\u0005]?\u0006 \u0003אי דאית בהו\u0004 \u0005[אם יש בהם]\u0006 בכל אחד מהנסרים הללו \u0003ארבעה\u0004 טפחים, אם כן \u0003למה להו לאיצטרופי\u0004 \u0005[להם להצטרף]\u0006 לאיסור? הרי ביותר מארבעה הם עצמם פסולים! ו\u0003אי דלית בהו\u0004 \u0005[אם כשאין בהם]\u0006 \u0003ארבעה\u0004 טפחים בכל אחד, \u0003אמאי\u0004 \u0005[מדוע]?\u0006 \u0003והא קנים בעלמא נינהו\u0004 \u0005[הרי קנים בלבד הם]\u0006 לשיטת רב וכשם שאפשר לסכך בקנים, מדוע לא יסככו בנסרים צרים אפילו לדעת ר' מאיר?","ומשיבים: \u0003לעולם\u0004 תפרש \u0003דאית בהו\u0004 \u0005[שיש בהם,\u0006 בכל אחד מהם\u0005],\u0006 \u0003ארבעה\u0004 טפחים ואכן, כל אחד מהם פסול לעצמו. אולם \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"מצטרפין\"\u0004 שאמרו — הריהו לענין אחר, לומר כי \u0003מצטרפין לארבע אמות מן הצד.\u0004 כלומר: אם סיכך בנסרים הללו ברוחב ארבע אמות בסמוך לדופן הסוכה הרי הנסרים הפסולים מצטרפין יחד כדי לפוסלה. אולם אם אין בכולם יחד כדי שטח ארבע אמות, הרי הם נעשים כהמשך הדופן על פי דין \"דופן עקומה\", והסוכה כולה כשרה. ובכך אם כן אפשר ליישב גם את דברי רב.","\u0003לישנא אחרינא\u0004 \u0005[לשון אחרת]\u0006 של הדיון על פי ברייתא זו, היתה בצורה הבאה: \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003ל\u0004שיטת \u0003שמואל\u0004 ש\u0003אמר\u0004 כי \u0003בשאין בהן ארבעה\u0004 טפחים \u0003מחלוקת, אבל\u0004 כש\u0003יש בהן ארבעה דברי הכל פסולה — מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"מצטרפין\" — מצטרפין לארבע אמות מן הצד\u0004 לפסול את הסוכה.","\u0003אלא לרב,\u0004 כיצד נבין את הברייתא? \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003ל\u0004שיטת \u0003ר' מאיר,\u0004 לדברי רב, \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"מצטרפין\"\u0004 — \u0003מצטרפין לארבע אמות מן הצד. אלא ל\u0004דברי \u0003ר' יהודה\u0004 ש\u0003אמר\u0004 כי \u0003אפילו\u0004 כש\u0003יש בהן ארבעה\u0004 טפחים הריהי \u0003כשרה, מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"אין מצטרפין\"?\u0004 מה מקום למחלוקת זו, הלא \u0003קנים בעלמא נינהו\u0004 \u0005[בלבד הם]\u0006 לשיטתו, וקנים בלבד שהם כשרים לסיכוך, הרי לא שייך בהם דין צירוף לשום פסול! ומשיבים: \u0003איידי דקאמר\u0004 \u0005[על ידי,\u0006 מתוך, \u0005שאמר]\u0006 \u0003ר' מאיר\u0004 לשון \u0003\"מצטרפין\", אמר ר' יהודה\u0004 גם הוא לשון \u0003\"אין מצטרפין\",\u0004 אבל לדיוקו של דבר אכן אין מקום ללשון זו. שלפי שאין בהם איסור מעיקרם, שוב אין שייך בהם דין צירוף.","ומעירים: \u0003תניא כוותיה\u0004 \u0005[שנויה\u0006 ברייתא \u0005כשיטתו]\u0006 של \u0003רב\u0004 וכן \u0003תניא כוותיה\u0004 \u0005[שנויה\u0006 ברייתא אחרת \u0005כשיטתו]\u0006 של \u0003שמואל.\u0004","\u0003תניא כוותיה\u0004 \u0005[שנויה\u0006 ברייתא \u0005כשיטתו]:\u0006 של \u0003רב: סככה בנסרים של ארז שאין בהן ארבעה\u0004 טפחים — \u0003דברי הכל כשרה. יש בהן ארבעה\u0004 — \u0003ר' מאיר פוסל ור' יהודה מכשיר.\u0004","\u0003אמר ר' יהודה: מעשה בשעת הסכנה\u0004 שהיתה גזירה על ישראל שלא לעשות סוכות \u0003שהביאנו נסרים שהיו בהן ארבעה\u0004 טפחים \u0003וסיככנו\u0004 בהם \u0003על גבי מרפסת,\u0004 שלא יראה הדבר כסוכה, \u0003וישבנו תחתיהן,\u0004 הרי שנסרים אלה כשרים לסוכה! \u0003אמרו לו: משם\u0004 מביא אתה \u0003ראיה?! אין שעת הסכנה ראיה,\u0004 כי יתכן שבאמת היתה הסוכה פסולה, ולא עשו כן אלא לעשות זכר למצוה. ומברייתא זו רואים שנחלקו בנסרים רחבים מארבעה טפחים, וכדברי רב.","אכן גם \u0003תניא כוותיה\u0004 \u0005[שנויה\u0006 ברייתא \u0005כשיטתו]\u0006 של \u0003שמואל: סככה בנסרים של ארז שיש בהן ארבעה\u0004 טפחים \u0003— דברי הכל פסולה. אין בהן ארבעה — ר' מאיר פוסל ור' יהודה מכשיר. ומודה ר' מאיר שאם יש בין נסר לנסר\u0004 מן הנסרים הפסולים מקום פנוי \u0003כמלא\u0004 שטח ה\u0003נסר\u0004 עצמו — \u0003שמניח פסל\u0004 (כלומר: סכך כשר שהוא מפסולת גורן ויקב) \u0003ביניהן, וכשרה\u0004 הסוכה כולה. \u0003ומודה ר' יהודה שאם נתן עליה\u0004 מן הצד \u0003נסר שהוא רחב ארבעה טפחים\u0004 שאמנם הסוכה בכללה \u0003כשרה\u0004 מדין דופן עקומה, אבל מכל מקום \u0003אין ישנים תחתיו, והישן תחתיו\u0004 — \u0003לא יצא ידי חובתו.\u0004 ואם כן, קיימות איפוא שתי ברייתות, שבכל אחת מפורש כאחת מן השיטות הללו.","\u0003אתמר\u0004 \u0005[נאמר]\u0006 שחלקו אמוראים בבעיה הבאה: \u0003הפכן\u0004 את הנסרים הפסולים \u0003על צידיהן,\u0004 ורוחב צידיהן פחות מן השיעור הפסול, האם עדיין פסולים הם לסיכוך, או שמא כעת שרוחבם קטן יותר, הרי הם מותרים? \u0003רב הונא אמר: פסולה\u0004 הסוכה, \u0003ורב חסדא ורבה בר רב הונא אמרי\u0004 \u0005[אמרו]:\u0006 \u0003כשרה.\u0004","מסופר: \u0003איקלע\u0004 \u0005[הזדמן]\u0006 \u0003רב נחמן לסורא, עול לגביה\u0004 \u0005[נכנסו אליו]\u0006 \u0003רב חסדא ורבה בר רב הונא. אמרי ליה\u0004 \u0005[אמרו לו]:\u0006 נסרים אלה, אם \u0003הפכן על צידיהן\u0004 וסיכך בהם, \u0003מהו\u0004 דין הסוכה? כי רצו לברר אם יפסוק כשיטתם. \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003פסולה,\u0004 שכיון שהם פסולים בצידם האחד, \u0003נעשו\u0004 (נחשבים) נסרים אלה \u0003כשפודין של מתכת\u0004 ואסורים בכל מקרה.","לאחר זמן כשסיפרו את הדבר לרב הונא, \u0003אמר להו\u0004 \u0005[להם]\u0006 \u0003רב הונא:\u0004 האם \u0003לא אמרי לכו\u0004 \u0005[אמרתי לכם];\u0006 \u0003אמרי כוותי\u0004 \u0005[אמרו כמותי]?\u0006 שהרי רואים אתם שגם רב נחמן סבור כן. \u0003אמרו ליה\u0004 \u0005[לו]:\u0006 \u0003ומי אמר לן מר טעמא ולא קבלינן מיניה\u0004 \u0005[האם אמר לנו אדוני טעם\u0006 להלכה זו ולא \u0005קבלנו ממנו]?\u0006 שהרי רב נחמן לא רק פסק הלכה אלא גם נתן לנו טעם. \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003ומי בעיתו מינאי טעמא ולא אמרי לכו\u0004 \u0005[האם שאלתם ממני טעם ולא אמרתי לכם]?\u0006","ומעירים: \u0003לימא מסייע ליה\u0004 \u0005[האם לומר\u0006 כי יש מקום \u0005לסייע לו]\u0006 לרב הונא מברייתא זו: סוכה ש\u0003אינה מחזקת\u0004 בשיעורה \u0003כדי ראשו ורובו ושולחנו\u0004 של אדם, \u0003או שנפרצה בה פרצה\u0004 גדולה עד \u0003כדי שיזדקר\u0004 (יקפוץ) \u0003בה גדי בבת ראש\u0004 (בבת אחת) שהוא כשיעור שלושה טפחים, \u0003או שנתן עליה\u0004 על סוכה זו \u0003נסר שהוא רחב ארבעה טפחים, אף על פי שלא הכניס לתוכה אלא שלשה טפחים\u0004 של הנסר — \u0003פסולה.\u0004","ולכאורה \u0003היכי דמי\u0004 \u0005[כיצד הוא\u0006 בדיוק\u0005]\u0006 היה הדבר שהכניס שלושה טפחים מנסר שרוחבו ארבעה? \u0003לאו\u0004 \u0005[האם לא]\u0006 \u0003כגון שהפכן על צידיהם\u0004 ועל ידי כך נעשה רוחבן שלושה בלבד, והרי זה כדברי רב הונא! ודוחים: \u0003לא, הכא במאי עסקינן כגון\u0004 \u0005[כאן במה אנו עוסקים]\u0006 \u0003דאנחה אפומא דמטללתא\u0004 \u0005[שהניח\u0006 את הנסר הזה \u0005על פי,\u0006 על פתח, \u0005הסוכה],\u0006 בצד שאין בו דופן, \u0003דעייל תלתא לגיו ואפיק חד לבר\u0004 \u0005[שהכניס שלושה\u0006 טפחים מן הנסר \u0005בפנים והוציא\u0006 טפח \u0005אחד החוצה]\u0006 \u0003דהוה ליה\u0004 \u0005[שנעשה]\u0006 נסר זה כ\u0003פסל\u0004 (סכך) \u0003היוצא מן הסוכה,\u0004 וכלל הוא ש\u0003כל פסל היוצא מן הסוכה — נידון כסוכה.\u0004 וכיון שאי אפשר להכשירו ולהחשיבו כדופן מדין דופן עקומה, שהרי אין בצד זה של הסוכה דופן כלל, לכך הריהו נידון כסכך וכיון שהוא סכך פסול ואסור לישון תחתיו, פסולה הסוכה בגללו. ואם כן אין מכאן ראיה לדברי רב הונא, אף כי אין מכאן גם ראיה לסתור."],["\u0003תקרה\u0004 העשויה נסרים רחבים ארבעה טפחים \u0003שאין עליה מעזיבה\u0004 (ציפוי של טיט ועפר) \u0003ר' יהודה אומר:\u0004 נחלקו בכך בית שמאי ובית הלל, \u0003בית שמאי אומרים: מפקפק\u0004 מנענע את כולם שיהיו כמו שהונחו לשם מצות סוכה \u0003ונוטל אחת מבינתים\u0004 ומניח במקומה סכך כשר. \u0003ובית הלל אומרים:\u0004 אין צורך בשניהם גם יחד, אלא \u0003מפקפק, או נוטל אחת מבינתים. ר' מאיר אומר: נוטל אחת מבינתים ואינו מפקפק.\u0004","ושואלים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 כי \u0003בית הלל, טעמייהו\u0004 \u0005[טעמם]\u0006 לאסור תיקרה זו שאין עליה מעזיבה, הוא \u0003משום \"תעשה\" ולא מן העשוי.\u0004 ולכן \u0003אי\u0004 \u0005[אם]\u0006 \u0003מפקפק, עביד ליה\u0004 \u0005[עושה הוא\u0006 בכך\u0005]\u0006 \u0003מעשה\u0004 של תיקון לענין זה, וכן \u0003אי\u0004 \u0005[אם]\u0006 \u0003נוטל אחת מבינתים עבד בה\u0004 \u0005[עושה בה]\u0006 \u0003מעשה. אלא בית שמאי, מאי טעמייהו\u0004 \u0005[מה טעמם]?\u0006 הלא \u0003אי\u0004 \u0005[אם]\u0006 טעמם הוא \u0003משום \"תעשה\" ולא מן העשוי,\u0004 אם כן \u0003בחדא סגי\u0004 \u0005[באחת\u0006 מאלה \u0005די],\u0006 ו\u0003אי\u0004 \u0005[אם]\u0006 \u0003משום גזירת תקרה\u0004 שגוזרים איסור בקירוי זה כדי שלא יבואו לשבת מתחת לתקרת בית רגילה שיש עליה מעזיבה, אם כן \u0003בנוטל אחת מבינתים סגי\u0004 \u0005[די]!\u0006","ומשיבים: \u0003לעולם\u0004 הטעם הוא \u0003משום גזרת תקרה, והכי קאמרי\u0004 \u0005[וכך אמרו],\u0006 כך יש להבין את דבריהם: \u0003אף על פי שמפקפק, אי\u0004 \u0005[אם]\u0006 \u0003נוטל אחת מבינתים, אין\u0004 \u0005[כן],\u0006 כשר, \u0003אי\u0004 \u0005[אם]\u0006 \u0003לא — לא.\u0004","ומקשים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 \u0003אימא סיפא\u0004 \u0005[אמור את סופה]\u0006 של המשנה; \u0003ר' מאיר אומר: נוטל אחת מבינתים אבל לא יפקפק.\u0004 ולפי מה שהסברנו, הרי \u0003ר' מאיר היינו בית שמאי,\u0004 שהרי סבור הוא שרק בתיקון זה שיש בו כדי לבטל גזירת תיקרה מותר, כשיטת בית שמאי הדחויה מן ההלכה!","ומשיבים: \u0003הכי קאמר\u0004 \u0005[כך אמר]\u0006 ר' מאיר: \u0003לא נחלקו בית שמאי ובית הלל בדבר זה,\u0004 אלא הסכימו כולם לאסור משום גזירת תיקרה ולשיטתו, דעתו היא אף כבית הלל.","ושואלים: \u0003מאי קא משמע לן\u0004 \u0005[מה השמיע לנו]\u0006 איפוא במחלוקת זו, ש\u0003ר' מאיר אית ליה\u0004 \u0005[יש לו,\u0006 מקבל\u0005]\u0006 \u0003גזרת תקרה, ור' יהודה לית ליה\u0004 \u0005[אין לו,\u0006 אינו מקבל\u0005]\u0006 \u0003גזרת תקרה.\u0004 אולם בכך אין הלא כל חידוש, \u0003והא אפליגו בה חדא זימנא\u0004 \u0005[והרי נחלקו בכך\u0006 בשאלה זו עצמה \u0005פעם אחת]\u0006 \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003מסככין בנסרים.\u0004 אלו \u0003דברי ר' יהודה. ור' מאיר אוסר.\u0004 וכבר הסברנו שהמחלוקת היא אם מקבלים את גזירת תיקרה!","\u0003אמר ר' חייא בר אבא אמר ר' יוחנן:\u0004 אינו כן, כי \u0003רישא\u0004 \u0005[בראש\u0006 אותה משנה\u0005]\u0006 שנחלקו בנסרים — \u0003בנסרים משופין עסקינן\u0004 \u0005[מוחלקים\u0006 ומהוקצעים \u0005עוסקים אנו]\u0006 ושם לא משום גזירת תיקרה, אלא \u0003משום גזרת כלים נגעו בה.\u0004 שנחלקו בבעיה אחרת: האם נסרים שנעשה בהם תיקון מסויים נחשבים ככלים ופסולים לשמש כסכך.","ומקשים: \u0003ו\u0004לדעת \u0003ר' יהודה אמר רב,\u0004 ש\u0003אמר: סככה\u0004 לסוכה \u0003בחיצין זכרים,\u0004 שסיכך את הסוכה בידות חצים עשויות עץ שהן כקנים חלקים בלבד — הרי זו \u0003כשרה,\u0004 כיון שהם פשוטי כלי עץ, וכלי עץ שאין להם בית קיבול אינם מקבלים טומאה. אולם אם סיככה בחיצין \u0003נקבות,\u0004 בעץ של חיצים כאשר ראש החץ העשוי מתכת נכנס בתוך בית קיבול העשוי בתוך העץ — הרי זו \u0003פסולה, ולא גזר\u0004 חיצים \u0003זכרים אטו\u0004 \u0005[משום]\u0006 חיצים \u0003נקבות. הכא נמי\u0004 \u0005[כאן גם כן]\u0006 \u0003לא נגזר נסרים משופין אטו\u0004 \u0005[משום]\u0006 \u0003כלים!\u0004","\u0003אלא\u0004 לשיטת רב \u0003על כרחך רישא פליגי\u0004 \u0005[בראש,\u0006 במשנה ראשונה, \u0005חלוקים\u0006 הם\u0005]\u0006 \u0003בגזרת תקרה, וסיפא פליגי\u0004 \u0005[ובסוף,\u0006 במשנתנו \u0005חלוקים\u0006 הם\u0005]\u0006 גם כן \u0003בגזרת תקרה.\u0004 וחזרה השאלה למקומה: \u0003ואפליגי בתרתי זימני\u0004 \u0005[ולחלוק בשתי פעמים]\u0006 \u0003למה לי?\u0004","ומשיבים: \u0003סיפא\u0004 \u0005[בסופה,\u0006 במשנתנו\u0005]\u0006 יש לפרש כי דברי \u0003ר' יהודה היא דקאמר ליה\u0004 \u0005[שאומר הוא]\u0006 \u0003לר' מאיר\u0004 כך: \u0003אמאי קא אסרת\u0004 \u0005[מדוע אוסר אתה]\u0006 \u0003בנסרים\u0004 — \u0003משום גזרת תקרה,\u0004 אולם \u0003האי סברא\u0004 \u0005[סברה זו]\u0006 \u0003לבית שמאי הוא דאית להו\u0004 \u0005[הוא שיש להם],\u0006 שהרי הם המקבלים את הגזירה הזו, ואילו \u0003בית הלל לא גזרי\u0004 \u0005[גזרו]\u0006 משום תיקרה, ואם כן בטלה אף דעתך! \u0003ואמר ר' מאיר\u0004 במשנתנו: לא כן, אלא \u0003לא נחלקו בית שמאי ובית הלל בדבר זה,\u0004 ואם כן לא שתי מחלוקות הן, אלא המשכה של מחלוקת אחת בלבד.","וממשיכים להקשות: \u0003הניחא\u0004 \u0005[זה נוח]\u0006 לשיטת \u0003רב,\u0004 ש\u0003אמר: מחלוקת\u0004 בנסרים, היא \u0003בשיש בהן ארבעה\u0004 טפחים, ש\u0003ר' מאיר\u0004 מקבל את \u0003גזרת תקרה ו\u0004אילו \u0003ר' יהודה לית ליה\u0004 \u0005[אין לו]\u0006 \u0003גזרת תקרה. אלא לשמואל,\u0004 ש\u0003אמר\u0004 כי \u0003בשאין בהן ארבעה\u0004 טפחים \u0003מחלוקת, אבל\u0004 כש\u0003יש בהן ארבעה\u0004 טפחים \u0003דברי הכל פסולה,\u0004 ולשיטתו הכל מודים בגזירת תיקרה, אם כן \u0003סיפא במאי פליגי\u0004 \u0005[בסופה\u0006 של המשנה, המשנה שלנו, \u0005במה הם חלוקים]?\u0006","ומשיבים: אכן אם בא לסכך בהם מלכתחילה, אף לשיטת ר' יהודה הסוכה פסולה משום גזירת תיקרה, אולם \u0003בביטולי\u0004 \u0005[\u0006בשאלה \u0005מה\u0006 עושים כדי \u0005לבטל]\u0006 \u0003תקרה\u0004 קיימת העשוייה מנסרים כאלו ולהכשירם כסכך \u0003קא מיפלגי\u0004 \u0005[נחלקו];\u0006 \u0003מר\u0004 \u0005[חכם זה,\u0006 ר' יהודה\u0005]\u0006 \u0003סבר\u0004 כי \u0003בטלה\u0004 התיקרה \u0003בהכי\u0004 \u0005[בכך],\u0006 בפקפוק בלבד, \u0003ומר\u0004 \u0005[וחכם זה,\u0006 ר' מאיר\u0005]\u0006 \u0003סבר\u0004 כי \u0003בהכי\u0004 \u0005[בכך]\u0006 בפקפוק בלבד \u0003לא בטלה\u0004 וצריך ליטול אחת מבינתים.","\u0003המקרה סוכתו בשפודין\u0004 (מוטות של מתכת) \u0003או בארוכות המטה,\u0004 כלומר: במוטות הארוכים שהם חלק ממסגרת המיטה, שמקבלים טומאה, \u0003אם יש ריוח ביניהן\u0004 בין המוטות הללו \u0003כמותן\u0004 לכל אורך הסוכה, ובריוח זה הוא מניח סכך כשר — הרי סוכה זו \u0003כשרה. החוטט\u0004 (העושה חור) \u0003בגדיש\u0004 של התבואה \u0003לעשות לו סוכה\u0004 בתוכו — \u0003אינה סוכה.\u0004","על סמך משנתנו שואלים: \u0003לימא תיהוי תיובתא\u0004 \u0005[האם נאמר שתהא\u0006 במשנתנו זו \u0005קושיה חמורה]\u0006 לדברי \u0003רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע. דאתמר\u0004 \u0005[שנאמר]\u0006 שנחלקו בנושא זה: \u0003פרוץ כעומד,\u0004 כלומר: מחיצה, גדר, או כל דבר אחר, שפרצותיו (החלק הריק או השבור שבו) הם בדיוק כשיעור החלק הקיים (\"העומד\") שבו, האם דינו כדבר שלם ויוצר בכך רשות עצמאית (כגון לענין הטלטול במקום זה בשבת), או דינו כפרוץ? \u0003רב פפא אמר: מותר,\u0004 שכל עוד שלא רב הפרוץ על העומד, הרי זה נחשב כולו כעומד. \u0003ורב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע אמר: אסור\u0004 עד שיהא העומד מרובה. ולכאורה מלשון משנתנו אפשר להסיק שאם הסכך הכשר שווה בדיוק לשטח השפודים הפסולים עצמם, הרי זה כשר, ובניגוד לדברי רב הונא בנו של רב יהושע!","ומשיבים: \u0003אמר\u0004 \u0005[יכול היה לומר]\u0006 \u0003לך רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע: מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003כמותן\u0004 — \u0003בנכנס ויוצא\u0004 שהכוונה במשנה היא שאין הרווח שווה ממש, אלא הריווח שבין השיפודים גדול מעט יותר, כדי שיוכל הסכך הכשר להיות נכנס ויוצא בקלות. משמע שרק מפני שהכשר מרובה מעט על הפסול הרי זה כשר."],["\u0003והא\u0004 \u0005[והרי]\u0006 \u0003אפשר לצמצם\u0004 (לדייק). כלומר: אין הכרחי שיהא הריוח גדול יותר, שהרי אפשר לדייק ולעשות שיהא הרווח ביניהן בדיוק כמותן, והמשנה לא דרשה יותר! \u0003אמר ר' אמי:\u0004 הכוונה היא \u0003במעדיף,\u0004 כלומר: המשנה אינה מכשירה אלא באופן שהוא עושה במכוון את הרווח גדול מעט מן השיפודים.","\u0003רבא אמר: אפילו תימא\u0004 \u0005[תאמר]\u0006 כי המשנה מכשירה אף \u0003בשאין מעדיף,\u0004 אלא כך עושה: \u0003אם היו נתונים\u0004 השפודים \u0003שתי\u0004 — \u0003נותנן\u0004 לסכך הכשר \u0003ערב,\u0004 היו נתונים \u0003ערב\u0004 — \u0003נותנן שתי,\u0004 וכדי שיוכלו אלה להשאר על גבי השפודים בלא ליפול חייב שירבה הסכך הכשר על הפסול.","שנינו במשנה שאם מסככה \u0003בארוכות המטה,\u0004 הרי זו פסולה. ומציעים: \u0003לימא מסייע ליה\u0004 \u0005[\u0006האם \u0005נאמר\u0006 שמשנה זו \u0005מסייעת לו]\u0006 \u0003לר' אמי בר טביומי,\u0004 ש\u0003אמר ר' אמי בר טביומי:\u0004 סוכה ש\u0003סככה בבלאי כלים,\u0004 כלומר: בשברי כלים — \u0003פסולה.\u0004 שאף ששברי כלים אינם מקבלים עוד טומאה, אולם מאחר שסכך זה בא מדבר שהיה פעם פסול — הריהו פסול לעולם. וראיה ממשנתנו, שהרי ארוכות המיטה אינן עוד כלי לעצמן אלא שבר כלי בלבד, ובכל זאת הריהן פסולות!","ודוחים: יש לפרש כאן \u0003כדאמר\u0004 \u0005[כפי שאמר]\u0006 בענין אחר \u0003ר' חנן אמר רבי:\u0004 שמדובר כאן לא בארוכות המיטה בלבד, אלא או \u0003בארוכה ושתי כרעים\u0004 הצמודות לה, או \u0003בקצרה ושתי כרעים\u0004 הצמודות לה, שאפשר להעמידן סמוך לקיר ולהשתמש בהן כעין מיטה, \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 מדובר \u0003בארוכה ושתי כרעים, בקצרה ושתי כרעים.\u0004 ואם כן אפשר לומר שבמשנתנו מדבר בארוכות המיטה כשהן עדיין בגדר כלי ממש, ולא שבר כלי.","ושואלים: \u0003היכא איתמר\u0004 \u0005[היכן נאמר]\u0006 במקורו ענין זה של \u0003ר' חנן אמר רבי?\u0004 ומשיבים: \u0003אהא דתנן\u0004 \u0005[על זו ששנינו\u0006 במשנה\u0005]:\u0006"],["\u0003מטה מטמאת חבילה,\u0004 כלומר: בשלימותה, שמיטה שלימה שנגעה בדבר טמא נטמאת כולה, וכן \u0003מטהרת\u0004 מן הטומאה בטבילה או בהזיה (מטומאת המת) כשהיא \u0003חבילה\u0004 (בשלימותה), אבל לא כשהיא מפורקת, אלו \u0003דברי ר' אליעזר. וחכמים אומרים:\u0004 מיטה \u0003מטמאת\u0004 אפילו כשהיא מפורקת ל\u0003אברים ו\u0004כמו כן אף \u0003מטהרת\u0004 כשהיא מפורקת ל\u0003אברים.\u0004 ושאלו \u0003מאי ניהו\u0004 \u0005[מה הם]\u0006 איברים אלה? שהרי אם נשברה המיטה לחלקים שאינם משמשים לכלום, הריהי נטהרת בעצם שבירתה! \u0003אמר ר' חנן אמר רבי:\u0004 מדובר פה ב\u0003ארוכה\u0004 כלומר: במוטות הארוכים שהם חלק ממסגרת המיטה \u0003ושתי כרעים\u0004 הצמודות להן, או ב\u0003קצרה ושתי כרעים.\u0004","ושואלים: \u0003למאי חזיא\u0004 \u0005[למה ראוי]\u0006 חלק זה של המיטה שייחשב עדיין ככלי? ומשיבים: \u0003למסמכינהו אגודא ולמיתב עלייהו\u0004 \u0005[לסמוך אותם\u0006 ארוכות המיטה \u0005לקיר ולשבת עליהם]\u0006 אחר שיניח קרשים לכל אורכם \u0003ומשדא אשלי\u0004 \u0005[ולתת חבלים]\u0006 עליהם ולסרגם שתי וערב, ובכך היא נעשית ראויה לישיבה ושכיבה וחשובה ככלי.","\u0003גופא,\u0004 עתה שבים לדון בגופה של ההלכה ש\u0003אמר ר' אמי בר טביומי: סככה בבלאי כלים פסולה.\u0004 ושואלים: \u0003מאי\u0004 \u0005[מה\u0006 הם\u0005]\u0006 \u0003בלאי כלים\u0004 אלה? \u0003אמר אביי: מטלניות\u0004 מטליות בד קטנות \u0003שאין בהן שלש על שלש\u0004 אצבעות, \u0003דלא חזיין\u0004 \u0005[שאינן ראויות]\u0006 מפני קטנותן לשימוש \u0003לא לעניים ולא לעשירים.\u0004","ומעירים: \u0003תניא כוותיה\u0004 \u0005[שנויה\u0006 ברייתא \u0005כשיטתו]\u0006 של \u0003ר' אמי בר טביומי: מחצלת\u0004 העשוייה ממיני עשב, כגון: \u0003של שיפא ושל גמי\u0004 — \u0003שיריה, אף על פי שנפחתו מכשיעורה\u0004 לענין קבלת טומאה ושוב אינם מטמאים בעצמם — מכל מקום \u0003אין מסככין בהן,\u0004 ממש כשיטת ר' אמי.","ועוד אמרו שם: \u0003מחצלת הקנים,\u0004 אם היתה \u0003גדולה,\u0004 שאינה עשויה לשכב עליה, ואינה ראויה אלא לסכך — \u0003מסככין בה. קטנה,\u0004 הראוייה אף לשכיבה ונחשבת ככלי — \u0003אין מסככין בה. ר' אליעזר אומר: אף היא\u0004 המחצלת הגדולה נחשבת ככלי ו\u0003מקבלת טומאה, ואין מסככין בה.\u0004","נאמר במשנה ש\u0003החוטט\u0004 (העושה חור) \u0003בגדיש\u0004 ועשה שם מעין סוכה אינה סוכה. \u0003אמר רב הונא: לא שנו\u0004 שאינה סוכה, \u0003אלא\u0004 כ\u0003שאין שם\u0004 בגדיש מתחילת עשייתו \u0003חלל\u0004 בגובה \u0003טפח במשך\u0004 (באורך) \u0003שבעה\u0004 טפחים. \u0003אבל\u0004 אם \u0003יש שם חלל טפח במשך שבעה,\u0004 שעשה מתחילה כעין חלל קטן בפנים, ורק לאחר מכן עשה מעליו את הגדיש, כיון שאינו יוצר בחטיטתו דבר חדש אלא רק מרחיב ומגביה את הדפנות הקיימים — \u0003הרי זה סוכה\u0004 כשרה.","ומעירים: \u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך]:\u0006 \u0003החוטט בגדיש לעשות לו סוכה — הרי זה סוכה.\u0004 ויש לתהות: \u0003והאנן תנן\u0004 \u0005[והרי אנו שנינו]\u0006 במשנה כי \u0003אינה סוכה! אלא לאו שמע מינה\u0004 \u0005[האם לא תלמד מכאן]\u0006 \u0003כ\u0004שיטת \u0003רב הונא,\u0004 שקיים אופן שאפשר לעשות חור בגדיש ושתהא סוכה כשרה. ומסכמים: אכן, \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שכן הוא.","\u0003איכא דרמי ליה מירמא\u0004 \u0005[יש שהשליך אותה],\u0006 כלומר: גרס שמועה זו בדרך הצגת סתירה בין הדברים. \u0003תנן\u0004 \u0005[שנינו]\u0006 במשנה: \u0003החוטט בגדיש לעשות לו סוכה — אינה סוכה. והא תניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003הרי זו סוכה! אמר רב הונא: לא קשיא\u0004 \u0005[אינו קשה],\u0006 \u0003כאן — בשיש שם חלל טפח במשך שבעה\u0004 טפחים. \u0003כאן בשאין שם חלל טפח במשך שבעה\u0004 טפחים.","\u0003המשלשל דפנות\u0004 של הסוכה \u0003מלמעלה למטה, אם גבוה\u0004 תחתית הדופן \u0003מן הארץ שלשה טפחים\u0004 — הרי זו \u0003פסולה,\u0004 שהרי עדיין יכולים בעלי חיים להכנס שם ואין דופן כזו נחשבת. אולם אם עושה דפנות ובונה אותם \u0003מלמטה למעלה, אם גבוה\u0004 הדופן עצמו \u0003עשרה טפחים,\u0004 אף אם אינו מגיע לגובה הסכך — הרי זו \u0003כשרה. ר' יוסי אומר: כשם\u0004 שאם בונה \u0003מלמטה למעלה\u0004 די בדופן שגובהה \u0003עשרה טפחים, כך\u0004 אם משלשל את הדפנות \u0003מלמעלה למטה\u0004 אם היו בגובה הדופן \u0003עשרה טפחים\u0004 — הרי זו כשרה, כיון שדופן זו יש לה דין מחיצה גמורה לכל ענין.","ושואלים: \u0003במאי קמיפלגי\u0004 \u0005[במה,\u0006 באיזה עיקרון \u0005נחלקו]\u0006 חכמים ור' יוסי? ומסבירים: \u0003מר\u0004 \u0005[חכם זה,\u0006 ר' יוסי\u0005]\u0006 \u0003סבר\u0004 כי \u0003מחיצה תלויה\u0004 גם אם אינה מגיעה עד למטה \u0003מתרת\u0004 ככל מחיצה, \u0003ומר\u0004 \u0005[וחכם זה,\u0006 החכמים בסתם משנה\u0005]\u0006 \u0003סבר\u0004 כי \u0003מחיצה תלויה אינה מתרת.\u0004","\u0003תנן התם\u0004 \u0005[שנינו שם]\u0006 במסכת עירובין: \u0003בור\u0004 שהיה מצוי \u0003בין שתי חצרות\u0004 שגדר מפרידה ביניהן ועוברת (תלויה) מעל פי הבור — \u0003אין ממלאין ממנו\u0004 מן הבור מים \u0003בשבת,\u0004 כיון שמי הבור אינן מחולקים על ידי מחיצה ושייכים לשתי החצירות, ואם אין עירוב ביניהן, השואב משם הרי הוא כמטלטל מחצר לחצר, \u0003אלא אם כן עשה לה\u0004 לבור עצמו \u0003מחיצה עשרה טפחים\u0004 להבדיל בין החלקים השייכים לכל חצר. \u0003בין\u0004 שהיתה המחיצה \u0003מלמעלה\u0004 ויורדת אל תוך המים \u0003בין מלמטה\u0004 שהעמידה בתוך המים, \u0003בין בתוך אוגנו\u0004 במקום אחר בחללו של הבור אף בלא שתיגע במים. שמחיצה כשרה הקבועה באחד מן המקומות הללו, יוצרת גבול בין שתי החצירות. \u0003רבן שמעון בן גמליאל אומר:\u0004"],["\u0003בית שמאי אומרים:\u0004 מחיצה זו יכולה להיות \u0003מלמעלה\u0004 בכל גובה שהוא בתוך חלל הבור, \u0003ובית הלל אומרים\u0004 דווקא \u0003מלמטה\u0004 סמוך למים. \u0003אמר ר' יהודה: לא תהא מחיצה\u0004 שעושים בתוך הבור \u0003גדולה\u0004 וחשובה \u0003מן הכותל שביניהן\u0004 שבין החצרות עצמן, שהרי הכותל שבין החצרות עובר מעל לבור, ודי בכותל זה התלוי מעל למי הבור כדי לשמש כמחיצה.","\u0003אמר רבה בר בר חנה אמר ר' יוחנן: ר' יהודה\u0004 בנושא זה \u0003בשיטת ר' יוסי אמרה,\u0004 ש\u0003אמר\u0004 ש\u0003מחיצה תלויה מתרת,\u0004 ומשום כך, הכותל שבין החצרות, אף שהוא תלוי ועובר מעל הבור, הריהו מועיל לחלק אף את הבור.","ודוחים: \u0003ולא היא,\u0004 ואין הדבר כן, שהשוואת השיטות אינה נכונה, ואפשר לומר כי \u0003לא ר' יהודה סבר לה\u0004 \u0005[סבור]\u0006 \u0003כר' יוסי, ולא ר' יוסי סבר לה\u0004 \u0005[סבור]\u0006 \u0003כר' יהודה.\u0004","ומבארים: \u0003לא ר' יהודה סבר לה כר' יוסי,\u0004 כי \u0003עד כאן לא\u0004 שמענו ש\u0003קאמר\u0004 \u0005[אמר]\u0006 \u0003ר' יהודה התם\u0004 \u0005[שם]\u0006 שמחיצה תלויה מתרת, \u0003אלא בעירובי חצרות\u0004 שהם \u0003דרבנן\u0004 \u0005[מדברי סופרים]\u0006 ולכן סבור הוא שמחיצה כזו מתירה בהם. \u0003אבל הכא\u0004 \u0005[כאן]\u0006 ב\u0003סוכה דאורייתא\u0004 \u0005[ש\u0006היא \u0005מן התורה]\u0006 \u0003לא\u0004 יתיר.","ולהיפך; \u0003ולא ר' יוסי סבר לה כר' יהודה,\u0004 כי \u0003עד כאן לא\u0004 שמענו ש\u0003קאמר\u0004 \u0005[אמר]\u0006 \u0003ר' יוסי הכא\u0004 \u0005[כאן]\u0006 \u0003אלא בסוכה\u0004 שאינה אלא \u0003מצות עשה, אבל\u0004 בדיני \u0003שבת\u0004 שהם חמורים, ובאופן כללי יש בהם \u0003איסור סקילה, לא\u0004 יודה שמחיצה תלויה מתרת. ואם כן אין להשוות את השיטות.","\u0003ואם תאמר:\u0004 כיון שר' יוסי אינו סובר בדין שבת כר' יהודה, אם כן \u0003מעשה שנעשה בציפורי\u0004 שסמכו על מחיצה תלויה לענין שבת בדבר שיש בו חיוב חמור מן התורה, \u0003על פי מי נעשה? לא על פי ר' יוסי, אלא על פי\u0004 בנו \u0003ר' ישמעאל בר' יוסי.\u0004","\u0003ומאי\u0004 \u0005[ומה]\u0006 היה אותו \u0003מעשה\u0004 — \u0003דכי אתא\u0004 \u0005[שכאשר בא]\u0006 \u0003רב דימי\u0004 מארץ ישראל לבבל, \u0003אמר: פעם אחת שכחו ולא הביאו ספר תורה מערב שבת\u0004 לבית הכנסת. וכיון שהיו צריכים להביא ספר תורה לקרוא בו ואסור לטלטל בשבת, עשו כך: \u0003למחר\u0004 בשבת \u0003פירסו\u0004 (תלו) \u0003סדינין על גבי העמודים\u0004 שהיו קבועים בדרך לבית הכנסת, ויצרו על ידי כך מחיצות בין הבית שבו היה מונח הספר לבין בית הכנסת \u0003והביאו ספר תורה\u0004 דרך המחיצות הללו \u0003וקראו בו.\u0004","על לשון הדברים שואלים: \u0003פירסו סלקא דעתך\u0004 \u0005[עולה על דעתך\u0006 לומר\u0005]?\u0006 זה ודאי אינו נכון, שהרי כיצד יכלו לעשות זאת, \u0003מהיכן הביאום בשבת?\u0004 שהרי אסור היה לטלטל שם, כאמור, וכיצד יכלו להביא את הסדינין? \u0003אלא\u0004 יש לומר שכך היה המעשה? \u0003מצאו סדינין פרוסין על גבי העמודים והביאו ספר תורה וקראו בו.\u0004 הרי שסמכו על מחיצה תלויה אפילו לדברי תורה. אולם דבר זה לא היה לא כשיטת ר' יהודה ולא כשיטת ר' יוסי, אלא לפי שיטה שלישית נעשה.","\u0003אמר רב חסדא אמר אבימי: מחצלת\u0004 שרוחבה \u0003ארבעה\u0004 טפחים \u0003ומשהו\u0004 — אפשר שתהא \u0003מתרת בסוכה משום דופן.\u0004 ומסבירים: \u0003היכי עביד\u0004 \u0005[כיצד הוא עושה\u0006 אותה\u0005]?\u0006 \u0003תלי ליה\u0004 \u0005[תולה אותה]\u0006 \u0003באמצע\u0004 של עשרה טפחים התחתונים \u0003פחות משלשה\u0004 טפחים \u0003למטה\u0004 לקרקע \u0003ופחות משלשה\u0004 טפחים \u0003למעלה\u0004 לסכך, וכלל הוא ש\u0003כל\u0004 חלל שהוא \u0003פחות משלשה\u0004 טפחים \u0003כלבוד\u0004 (צמוד) \u0003דמי\u0004 \u0005[נחשב],\u0006 ועל ידי ארבעה טפחים ומשהו אלה נחשב הכל כמחיצה בת עשרה טפחים.","ושואלים: הלא באופן זה \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן\u0005]\u0006 הדבר, ומה טעם לאומרו? ומשיבים: \u0003מהו דתימא\u0004 \u0005[שתאמר]\u0006 כי \u0003חד לבוד אמרינן\u0004 \u0005[לבוד אחד אומרים אנו]\u0006 שאנו מחשיבים כאילו המחיצה נמשכת מצד אחד, אולם \u0003תרי\u0004 \u0005[שני]\u0006 \u0003לבוד,\u0004 בשני צדדים שונים, \u0003לא אמרינן\u0004 \u0005[אין אנו אומרים],\u0006 על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שאין זה מעכב.","על עיקר דברי אבימי \u0003מיתיבי\u0004 \u0005[מקשים],\u0006 ממה ששנינו בברייתא: \u0003מחצלת שבעה ומשהו מתרת בסוכה משום דופן.\u0004 משמע: שבעה, אבל לא פחות משבעה! ומשיבים: \u0003כי תניא ההיא\u0004 \u0005[כאשר שנויה אותה\u0006 ברייתא\u0005],\u0006 הריהי שנויה \u0003בסוכה גדולה,\u0004 כלומר: סוכה הגבוהה הרבה מעשרה טפחים. ואם תולים את המחצלת סמוך לשלושה טפחים לסכך הרי היא נחשבת כיורדת עד למטה וכשרה, אף על פי שעדיין קיים רווח גדול בין תחתיתה לקרקע. \u0003ומאי קא משמע לן\u0004 \u0005[ומה השמיע לנו]\u0006 בכך — ש\u0003משלשלין דפנות מלמעלה למטה\u0004 כשיטת \u0003ר' יוסי.\u0004","כיון שהוזכר ענין זה של יצירת דופן לסוכה תוך שימוש בהלכות לבוד, מביאים מה ש\u0003אמר ר' אמי: פס\u0004 שרוחבו \u0003ארבעה\u0004 טפחים \u0003ומשהו\u0004 — \u0003מתיר בסוכה משום דופן.\u0004 כיצד \u0003מוקים ליה\u0004 \u0005[מעמיד\u0006 הוא \u0005אותו]\u0006 — \u0003בפחות משלשה טפחים סמוך לדופן\u0004 אחרת, \u0003וכל פחות משלשה\u0004 טפחים \u0003סמוך לדופן כלבוד דמי\u0004 \u0005[נחשב].\u0006","ושואלים: \u0003מאי קא משמע לן\u0004 \u0005[מה השמיע\u0006 ומחדש \u0005לנו\u0006 בכך\u0005]?\u0006 הרי יודעים אנו דין לבוד! ומשיבים: \u0003הא קא משמע לן\u0004 \u0005[\u0006דבר \u0005זה השמיע לנו];\u0006 ש\u0003שיעור משך\u0004 (אורך) \u0003סוכה קטנה שבעה\u0004 טפחים ואין צורך בשטח גדול יותר, ולכן ניתן ליצור דופן סוכה בפס ארבעה טפחים."],["\u0003הרחיק את הסיכוך מן הדפנות,\u0004 שאמנם הניח את הסכך בגובה הדפנות, אלא שהרחיקו מהם \u0003שלשה טפחים\u0004 — הסוכה \u0003פסולה,\u0004 שאויר שלושה טפחים אפילו מן הצד פוסל.","\u0003בית שנפחת\u0004 (שנעשה חור בגגו) \u0003ו\u0004כדי להכשירו לסוכה \u0003סיכך על גביו\u0004 (על החור) — \u0003אם יש מן הכותל לסיכוך\u0004 מרחק \u0003ארבע אמות,\u0004 הרי זו סוכה \u0003פסולה,\u0004 ובפחות מכן, הרי היא כשרה, שאנו מחשיבים את חלק התיקרה השלם כאילו הוא המשך עקום של הקיר (\"דופן עקומה\").","\u0003וכן, חצר שהיא מוקפת אכסדרה,\u0004 שהיא כעין מרפסת פתוחה בעלת גג, אם מסכך על החלל שבין האכסדראות, והיה גג האכסדראות רחב, וכן \u0003סוכה גדולה שהקיפוה\u0004 על גביה והניחו שם סמוך לדפנותיה \u0003בדבר שאין מסככין בו,\u0004 כגון דבר המקבל טומאה — \u0003אם יש תחתיו\u0004 (תחת החלק הפסול) \u0003ארבע אמות, פסולה,\u0004 שאז אין הקירות נחשבים כמצטרפים אל הסכך להיחשב כ\"דופן עקומה\".","ושואלים: \u0003כל הני\u0004 \u0005[כל\u0006 הדוגמאות \u0005האלה]\u0006 \u0003למה לי?\u0004 שלכאורה הן מבוססות על עיקרון אחד של הכשר דופן עקומה, ומה טעם להביא דוגמאות שונות לענין אחד? ומסבירים: \u0003צריכא\u0004 \u0005[נצרכו]\u0006 כל אלה; \u0003דאי אשמעינן\u0004 \u0005[שאילו היה משמיע לנו]\u0006 רק ב\u0003בית שנפחת,\u0004 הייתי אומר: \u0003משום דהני\u0004 \u0005[שאלה]\u0006 \u0003המחיצות לבית עבידן\u0004 \u0005[\u0006הן \u0005עשויות],\u0006 ולכן, לאחר שייעדו אותו לסוכה, נשארו מחיצות אלה במהותן ויכולות הן איפוא לשמש גם כדופן לסוכה. \u0003אבל חצר המוקפת אכסדרה, דמחיצות\u0004 (הבית, קירותיו החיצוניים) \u0003לאו לאכסדרה עבידי\u0004 \u0005[לא עבור האכסדרה הן עשויות],\u0006 אלא לצורך הבית נעשו, ורק בדרף אגב הן משמשות כקיר פנימי לאכסדרה, \u0003אימא\u0004 \u0005[אמור]\u0006 ש\u0003לא,\u0004 ולא ייחשבו איפוא כקשורות לסכך, על כן \u0003צריכא\u0004 \u0005[נצרכה]\u0006 לומר ולהביא גם את דין האכסדרה.","\u0003ואי אשמעינן הני תרתי\u0004 \u0005[ואילו היה משמיע לנו\u0006 ב\u0005שתי אלה]\u0006 היינו אומרים; \u0003משום\u0004 ש\u0003סככן\u0004 של סוכות אלה כולו \u0003סכך כשר הוא,\u0004 לכך יש לומר כי חלק התיקרה שלצד הסכך נעשה כמחובר לדופן ויש להכשירו משום דופן עקומה, \u0003אבל סוכה גדולה שהקיפוה בדבר שאין מסככין בו,\u0004 ש\u0003סככה\u0004 מקצתו \u0003סכך פסול הוא, אימא\u0004 \u0005[אמור]\u0006 ש\u0003לא\u0004 ואם אין הסכך מגיע ממש לדופן, הריהי פסולה, על כן \u0003צריכא\u0004 \u0005[נצרכו]\u0006 לומר ולהביא אף דוגמא זו ויש איפוא טעם להבאת כל המקרים.","\u0003אמר רבה: אשכחתינהו לרבנן דבי רב דיתבי וקאמרי\u0004 \u0005[מצאתי את חכמי בית\u0006 מדרשו של \u0005רב שיושבים ואומרים]\u0006 ומסכמים את ההלכה הבאה בשם רב: \u0003אויר,\u0004 כלומר: חלל בלא סכך, \u0003פוסל\u0004 את הסוכה \u0003בשלשה\u0004 טפחים, ואילו \u0003סכך פסול פוסל\u0004 רק \u0003בארבעה\u0004 טפחים.","\u0003ואמינא להו אנא\u0004 \u0005[ואמרתי להם אני]:\u0006 דבר זה ש\u0003אויר,\u0004 חלל, ש\u0003פוסל בשלשה\u0004 טפחים \u0003מנא לכו\u0004 \u0005[מניין לכם] —\u0006 \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנתנו\u0005]:\u0006 \u0003הרחיק את הסיכוך מן הדפנות שלשה טפחים\u0004 — \u0003פסולה.\u0004 ואם אכן המקור להלכה זו הוא דברי המשנה הזו, אם כן \u0003סכך פסול נמי לא ליפסיל\u0004 \u0005[גם כן\u0006 ש\u0005לא יפסול]\u0006 \u0003אלא בארבע אמות, דתנן\u0004 \u0005[שהרי\u0006 כך \u0005שנינו\u0006 במשנתנו זו\u0005]:\u0006 \u0003בית שנפחת וסיכך על גביו, אם יש בין הסיכוך לכותל ארבע אמות\u0004 — \u0003פסולה!\u0004","\u0003ואמרו לי\u0004 הם: \u0003בר מינה\u0004 \u0005[חוץ מזו]\u0006 של \u0003ההיא.\u0004 כלומר: אין להביא ראיה ממשנה זו לענייננו. כי \u0003רב ושמואל אמרי תרוייהו\u0004 \u0005[אמרו שניהם],\u0006 \u0003משום דופן עקומה נגעו בה,\u0004 כלומר: הטעם שבית זה כשר לסוכה אם הקירוי פחות מארבע אמות, אינו משום שסכך פסול אינו פוסל את הסוכה עד ארבע אמות, אלא משום שהתיקרה נחשבת כחלק מדופן הסוכה, והלכה מיוחדת היא זו שתיחשב התיקרה כדופן סוכה שהתעקמה.","\u0003ואמינא להו אנא\u0004 \u0005[ואמרתי להם אני]:\u0006 \u0003מה אילו איכא,\u0004 כלומר: מה תאמרו אילו תהיה סוכה שיש בה \u0003סכך פסול פחות מארבעה\u0004 טפחים ובסמוך לו יהיה \u0003אויר\u0004 (חלל ריק) \u0003פחות משלשה\u0004 טפחים \u0003מאי\u0004 \u0005[מה\u0006 יהא דינה\u0005]?\u0006 — לדעתכם תהא \u0003כשרה,\u0004 שהרי אין בה שיעור לפסול. אם \u0003מלייה\u0004 \u0005[מלאו]\u0006 את החלל הריק הזה \u0003בשפודין\u0004 שהן סכך פסול, \u0003מאי\u0004 \u0005[מה\u0006 יהא\u0005]\u0006 הדין — \u0003פסולה,\u0004 שהרי עכשיו יש סכך פסול יותר מארבעה טפחים, ולשיטתכם מגיעים אתם לידי מסקנה תמוהה, כי מדוע \u0003לא יהא אויר\u0004 שהוא פסול חמור יותר שהרי \u0003פוסל בשלשה\u0004 טפחים, \u0003כסכך פסול הפוסל\u0004 רק \u0003בארבעה\u0004 טפחים!","\u0003ואמרו לי\u0004 חכמי בית רב: \u0003אי הכי, לדידך נמי\u0004 \u0005[אם כך, לשיטתך גם כן]\u0006 אפשר להקשות כך; \u0003דאמרת\u0004 \u0005[שאתה אומר]\u0006 כי \u0003סכך פסול פוסל\u0004 רק \u0003בארבע אמות,\u0004 הרי \u0003מה אילו איכא\u0004 \u0005[יש]\u0006 \u0003סכך פסול\u0004 שהוא \u0003פחות מארבע אמות\u0004 וסמוך לו \u0003אויר פחות משלשה\u0004 טפחים, \u0003מאי\u0004 \u0005[מה יהא]\u0006 הדין? — הלא תהיה הסוכה לפי זה \u0003כשרה,\u0004 שהרי אין בה שיעור פסול, ואם \u0003מלייה\u0004 \u0005[מילאו]\u0006 את האויר הזה \u0003בשפודין\u0004 והשלים את הסכך הפסול לארבע אמות \u0003מאי\u0004 \u0005[מה]\u0006 דינה של סוכה זו — \u0003פסולה,\u0004 ויכול אתה איפוא להקשות אף לשיטתך: \u0003לא יהא אויר\u0004 שפסולו חמור שהוא \u0003פוסל בשלשה\u0004 טפחים \u0003כסכך פסול הפוסל\u0004 רק \u0003בארבע אמות!\u0004","\u0003ואמינא להו אנא\u0004 \u0005[ואמרתי להם אני]:\u0006 \u0003האי מאי\u0004 \u0005[זה מהו]?\u0006 כלומר: מה טיבה של קושיה זו שאתם מקשים? \u0003בשלמא לדידי דאמינא\u0004 \u0005[נניח לשיטתי, שאני אומר]\u0006 \u0003ארבע אמות\u0004"],["\u0003משום שיעורא\u0004 \u0005[שיעור]\u0006 \u0003ולאו שיעורא\u0004 \u0005[ולא שיעור]\u0006 \u0003הוא,\u0004 כלומר: שלדעתי הלכה מיוחדת היא ששיעור סכך פסול לפסול אינו אלא בארבע אמות, והוא דין אחד מסויים לעצמו. ויש פסול אחר בסוכה שהוא פסול חלל ריק (\"אויר\") ובו שיעור לעצמו, ואם כן \u0003האי\u0004 \u0005[זה]\u0006 פחות מארבע אמות \u0003לאו שיעורא\u0004 \u0005[לא שיעור]\u0006 \u0003הוא\u0004 לפסול לעצמו, ו\u0003כיון\u0004 ש\u0003לא שוו\u0004 \u0005[שווים]\u0006 \u0003שיעורייהו להדדי\u0004 \u0005[שיעוריהם\u0006 של שני הפסולים \u0005זה לזה]\u0006 — \u0003לא מצטרפי\u0004 \u0005[מצטרפים],\u0006 כיון שהם שני סוגים שונים של פסול. ורק אם מרחיב ועושה את הפסול ארבע אמות הרי הגיע לשיעור ופוסל.","\u0003אלא לדידכו דאמריתו\u0004 \u0005[לשיטתכם שאתם אומרים]\u0006 כי \u0003שיעור\u0004 זה של פסול הוא \u0003משום הפלגה,\u0004 כלומר: המרחק שבין הדופן ובין הסכך הכשר, ובשל הרווח הזה נפסלת הסוכה, אם כן \u0003מה לי איתפלג\u0004 \u0005[\u0006אם \u0005נחלק,\u0006 התרחק\u0005]\u0006 השיעור על ידי \u0003סכך פסול,\u0004 ו\u0003מה לי איתפלג\u0004 \u0005[\u0006אם \u0005נחלק,\u0006 התרחק\u0005]\u0006 השיעור על ידי \u0003סכך פסול ואויר,\u0004 שהרי בין כה וכה אין כאן מקום לצרף את הסכך עם הדופן. עד כאן סיפר רבה את ויכוחו שהיה לו עם חכמי בית רב.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: ולמר נמי\u0004 \u0005[ול\u0006שיטתך \u0005אדוני,\u0006 רבה, \u0005גם כן]\u0006 \u0003נהי דלא שוו שיעורייהו\u0004 \u0005[אם אמנם שלא שווים שיעוריהם]\u0006 של שני פסולים אלה, הרי זה דווקא \u0003בסוכה גדולה\u0004 בת ארבע אמות ויותר, אולם \u0003בסוכה קטנה מי לא שוו שיעורייהו\u0004 \u0005[האם לא שווים שיעוריהם]?\u0006 שהרי בסוכה ששיעורה מצומצם (שבעה טפחים), האויר הפסול והסכך הפסול בעל כרחנו פוסלים בשיעור זהה, שהרי ודאי שאם רוב (שהוא ארבעה טפחים) הסוכה מכוסה בסכך פסול הריהי פסולה, ואם כן נימוקו של רבה ששני השיעורים אינם שוים איננו מדוייק!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רבה: \u0003התם לאו\u0004 \u0005[שם לא]\u0006 \u0003משום דשוו שיעורייהו להדדי\u0004 \u0005[ששווים שיעוריהם זה לזה]\u0006 \u0003הוא\u0004 טעם פסולם, \u0003אלא משום דליתיה\u0004 \u0005[שאין]\u0006 \u0003שיעור\u0004 ל\u0003סוכה\u0004 זו, \u0003הוא\u0004 הפסול. ששם אין הסוכה נפסלת משום שיש בה שיעור מסויים של סכך פסול, אלא היא נפסלת משום שאין בה שיעור של סוכה כשרה, והפסול אינו חיובי, אלא נובע מהעדר הכשר בסוכה זו, ואין להקשות איפוא מכאן.","בתוך דבריו השתמש רבה בנימוק שכיון ששיעורי שני הפסולים אינם שוים זה לזה, לכך אין הם מצטרפים זה לזה. ושואלים: \u0003וכל היכא\u0004 \u0005[אימת]\u0006 ש\u0003לא שוו שיעורייהו להדדי\u0004 \u0005[שווים שיעוריהם זה לזה]\u0006 \u0003לא מצטרפי\u0004 \u0005[מצטרפים]?\u0006 \u0003והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]:\u0006 \u0003הבגד\u0004 שיעורו הקטן ביותר לקבל טומאת משכב הזב הוא \u0003שלשה על שלשה\u0004 טפחים, \u0003השק\u0004 הארוג משיער עזים שהוא גס יותר, שיעורו ב\u0003ארבעה על ארבעה\u0004 טפחים, \u0003העור,\u0004 שיעורו \u0003חמשה על חמשה\u0004 טפחים, \u0003מפץ\u0004 (מחצלת), שיעורה \u0003ששה על ששה\u0004 טפחים.","\u0003ותני עלה\u0004 \u0005[ושנויה\u0006 ברייתא \u0005עליה\u0006 כתוספת\u0005]:\u0006 \u0003הבגד והשק, השק והעור, העור והמפץ, מצטרפין זה עם זה.\u0004 שאם צירף מהמין החמור (כלומר: מהמין ששיעורו לטומאה קטן יותר) להשלים לשיעורו של המין הקל ממנו (ששיעורו לטומאה גדול יותר), הרי הדבר המצורף מקבל טומאה. משמע, ששני דברים ששיעוריהם לעצמם אינם שוים, אם מצרפים אותם יחד הריהם מצטרפים לפחות לשיעור הקל!","ודוחים: \u0003התם כדקתני טעמא\u0004 \u0005[שם כמו שנינו\u0006 ב\u0005טעם]\u0006 הדבר, ש\u0003אמר ר' שמעון: מה טעם\u0004 מצטרפין אלה — \u0003הואיל וראוי\u0004 החלק המצורף \u0003לטמא מושב\u0004 בעצמו, אף ללא צירוף. \u0003כדתנן\u0004 \u0005[כפי ששנינו\u0006 במשנה\u0005]:\u0006 \u0003המקצע\u0004 (חותך ומעבד בצורה יפה) \u0003מכולן,\u0004 מן הבגד, השק, או העור \u0003טפח על טפח\u0004 — הריהו \u0003טמא.\u0004 ונמצא שלענין מסויים יש שיעור אחד שוה לכל המינים הללו, וכיון שכן, יש בכך כדי לעשותם ראויים להצטרף זה לזה.","ושואלים לעצם הענין: \u0003טפח על טפח למאי חזי\u0004 \u0005[למה הוא ראוי]?\u0006 שהרי מטלית שאינה ראויה לשימוש, אינה מקבלת טומאה! \u0003ואמר ר' שמעון בן לקיש משום\u0004 \u0005[בשם]\u0006 \u0003ר' ינאי: הואיל וראוי ליטלו\u0004 (לעשות ממנו טלאי) למרדעת המונחת \u0003על גבי החמור\u0004 כנגד מקום ישיבת הרוכב. עד כאן המשא והמתן בדברי רבה, בויכוחו עם חכמי בית רב.","ומעירים: \u0003בסורא אמרי להא שמעתא בהאי לישנא\u0004 \u0005[היו אומרים את דבר ההלכה הזה בלשון זו]\u0006 כפי שאמרנו. ואילו \u0003בנהרדעא מתנו\u0004 \u0005[היו שונים]\u0006 כך: \u0003אמר רב יהודה אמר שמואל: סכך פסול,\u0004 אם היה \u0003באמצע,\u0004 שלא בסמוך לדופן הסוכה — הריהו \u0003פוסל בארבעה\u0004 טפחים. ואם היה \u0003מן הצד\u0004 — הריהו \u0003פוסל בארבע אמות. ורב אמר: בין מן הצד בין באמצע\u0004 — הריהו פוסל \u0003בארבע אמות.\u0004","\u0003תנן\u0004 \u0005[שנינו\u0006 במשנה\u0005]:\u0006 \u0003נתן עליה\u0004 על הסוכה \u0003נסר שהוא רחב ארבעה טפחים\u0004 — הרי הסוכה \u0003כשרה.\u0004 ומעתה, \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003ל\u0004שיטת \u0003רב\u0004 ש\u0003אמר\u0004 כי \u0003בין באמצע בין מן הצד,\u0004 שיעור סכך פסול הוא \u0003בארבע אמות, משום הכי\u0004 \u0005[כך]\u0006 \u0003כשרה\u0004 הסוכה, שהרי הנסר אינו מגיע לארבע אמות. \u0003אלא ל\u0004שיטת \u0003שמואל\u0004 ש\u0003אמר\u0004 כי \u0003באמצע\u0004 פוסלים אפילו \u0003ארבעה\u0004 טפחים, אם כן \u0003אמאי\u0004 \u0005[מדוע]\u0006 הסוכה \u0003כשרה?\u0004 ומשיבים: \u0003הכא במאי עסקינן\u0004 \u0005[כאן\u0006 במשנה \u0005במה אנו עוסקים]\u0006 — שהניח את הנסר \u0003מן הצד,\u0004 אולם אם היה מניחו באמצע אכן היה פוסל לדעת הכל את הסוכה.","ומנסים להביא ראיה אחרת: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע],\u0006 ממה ששנינו: \u0003שני סדינין\u0004 (שהם ודאי סכך פסול) שהניחם על גבי הסוכה — \u0003מצטרפין\u0004 לפסול את הסוכה. \u0003שני נסרים\u0004 — \u0003אין מצטרפין\u0004 לפסול את הסוכה. \u0003ר' מאיר אומר: נסרים\u0004 דינן \u0003כסדינין,\u0004 שהרי פוסל ר' מאיר סוכה המסוככת בנסרים משום גזירת תיקרה.","ומבררים: \u0003בשלמא להך לישנא\u0004 \u0005[נניח לפי לשון זו]\u0006 ש\u0003אמר רב\u0004 כי \u0003בין באמצע בין מן הצד\u0004 שיעורם \u0003בארבע אמות, מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"מצטרפין\" — מצטרפין\u0004 שני הפסולים \u0003לארבע אמות. אלא להך לישנא\u0004 \u0005[לפי לשון זו]\u0006 ששנו בסורא, ש\u0003אמר רב\u0004 כי \u0003באמצע\u0004 די \u0003בארבעה\u0004 טפחים כדי לפסול, \u0003היכי דמי\u0004 \u0005[כיצד היה בדיוק הענין]\u0006 בנסרים אלה? \u0003אי דאית בהו\u0004 \u0005[אם\u0006 באלה \u0005שיש בהם]\u0006 רוחב \u0003ארבעה\u0004 טפחים, \u0003למה להו אצטרופי\u0004 \u0005[להם להצטרף]?\u0006 שהרי הם עצמם פסולים! \u0003אי דלית בהו\u0004 \u0005[אם שאין בהם]\u0006 \u0003ארבעה\u0004 טפחים, אם כן \u0003קניא בעלמא נינהו\u0004 \u0005[קנים בלבד הם]\u0006 ומדוע יהיו פסולים לסוכה?","ומשיבים: \u0003לעולם\u0004 תפרש \u0003דאית בהו\u0004 \u0005[שיש בהם\u0006 ברוחבם\u0005]\u0006 \u0003ארבעה\u0004 טפחים, \u0003ומאי\u0004 \u0005[ומה\u0006 פירוש\u0005]\u0006 \u0003\"מצטרפין\"\u0004 — \u0003מצטרפין ל\u0004פסול ב\u0003ארבע אמות מן הצד,\u0004 וזה מתאים לכל השיטות, הן לרב והן לשמואל.","\u0003תא שמע\u0004 \u0005[בא\u0006 ו\u0005שמע]\u0006 ראיה מברייתא אחרת: \u0003סככה\u0004 לסוכה כולה \u0003בנסרין של ארז שיש בהן\u0004 בכל אחד מהם \u0003ארבעה\u0004 טפחים — \u0003דברי הכל פסולה. אין בהן ארבעה\u0004 טפחים — \u0003ר' מאיר פוסל ור' יהודה מכשיר.\u0004"],["\u0003ומודה ר' מאיר שאם יש בין נסר לנסר\u0004 חלל \u0003כמלא\u0004 רוחב \u0003נסר\u0004 — \u0003שמניח פסל\u0004 (סכך כשר) \u0003ביניהם וכשרה.\u0004","ומעתה נברר: \u0003בשלמא למאן דאמר\u0004 \u0005[נניח ל\u0006שיטת \u0005מי שאמר]\u0006 כי סכך פסול \u0003בין באמצע בין מן הצד\u0004 פוסל \u0003בארבע אמות, משום הכי\u0004 \u0005[כך]\u0006 סוכה זו \u0003כשרה, אלא למאן דאמר\u0004 \u0005[\u0006לשיטת \u0005מי שאמר]\u0006 כי \u0003באמצע\u0004 נפסלת הסוכה \u0003בארבעה\u0004 טפחים, \u0003אמאי\u0004 \u0005[מדוע]\u0006 אם כן הסוכה \u0003כשרה?\u0004 והרי בכל נסר כזה יש כדי שיעור לפסול, ואם כן אין לסוכה כל הכשר!","\u0003אמר רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע: הכא\u0004 \u0005[כאן]\u0006 מדובר \u0003בסוכה דלא הויא\u0004 \u0005[שאינה]\u0006 \u0003אלא שמנה\u0004 אמות \u0003מצומצמות עסקינן\u0004 \u0005[עוסקים אנו],\u0006 שהם בדיוק ארבעים ושמונה טפחים, והתחיל בהנחת הסכך מן הצדדים, \u0003ויהיב\u0004 \u0005[והוא נותן]\u0006 באופן זה: \u0003נסר\u0004 בן ארבע טפחים \u0003ופסל\u0004 במידה זהה \u0003ונסר ופסל ונסר ופסל מהאי גיסא\u0004 \u0005[מצד זה,\u0006 מצד אחד\u0005],\u0006 כך שהמידה הכוללת מצד זה היא עשרים וארבע טפחים. ולאחר מכן הניח \u0003נסר ופסל ונסר ופסל ונסר ופסל מהאי גיסא\u0004 \u0005[מצד זה,\u0006 מהצד הנגדי\u0005],\u0006 שאף מידתם הכוללת היא עשרים וארבעה טפחים, ועל ידי כך","\u0003דהוו להו\u0004 \u0005[\u0006נמצא \u0005שיש להם]\u0006 בסופו של דבר סוכה מסוככת כש\u0003שני פסלין\u0004 שהם ביחד שמונה טפחים צמודים זה לזה \u0003באמצע, ואיכא\u0004 \u0005[ויש]\u0006 \u0003הכשר סוכה באמצע\u0004 וכל השאר אינו פסול לכל השיטות, בין לדעת האומר משום דופן עקומה, בין לדעת האומר משום סכך פסול, לא יפסול אלא בארבע אמות, שכיון שכאן יש פחות מארבע אמות, תהא הסוכה כשרה.","\u0003אמר אביי: אויר\u0004 (חלל) \u0003שלשה\u0004 טפחים \u0003בסוכה גדולה\u0004 (שהיא יתירה מן השיעור המצומצם של סוכה כשרה שהוא שבעה טפחים) \u0003ומיעטו\u0004 לחלל זה, \u0003בין\u0004 שמיעטו על ידי \u0003קנים\u0004 שהם סכך כשר \u0003בין בשפודין\u0004 ממתכת שהם סכך פסול — \u0003הוי\u0004 \u0005[הרי\u0006 זה\u0005]\u0006 \u0003מיעוט\u0004 ואין החלל פוסל עוד. שהלוא עתה שוב אין שיעור אויר הפוסל ולא די שיעור כדי לפסול בסכך פסול. אולם אם היה החלל \u0003בסוכה קטנה,\u0004 אם מיעט את החלל \u0003בקנים, הוי\u0004 \u0005[הרי\u0006 זה\u0005]\u0006 \u0003מיעוט\u0004 וכשר. ואם מיעטו \u0003בשפודין, לא הוי\u0004 \u0005[אינו]\u0006 \u0003מיעוט\u0004 ופסולה. שכיון שהסוכה כולה קטנה מאוד ויש בה שלושה טפחים שאין בהם הכשר סוכה, אין די בארבעת הטפחים האחרים כדי להחשיבה כסוכה כשרה, ואין החלל הזה נחשב כסתום.","ומעירים: \u0003והני מילי\u0004 \u0005[ודברים אלה]\u0006 אמורים כשהיה חלל זה \u0003מן הצד,\u0004 שאז ניתן לומר דין לבוד, שכל חלל הפחות משלושה טפחים נחשב כסתום. \u0003אבל\u0004 אם היה החלל \u0003באמצע\u0004 — \u0003פליגי\u0004 \u0005[נחלקו]\u0006 \u0003בה רב אחא ורבינא, חד\u0004 \u0005[אחד]\u0006 מהם \u0003אמר: יש לבוד\u0004 גם \u0003באמצע,\u0004 ואף חלל פחות משלושה שם נחשב כאילו אינו; \u0003וחד\u0004 \u0005[ואחד]\u0006 מהם \u0003אמר: אין לבוד באמצע,\u0004 וכל דבר שיש בו חלל באמצעו אין אומרים בו לבוד.","ומסבירים: \u0003מאי טעמיה דמאן דאמר\u0004 \u0005[מה טעמו של מי שאמר]\u0006 כי \u0003יש לבוד באמצע\u0004 — \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003קורה\u0004 של הכשר מבוי \u0003היוצאה מכותל זה ואינה נוגעת בכותל אחר\u0004 שכנגדו, \u0003וכן שתי קורות, אחת יוצאה מכותל זה ואחת יוצאה מכותל אחר ואינן נוגעות זו בזו,\u0004 אף שהן מקבילות — אם היה הרווח בין הקורות או בין הקורה והכותל \u0003פחות משלשה\u0004 טפחים, \u0003אינו צריך להביא קורה אחרת,\u0004 לפי שאנו חושבים אותם כצמודים זה לזה. אולם אם היה הרווח \u0003שלשה\u0004 טפחים — \u0003צריך להביא קורה אחרת.\u0004 ומכאן משמע שאפילו באמצע אומרים לבוד, שבפחות משלושה טפחים שתי הקורות נחשבות כצמודות זו לזו.","ושואלים: \u0003ואידך\u0004 \u0005[והאחר]\u0006 האומר שאין לבוד באמצע, הלא לכאורה ראיה גמורה היא מהכשר מבוי כנגד שיטתו! ומסבירים שהוא עונה על כך: \u0003שאני\u0004 \u0005[שונות]\u0006 ה\u0003קורות\u0004 שהם מ\u0003דרבנן\u0004 \u0005[מדברי סופרים],\u0006 שכיון שכל איסור הטלטול במבוי והכשר המבוי בטלטול על ידי תיקון בקורה הוא מתקנת חכמים בלבד, לכן הקילו בו בכמה דברים, ואין מכאן ראיה לדינים אחרים.","\u0003מאי טעמא דמאן דאמר\u0004 \u0005[מה טעמו של מי שאמר]\u0006 כי \u0003אין לבוד באמצע\u0004 — \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003ארובה שבבית ובה פותח טפח,\u0004 כלומר: שחללה טפח על טפח אם היתה \u0003טומאה\u0004 (טומאת מת) \u0003בבית\u0004 — \u0003כולו טמא\u0004 כדין אהל המת, \u0003ומה ש\u0004מונח \u0003כנגד\u0004 ה\u0003ארובה\u0004 — \u0003טהור,\u0004 לפי שעל דבר זה אין הבית מאהיל. ואם היתה ה\u0003טומאה\u0004 מונחת \u0003כנגד\u0004 ה\u0003ארובה,\u0004 שנמצא שאין כיסוי אהל על הטומאה עצמה, \u0003כל הבית כולו טהור.\u0004","וכן הדין אם \u0003אין בארובה פותח טפח, טומאה בבית —\u0004 מה ש\u0003כנגד\u0004 ה\u0003ארובה, טהור.\u0004 ואם היתה ה\u0003טומאה\u0004 מונחת \u0003כנגד\u0004 ה\u0003ארובה — כל הבית כולו טהור.\u0004 והלא חלל הארובה אין בו אף טפח אחד, ואם אנו אומרים לבוד אף באמצע הרי חלל זה היה צריך להיחשב כסתום, וארובה זו היתה צריכה להתבטל ולהיחשב כחלק מן הבית. ומאחר ובכל זאת מתחשבים בחלל זה ורואים אותו כפתוח, משמע שאין דין לבוד באמצע.","ושואלים: \u0003ואידך\u0004 \u0005[והאחר]\u0006 מה עונה הוא להוכחה זו? ומשיבים: \u0003שאני\u0004 \u0005[שונות]\u0006 \u0003הלכות טומאה דהכי גמירי להו\u0004 \u0005[שכך למודים\u0006 במסורת \u0005אותן]\u0006 וכולן הלכה למשה מסיני, ודיני אהל הטומאה מיוחדים הם בכל פרטיהם ואין ללמוד מהם להלכות אחרות.","\u0003דרש ר' יהודה בר אלעאי: בית שנפחת וסיכך על גביו\u0004 — הרי זו סוכה \u0003כשרה. אמר לפניו ר' ישמעאל בר' יוסי: רבי פריש\u0004 \u0005[פרש\u0006 דבריך\u0005],\u0006 \u0003כך פירש אבא:\u0004 אם היה הריוח בין הכותל לפחת \u0003ארבע אמות — פסולה, פחות מארבע אמות — כשרה.\u0004","אגב סיפור זה, מביאים סיפור דומה בענין אחר. \u0003דרש ר' יהודה בר אלעאי:\u0004 הדג הקרוי \u0003אברומא — שריא\u0004 \u0005[מותר],\u0006 אף על פי שדג זה קטן ביותר וכשהוא ניצוד ניצודים עמו דגים טמאים הדומים לו וקיים קושי בזיהויו. \u0003אמר לפניו ר' ישמעאל בר' יוסי: רבי, פריש\u0004 \u0005[פרש\u0006 דבריך\u0005],\u0006 \u0003כך אמר אבא:\u0004 אברומא \u0003של מקום פלוני\u0004 שבנהרות שבו קיימים גם דגים טמאים — \u0003אסורה,\u0004 ואילו \u0003של מקום פלוני\u0004 שבנהרות שבו אין קיימים דגים טמאים — \u0003מותרת.\u0004","ומעירים: ודברים אלה \u0003כי הא\u0004 \u0005[כמו זה]\u0006 ש\u0003אמר אביי: האי צחנתא דבב נהרא שריא\u0004 \u0005[אותם דגים קטנים של נהר בב מותרים].\u0006 ושואלים: \u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 התירם כולם ולא חשש לדגים טמאים? \u0003אילימא משום דרדיפי מיא\u0004 \u0005[אם תאמר משום שהמים\u0006 שם \u0005רדופים,\u0006 זורמים בחזקה\u0005]\u0006 \u0003והאי\u0004 \u0005[וזה]\u0006 ה\u0003דג טמא, כיון דלית ליה\u0004 \u0005[שאין לו]\u0006 \u0003חוט השדרה לא מצי קאים\u0004 \u0005[אינו יכול לעמוד]\u0006 במים אלה והוא מושלך מתוכם, ולכן דגי נהר בב כולם כשרים. ואולם נימוק זה אינו נכון: \u0003והא קא חזינן דקאי\u0004 \u0005[והרי רואים אנו שעומדים,\u0006 קיימים\u0005]\u0006 דגים טמאים גם בנהרות הזורמים בחזקה!","\u0003אלא משום דמליחי מיא\u0004 \u0005[שמלוחים המים]\u0006 בנהר בב \u0003והאי\u0004 \u0005[וזה]\u0006 ה\u0003דג\u0004 ה\u0003טמא, כיון דלית ליה קילפי\u0004 \u0005[שאין לו קשקשים]\u0006 \u0003לא מצי קאי\u0004 \u0005[אינו יכול לעמוד,\u0006 להתקיים\u0005]\u0006 במים מלוחים. ואף זה איננו נכון — \u0003והא קא חזינן דקאי\u0004 \u0005[והרי רואים אנו שהוא עומד,\u0006 קיים\u0005],\u0006 \u0003אלא\u0004 יש לומר שקבע עובדה נסיונית: \u0003משום דלא מרבה טינייהו\u0004 \u0005[שאין מגדל הבוץ שלהם]\u0006 \u0003דג טמא.\u0004 שאין התנאים בנהר זה מתאימים לגידולם של דגים טמאים. \u0003אמר רבינא: והאידנא\u0004 \u0005[ועכשיו]\u0006 ששינתה המלכות ובנתה תעלות בין הנהרות, \u0003דשפכי\u0004 \u0005[שנשפכים]\u0006 \u0003נהר איתן ונהר גמדא להתם\u0004 \u0005[לשם]\u0006 ונהר בב שוב אינו כמו שהיה מתחילה ומים אחרים מעורבים בו ונשתנו תנאי המחיה בנהר זה, הרי \u0003אסירא\u0004 \u0005[אסורה]\u0006 הדגה של נהר זה ללא בדיקה מדוקדקת.","\u0003אתמר\u0004 \u0005[נאמר]\u0006 שחלקו אמוראים בבעיה הבאה; \u0003סיכך על גבי אכסדרה שיש לה פצימין\u0004 (עמודים) בצידה הפתוח — \u0003כשרה.\u0004 ואם \u0003אין לה פצימין, אביי אמר: כשרה, ורבא אמר: פסולה,\u0004 ומסבירים את שיטותיהם; \u0003אביי אמר כשרה\u0004"],["כי \u0003אמרינן\u0004 \u0005[אומרים אנו]\u0006 ומקבלים את ההנחה ש\u0003פי תקרה יורד וסותם.\u0004 שמאחר שלאכסדרה יש תיקרה הרי פי (קצה) התיקרה הוא כמחיצה קטנה לעצמו ומחשיבים אותו כאילו הוא נמשך ויורד וסותם עד למטה כדופן. \u0003רבא אמר:\u0004 סוכה זו \u0003פסולה,\u0004 כי \u0003לא אמרינן\u0004 \u0005[אין אנו אומרים]\u0006 \u0003פי תקרה יורד וסותם.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא לאביי: לדידך\u0004 \u0005[לשיטתך]\u0006 \u0003דאמרת\u0004 \u0005[שאתה אומר]\u0006 כי \u0003פי תקרה יורד וסותם\u0004 ודבר זה נחשב כדופן, אם כן לשיטתך סוכה שיש עליה קורות ישרות \u0003אפילו הפחית דופן האמצעי\u0004 ויש לה רק שתי דפנות תהא הסוכה כשרה, אם אומר אתה \"פי תיקרה יורד וסותם\", ותיחשב הסוכה כסתומה מכל צד! \u0003אמר ליה: מודינא לך בההיא\u0004 \u0005[מודה אני לך בזו]\u0006 \u0003דהוה ליה\u0004 \u0005[שהרי היא]\u0006 \u0003כמבוי המפולש\u0004 שהכל עוברים בו, ואין מקום לסמוך כאן על ההנחה של פי תיקרה יורד וסותם. אבל במקום שאין הכל עוברים, יכולים אנו לסמוך על התפישה כי פי תיקרה עצמו יורד וסותם.","ומציעים: \u0003לימא\u0004 \u0005[האם לומר]\u0006 כי \u0003אביי ורבא בפלוגתא\u0004 \u0005[במחלוקת]\u0006 של \u0003רב ושמואל קמיפלגי\u0004 \u0005[הם חלוקים],\u0006 שהם מפתחים מחלוקת יסודית שכבר נחלקו בה אמוראים אחרים. \u0003דאתמר\u0004 \u0005[שנאמר]\u0006 שנחלקו בנושא זה: \u0003אכסדרה\u0004 שהיתה מצויה בתוך \u0003בקעה\u0004 (שדה) והבקעה אין דינה כרשות הרבים אלא ככרמלית (רשות ביניים), והשאלה היא: האם נאמר שהאכסדרה למרות שאין לה מחיצות גמורות נחשבת כרשות היחיד או לא. \u0003רב אמר: מותר לטלטל בכולו\u0004 בכל השטח של האכסדרה, שלדעתו הריהו נחשב כרשות היחיד, \u0003דאמרינן\u0004 \u0005[שאומרים אנו];\u0006 \u0003פי תקרה\u0004 של האכסדרה \u0003יורד וסותם\u0004 והריהי כמוקפת מחיצות מכל צד. \u0003ושמואל אמר: אין מטלטלין בה אלא בארבע אמות,\u0004 כפי שמותר לטלטל בכרמלית עצמה, כי \u0003לא אמרינן\u0004 \u0005[אין אנו אומרים]\u0006 \u0003פי תקרה יורד וסותם.\u0004 ולכאורה מחלוקת אביי ורבא זהה ביסודה למחלוקתם של רב ושמואל!","את הדמיון הזה דוחים, ואומרים: \u0003אליבא\u0004 \u0005[לפי שיטתו]\u0006 של \u0003שמואל, כולי עלמא לא פליגי\u0004 \u0005[הכל אינם חולקים]\u0006 שאפילו אביי מודה שלפי שיטת שמואל אין לומר הלכה זו בסוכה."],["\u0003כי פליגי\u0004 \u0005[כאשר נחלקו]\u0006 הרי זה \u0003אליבא\u0004 \u0005[לפי שיטתו]\u0006 של \u0003רב, אביי\u0004 סובר \u0003כרב,\u0004 שהוא מחזיק בסברתו כי פי תיקרה יורד וסותם. \u0003ורבא אמר\u0004 \u0005[\u0006יכול היה \u0005לומר]\u0006 \u0003לך: עד כאן לא\u0004 שמענו ש\u0003אמר רב התם\u0004 \u0005[שם]\u0006 לענין אכסדרה \u0003אלא\u0004 ש\u0003מחיצות לאכסדרה\u0004 עצמה \u0003הוא דעבידי\u0004 \u0005[הן עשויות],\u0006 שפי תיקרה יכול להיחשב כיורד וסותם עבור השטח הפנימי של האכסדרה עצמה שתהא חשובה כבעלת דפנות, \u0003אבל הכא\u0004 \u0005[כאן]\u0006 בסוכה \u0003דלאו להכי עבידי\u0004 \u0005[שלא לכך נעשו],\u0006 \u0003לא\u0004 יועילו המחיצות.","ומנסים להביא ראיה: \u0003תנן\u0004 \u0005[שנינו\u0006 במשנתנו\u0005]:\u0006 \u0003וכן חצר המוקפת אכסדרה,\u0004 שאם אין מרחק ארבע אמות בין קירות הבתים שלצידה ובין הסכך שעל גבי האכסדרה, הרי קירות הבתים בצירוף תקרת האכסדרה משמשים כדופן לסוכה מדין \"דופן עקומה\". אולם אין מחשיבים את דפנות הסוכה כמן האכסדרה ולחוץ, \u0003ואמאי\u0004 \u0005[ומדוע]?\u0006 \u0003נימא\u0004 \u0005[נאמר]\u0006 כי \u0003פי תקרה יורד וסותם\u0004 ויחשב צידה החיצון של האכסדרה כדופן הסוכה!","\u0003תרגמה\u0004 \u0005[הסביר זאת]\u0006 \u0003רבא אליבא\u0004 \u0005[על פי שיטתו]\u0006 של \u0003אביי,\u0004 שתירץ את המשנה לפי דעת אביי: \u0003כשהשוה את קרויו.\u0004 כלומר: שלא עשה את פי התיקרה כיחידה מיוחדת לעצמה אלא הקירוי ופי התיקרה אחת הם, ואין ניכר שיש כאן פי תיקרה ולכן אינו נחשב כיורד וסותם.","ומעירים: \u0003בסורא מתני\u0004 \u0005[היו שונים]\u0006 \u0003להא שמעתא בהאי לישנא\u0004 \u0005[את ההלכה הזו בלשון זו]\u0006 שאמרנו. ואילו \u0003בפומבדיתא מתני\u0004 \u0005[היו שונים]\u0006 בלשון אחרת: \u0003סיכך על גבי אכסדרה שאין לה פצימין\u0004 (עמודים הקבועים בצידה החיצוני ומהווים לה מעין מחיצה), סוכה כזו ל\u0003דברי הכל פסולה,\u0004 שהרי אין לה מחיצות. אולם אם \u0003יש לה\u0004 לסוכה \u0003פצימין\u0004 וסמוכים הם זה לזה בפחות משלושה טפחים, \u0003אביי אמר: כשרה, רבא אמר: פסולה.\u0004 ומסבירים את שיטותיהם: \u0003אביי אמר\u0004 שהיא \u0003כשרה,\u0004 כי לשיטתו \u0003אמרינן\u0004 \u0005[אומרים אנו]\u0006 דין \u0003לבוד,\u0004 שמחשיבים את הפצימים כאילו היו מחוברים והריהם כמחיצה גמורה, בין ביחס לפנים האכסדרה ובין כלפי חוץ, ולכן הסוכה כשרה. ואילו \u0003רבא אמר\u0004 שהיא \u0003פסולה,\u0004 כי לשיטתו אף שדין לבוד הלכה למשה מסיני הוא, מכל מקום, לכגון זה שתיחשב זו כמחיצה גמורה לפנים ולחוץ — \u0003לא אמרינן\u0004 \u0005[אין אנו אומרים]\u0006 דין \u0003לבוד.\u0004 ומסכמים: \u0003והלכתא כלישנא קמא\u0004 \u0005[והלכה כלשון\u0006 ה\u0005ראשונה]\u0006 שהיא עיקר, ולפיה אנו פוסקים בענין זה.","מסופר: \u0003רב אשי אשכחיה\u0004 \u0005[מצא]\u0006 את \u0003רב כהנא דקא\u0004 \u0005[שהוא]\u0006 \u0003מסכך\u0004 סוכתו \u0003על גבי אכסדרה שאין לה פצימין. אמר ליה\u0004 \u0005[לו]:\u0006 \u0003לא סבר ליה מר הא\u0004 \u0005[וכי אין אדוני סובר\u0006 הלכה \u0005זו]\u0006 \u0003דאמר רבא\u0004 כי אם \u0003יש לה פצימין — כשרה,\u0004 ואם \u0003אין לה פצימין — פסולה,\u0004 ולכן אין לסכך בסוכה זו! \u0003אחוי ליה\u0004 \u0005[הראה לו]\u0006 ששם היה מקרה מיוחד, כי בסוכה זו היה \u0003נראה מבפנים ושוה מבחוץ.\u0004 שאמנם מבחוץ היו האכסדרה והסוכה כהמשך אחד באותו רוחב, אולם מבפנים היה אחד ממחיצותיה רחב מזו של הסוכה ובכך היתה האכסדרה נראית צרה יותר מן הסוכה ונבדלת איפוא ממנה.","\u0003אי נמי\u0004 \u0005[או גם כן]\u0006 היה זה מקרה של \u0003נראה מבחוץ ושוה מבפנים.\u0004 שהדופן החיצוני שלאורך הסוכה והאכסדרה לא היה שווה בשתיהן, ונראות היו שתיהן מצידן החיצוני כנבדלות זו מזו, אף שמבפנים היה דופנם שווה לכל אורכו. ובשתי האופנים הללו יש להחשיב בליטה זו כפצים ולהכשיר את הסוכה בכך.","\u0003דאתמר\u0004 \u0005[שנאמר]\u0006 בענין הכשרת מבוי לטלטול בשבת באמצעות לחי הצמוד לאחד מצידיו: כל עצם בולט שהוא \u0003נראה מבחוץ ושוה מבפנים,\u0004 כיון שהוא בולט וניכר מבחוץ \u0003נידון משום לחי. ולחי היינו\u0004 \u0005[הריהו\u0006 נחשב\u0005,\u0006 דינו\u0005]\u0006 כ\u0003פצימין\u0004 לענין זה. ולכן אף לענין סוכתו של רב כהנא, יש להחשיבה בשל אותה בליטה כאכסדרה שיש לה פצימין וכשרה.","\u0003תנא\u0004 \u0005[שנה\u0006 החכם בתוספתא\u0005]:\u0006 \u0003פסל,\u0004 כלומר: מיני פסולת קנים וכיוצא בהם שהם סכך כשר \u0003היוצא מן הסוכה — נידון כסוכה.\u0004 ושואלים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003פסל היוצא מן הסוכה? אמר עולא: קנים היוצאים\u0004 ונמשכים \u0003לאחורי\u0004 ה\u0003סוכה\u0004 ואינם בתוך חללה.","ושואלים: \u0003והא בעינן\u0004 \u0005[והרי צריכים אנו]\u0006 כדי להכשיר את חלק הסכך הזה הנוטה חוץ לסוכה שיהיו תחתיו גם \u0003שלש דפנות!\u0004 ומשיבים: \u0003בדאיכא\u0004 \u0005[בשיש].\u0006 כלומר, ששתי הדפנות הצדדיים נמשכים אל מחוץ לדופן האמצעית ומשמשים בדרך זו כסוכה בפני עצמה עם הסכך שעליה. ושואלים עוד: \u0003והא בעינן\u0004 \u0005[והרי צריכים אנו]\u0006 שיהיה במקום זה \u0003הכשר סוכה\u0004 מבחינת הגודל (שבעה טפחים)! ומשיבים: \u0003בדאיכא\u0004 \u0005[בשיש\u0006 שם\u0005].\u0006 ושואלים: \u0003והא בעינן\u0004 \u0005[והרי צריכים אנו]\u0006 שתהא \u0003צלתה מרובה מחמתה!\u0004 ומשיבים: \u0003בדאיכא\u0004 \u0005[שיש\u0006 שם\u0005].\u0006","לאחר כל אלה אומרים: אם כן הוא, שיש שם גם דפנות, גם שטח ראוי וגם צל, \u0003אי הכי מאי למימרא\u0004 \u0005[אם כן מה\u0006 נצרך \u0005לומר].\u0006 שאם כן סוכה גמורה וכשרה היא לעצמה, ומה השמיענו באומרו שנידון כסוכה? הלא סוכה גמורה הוא! ומשיבים: יש בכך חידוש, כי \u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 \u0003הואיל ו\u0004מחיצות סוכה זו מלכתחילה \u0003לגוואי עבידי\u0004 \u0005[לבפנים\u0006 לתוך הסוכה \u0005הם עשויות]\u0006 אולם \u0003ולבראי לא עבידי\u0004 \u0005[ולחוץ אינן עשויות],\u0006 כלומר: אותו דופן אמצעית שמלכתחילה לא היה מעוניין שישמש כדופן לכל אורך הדפנות הצדדים, שהרי הכניסו לפנים מהם, אם כן \u0003אימא\u0004 \u0005[אמור]\u0006 ש\u0003לא\u0004 ייחשב דופן זה כמחיצה, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שכיון שבפועל הוא משמש כמחיצה, אין זה משנה מה היתה הכוונה הראשונה בעשייתו.","\u0003רבה ורב יוסף אמרי תרווייהו\u0004 \u0005[אמרו שניהם]:\u0006 לא בכך מדובר, אלא \u0003הכא\u0004 \u0005[כאן]\u0006 באותה תוספתא מדובר \u0003בקנים היוצאים לפנים מן הסוכה\u0004 כלפי פתחה \u0003ומשכא ואזלא חדא דופן בהדייהו\u0004 \u0005[ונמשכת והולכת דופן אחת\u0006 של הסוכה \u0005יחד אתן]\u0006 ויש כאן כעין שתי דפנות הפתוחות אל הסוכה, \u0003מהו דתימא\u0004 \u0005[מהו שתאמר]\u0006 \u0003הא לית\u0004 \u0005[זו,\u0006 אותו מקום, \u0005אין]\u0006 \u0003בה\u0004 כדי \u0003הכשר סוכה\u0004 מצד הדפנות והגודל, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שדנים אנו חלק זה כהמשך של הסוכה, וכשר אף הוא אגב הסוכה.","\u0003רבה בר בר חנה אמר\u0004 בשם \u0003ר' יוחנן:\u0004 תוספתא זו \u0003לא נצרכה אלא לסוכה שרובה\u0004 אמנם \u0003צלתה מרובה מחמתה, ומעוטה חמתה מרובה מצלתה. מהו דתימא\u0004 \u0005[שתאמר]:\u0006 \u0003תפסל\u0004 הסוכה \u0003בהך פורתא\u0004 \u0005[באותו מעט]\u0006 שאין בו הכשר סוכה, ונאמר שחלק זה כיון שאינו כשר, כאילו אינו קיים, \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שאין חוששים לכך, ואף חלק זה דינו כסוכה. \u0003ו\u0004להסבר זה, אם כן \u0003מאי\u0004 \u0005[ומה\u0006 לשון\u0005]\u0006 \"פסל ה\u0003יוצא\u0004 מן הסוכה\" — יש לפרשו: \u0003יוצא מהכשר סוכה.\u0004 כלומר: יוצא לא בבחינת המקום אלא בבחינת ההלכה.","\u0003ר' אושעיא אמר: לא נצרכה אלא לסכך פסול\u0004 שהוא \u0003פחות משלשה\u0004 טפחים ומשהו, \u0003בסוכה קטנה. ומאי\u0004 \u0005[ומה\u0006 פירוש\u0005]\u0006 \u0003\"יוצא\"\u0004 — הכוונה היא \u0003יוצא מתורת סוכה\u0004 ואף על פי כן אין הוא פוסל את הסוכה כולה.","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב הושעיא:\u0004 מה איפוא החידוש בהלכה זו? \u0003לא יהא\u0004 חלל זה \u0003אלא\u0004 כ\u0003אויר, ואויר פחות משלשה טפחים בסוכה קטנה מי פסיל\u0004 \u0005[האם הוא פוסל]?\u0006 וכיון שגם חלל ריק לא היה פוסל, כל שכן שסכך פסול לא יפסול!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' אבא:\u0004 יש להבחין בדין בין סכך פסול לחלל בסוכה. כי \u0003זה\u0004 הסכך הפסול \u0003מצטרף\u0004 לשיעור סוכה ואף \u0003ישנים תחתיו\u0004 שהוא בטל לגמרי לסוכה ונעשה לגמרי חלק ממנה, ואילו \u0003זה\u0004 האויר אמנם \u0003מצטרף\u0004 לשיעור הסכך אבל \u0003אין ישנים תחתיו\u0004 שהוא עצמו לא הוכשר. ואם כן יש מקום לחידושו של ר' אושעיא.","ומקשים על סברה זו: \u0003ומי איכא מידי דאצטרופי מצטרף\u0004 \u0005[והאם יש דבר שהוא מצטרף]\u0006 ועל ידי צירופו הוא מכשיר אבל \u0003הוא עצמו\u0004 כשהוא לבדו \u0003אינו כשר\u0004 כלל? \u0003אמר ר' יצחק בן אלישב: אין\u0004 \u0005[כן],\u0006 יש כעין זה אף בהלכות אחרות"],["\u0003טיט הנרוק יוכיח.\u0004 כלומר: הדין שנאמר בטיט שהוא דליל כל כך שאפשר להריקו בשפיכה מכלי לכלי, \u0003שמצטרף לארבעים סאה\u0004 במקוה, שאם היה מקוה שיש בו מים קרוב לשיעור המכשיר של ארבעים סאה ונוסף לכך היתה במקוה כמות של טיט רך מאוד הרי זה מצטרף להכשיר את המקוה, אף ש\u0003הטובל בו,\u0004 בטיט עצמו \u0003לא עלתה לו טבילה.\u0004 הרי שיכול להיות דבר המצטרף להכשר, אף שהוא לכשעצמו אינו כשר.","\u0003העושה סוכתו כמין צריף\u0004 כאהל משופע מכל צד, \u0003או\u0004 שהיתה עשויה קיר אחד \u0003וסמכה לכותל ר' אליעזר פוסל\u0004 סוכה זו \u0003מפני שאין לה גג\u0004 ניכר, \u0003וחכמים מכשירין\u0004 שלדעתם יכולים להיות הגג והדופן יחידה אחת ואף שאינם נבדלים זה מזה — כשרים.","\u0003תנא\u0004 \u0005[שנויה\u0006 בתוספתא\u0005]:\u0006 \u0003מודה ר' אליעזר שאם הגביה\u0004 את הסוכה הזו העשויה כצריף או זו הסמוכה לכותל \u0003מן הקרקע טפח\u0004 ויש לה קיר זקוף לפחות בן טפח אחד, \u0003או שהפליגה\u0004 (הרחיקה) למעלה בקצה העליון \u0003מן הכותל טפח\u0004 — \u0003שהיא כשרה.\u0004 משום שאז ניכר שיש בה חלק המשמש כעין גג, וחלק המשמש כעין דופן וכיון שקיימת הבחנה כלשהי בין הדופן והגג — הרי זו כשרה.","ושואלים: \u0003מאי טעמייהו דרבנן\u0004 \u0005[מה טעמם של חכמים]\u0006 המכשירים אף כשדופן הסוכה משופע לגמרי? ומשיבים: לדעתם \u0003שיפועי אהלים כאהלים דמו\u0004 \u0005[נחשבים].\u0006 כלומר: השיפוע אף שאין ניכרים בו תחומי הגג והדופן, הרי דינו לענין זה כאהל, כלומר ככיסוי וסכך, ואין אנו צריכים שיהיה לו גג נבדל ניכר לעין.","מסופר: \u0003אביי אשכחיה\u0004 \u0005[מצא]\u0006 את \u0003רב יוסף\u0004 רבו \u0003דקא גני\u0004 \u0005[שהוא ישן]\u0006 \u0003בכילת חתנים\u0004 שהיא מיטה מסוככת שמעליה יש כילה של בד העשויה בשיפוע, \u0003ב\u0004תוך ה\u0003סוכה.\u0004 לכאורה לא יצא ידי חובה, שהרי ישן באהל שאינו סוכה. \u0003אמר ליה\u0004 \u0005[לו]\u0006 אביי: \u0003כמאן\u0004 \u0005[כ\u0006שיטת \u0005מי]\u0006 עושה אתה כך, ואינך סבור שכילה זו דינה כאהל — כדעת \u0003ר' אליעזר\u0004 האומר שדבר שאין לו גג נבדל מלמעלה אינו קרוי כלל גג, ואם ישן בתוך הסוכה בתוך כילה כזו אינו נחשב כישן בבית שבתוך סוכה. אולם, כיצד יכול אתה לנהוג כן? שהרי \u0003שבקת\u0004 \u0005[עזבת]\u0006 את שיטת \u0003רבנן\u0004 \u0005[חכמים]\u0006 המתירים בסוכה וממילא פוסלים בכילה \u0003ועבדת\u0004 \u0005[ועשית]\u0006 \u0003כ\u0004שיטת \u0003ר' אליעזר,\u0004 שדעתו דעת יחיד!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רב יוסף: ב\u0003ברייתא איפכא תני\u0004 \u0005[ההיפך שנינו],\u0006 בהיפוך הדעות, ושם שנינו: \u0003ר' אליעזר מכשיר וחכמים פוסלין.\u0004 תמה עליו אביי: אם כן \u0003שבקת מתניתין\u0004 \u0005[עוזב אתה\u0006 את \u0005משנתנו]\u0006 שגירסתה מוסמכת \u0003ועבדת\u0004 \u0005[ועושה אתה]\u0006 \u0003כברייתא\u0004 שלא תמיד היא מדוייקת?","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 יש לי הוכחה אחרת לדיוקה של אותה ברייתא, כי \u0003מתניתין יחידאה\u0004 \u0005[משנתנו\u0006 בעצם \u0005כדעת יחיד]\u0006 \u0003היא,\u0004 ורוב החכמים חולקים עליה. \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003העושה סוכתו כמין צריף או שסמכה לכותל, ר' נתן אומר: ר' אליעזר פוסל מפני שאין לה גג וחכמים מכשירין.\u0004 ומשנתנו ערוכה לפי גירסה זו, אך מן הברייתא מובן כי גירסה זו היא דעת יחיד של ר' נתן, ורוב חכמי הדור גרסו להיפך, ולכן להלכה יש להפוך את הדעות. ולפיכך מותר לישון בכילת חתנים בסוכה.","\u0003מחצלת קנים גדולה,\u0004 אם \u0003עשאה\u0004 מתחילה לצורך \u0003שכיבה\u0004 עליה — \u0003מקבלת טומאה\u0004 בתורת כלי, ולכן גם \u0003אין מסככין בה.\u0004 ואם עשה אותה לצורך \u0003סיכוך — מסככין בה, ואינה מקבלת טומאה,\u0004 שהרי אינה כלי העשוי לישיבה. \u0003ר' אליעזר אומר\u0004 אין לעשות הבחנה לפי הגודל אלא לפי השימוש \u0003אחת קטנה ואחת גדולה\u0004 אם \u0003עשאה לשכיבה — מקבלת טומאה ואין מסככין בה,\u0004 עשאה \u0003לסיכוך — מסככין בה, ואינה מקבלת טומאה.\u0004","כאשר מעיינים בלשון המשנה, מדייקים: \u0003הא גופא קשיא\u0004 \u0005[היא עצמה,\u0006 משנתנו, \u0005קשה]\u0006 שיש בה לכאורה סתירה פנימית. \u0003אמרת\u0004 מצד אחד: כי אם \u0003עשאה לשכיבה — מקבלת טומאה ואין מסככין בה,\u0004 ונדייק: \u0003טעמא\u0004 \u0005[הטעם,\u0006 דווקא\u0005]\u0006 ש\u0003עשאה\u0004 במיוחד \u0003לשכיבה, הא\u0004 \u0005[הרי]\u0006 מחצלת גדולה שלא ייחד אותה לתפקיד מיוחד, אלא עשאה \u0003סתמא\u0004 \u0005[בסתם]\u0006 ולא ציין את יעודה — \u0003לסיכוך\u0004 היא וכשרה.","\u0003והדר תני\u0004 \u0005[וחזר ושנה]\u0006 בהמשך המשנה: אם עשאה \u0003לסיכוך — מסככין בה ואינה מקבלת טומאה,\u0004 ונדייק: \u0003טעמא\u0004 \u0005[הטעם,\u0006 דווקא\u0005]\u0006 ש\u0003עשאה\u0004 במיוחד \u0003לסיכוך, הא\u0004 \u0005[הרי]\u0006 אם עשאה ב\u0003סתמא\u0004 \u0005[בסתם]\u0006 — ודאי \u0003לשכיבה\u0004 היא עשויה. הרי ששתי ההלכות הנאמרות במשנה סותרות זו לזו, בענין דברים שלא יוחדו מתחילה לצורך מסויים!","ומתרצים: \u0003הא לא קשיא\u0004 \u0005[זו אינה קשה],\u0006 \u0003כאן בגדולה, כאן — בקטנה.\u0004 כלומר: בתחילה מדובר במחצלת גדולה, שדווקא אם עשאה לשכיבה היא מקבלת טומאה וסתמה טהורה. ואילו בהמשך מדובר במחצלת קטנה, שבזו אם עשאה לסיכוך — מסככין בה, אבל סתמה לשם שכיבה היא.","ומעירים: \u0003בשלמא לרבנן לא קשיא\u0004 \u0005[נניח לשיטת חכמים,\u0006 לפי סתם משנה, \u0005אינו קשה]\u0006 ואפשר ליישב את הדברים כפי שהסברת. \u0003אלא ל\u0004שיטת \u0003ר' אליעזר\u0004 עדיין \u0003קשיא\u0004 \u0005[קשה],\u0006 \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנתנו\u0005];\u0006 \u0003ר' אליעזר אומר: אחת קטנה ואחת גדולה,\u0004 אם \u0003עשאה לשכיבה — מקבלת טומאה ואין מסככין בה,\u0004 ומדבריו נדייק: \u0003טעמא\u0004 \u0005[הטעם]\u0006 דווקא ש\u0003עשאה לשכיבה, הא\u0004 \u0005[הרי]\u0006 אם עשאה \u0003סתמא\u0004 \u0005[בסתם]\u0006 — ודאי מחצלת כזו \u0003לסיכוך.\u0004 היא עשוייה.","ומעתה \u0003אימא סיפא\u0004 \u0005[אמור את\u0006 המשך דבריו האמורים ב\u0005סופה\u0006 של המשנה\u0005]:\u0006 \u0003עשאה לסיכוך — מסככין בה ואינה מקבלת טומאה.\u0004 ונדייק: \u0003טעמא\u0004 \u0005[\u0006ה\u0005טעם,\u0006 דווקא\u0005]\u0006 אם \u0003עשאה לסיכוך, הא סתמא\u0004 \u0005[הרי סתמה]\u0006 \u0003לשכיבה\u0004 היא עומדת, והרי דבריו כסותרים זה את זה, וכאן אי אפשר לחלק בין קטנה לגדולה, שהרי הוא עצמו אינו מחלק!","\u0003אלא אמר רבא:\u0004 יש לדחות את התירוץ הראשון שתירצנו, ובמחצלת \u0003גדולה כולי עלמא לא פליגי\u0004 \u0005[הכל אינם חלוקים]\u0006 \u0003דסתמא\u0004 \u0005[שסתמה]\u0006 של מחצלת זו \u0003לסיכוך\u0004 היא עשויה. \u0003כי פליגי\u0004 \u0005[כאשר נחלקו]\u0006 הרי זה במחצלת \u0003קטנה. תנא קמא\u0004 \u0005[התנא הראשון]\u0006 \u0003סבר\u0004 כי \u0003סתם קטנה לשכיבה\u0004 היא מיועדת\u0003,\u0004 ואילו \u0003ר' אליעזר סבר:\u0004 כי \u0003סתם\u0004 מחצלת \u0003קטנה נמי\u0004 \u0005[גם כן]\u0006 \u0003לסיכוך\u0004 היא עשוייה, אלא אם כן יועדה במפורש לשכיבה."],["\u0003והכי קאמר\u0004 \u0005[וכך אמר],\u0006 כך יש להבין את לשון משנתנו: \u0003מחצלת הקנים גדולה\u0004 אם \u0003עשאה לשכיבה — מקבלת טומאה ואין מסככין בה. טעמא\u0004 \u0005[הטעם\u0006 דווקא\u0005]\u0006 ש\u0003עשאה לשכיבה, הא\u0004 \u0005[הרי]\u0006 אם עשאה \u0003סתמא\u0004 \u0005[בסתם]\u0006 — \u0003נעשה כמי שעשאה לסיכוך, ומסככין בה.\u0004 ואילו מחצלת \u0003קטנה,\u0004 אם \u0003עשאה לסיכוך\u0004 דווקא — \u0003מסככין בה, וטעמא\u0004 \u0005[הטעם,\u0006 דווקא\u0005]\u0006 ש\u0003עשאה לסיכוך, הא\u0004 \u0005[הרי]\u0006 אם עשאה \u0003סתמא\u0004 \u0005[בסתם]\u0006 — \u0003נעשה כמי שעשאה לשכיבה, ואין מסככין בה. ואתא\u0004 \u0005[ובא]\u0006 \u0003ר' אליעזר למימר\u0004 \u0005[לומר]:\u0006 אינו כן, אלא \u0003אחת קטנה ואחת גדולה\u0004 כשעשאה \u0003סתמא\u0004 \u0005[בסתם]\u0006 — \u0003כשרה לסיכוך.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: אי הכי\u0004 \u0005[אם כך]\u0006 כדבריך, שנחלקו בענין מחצלת קטנה סתם, הרי הלשון \u0003\"ר' אליעזר אומר אחת קטנה ואחת גדולה\"\u0004 אינה מדוייקת, שהרי לפי זה \u0003\"אחת גדולה ואחת קטנה\" מיבעי ליה\u0004 \u0005[צריך היה לו]\u0006 לומר! שהרי הוא אומר \"אחת זו ואחת זו\" ודרכו להתחיל בדבר הפשוט והמוסכם ולסיים בדבר שיש בו מחלוקת. ואילו לשיטתך, הלא בגדולה לא נחלקו כלל, ובקטנה היא המחלוקת!","\u0003ועו‍ד:\u0004 הרי יש ראיה \u0003כי פליגי\u0004 \u0005[כאשר נחלקו],\u0006 באמת במחצלת \u0003גדולה הוא דפליגי\u0004 \u0005[שנחלקו]\u0006 \u0003ו\u0004דעת \u0003ר' אליעזר לחומרא\u0004 היא ולא להקל, כפי שפירשת. \u0003דתניא\u0004 \u0005[ש\u0006הרי \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003מחצלת הקנים, בגדולה מסככין בה. ר' אליעזר אומר: אם אינה מקבלת טומאה — מסככין בה.\u0004 משמע שבסתם מחצלת גדולה אין מסככים!","\u0003אלא אמר רב פפא:\u0004 יש לדחות את דברי רבא ולומר כי במחצלת \u0003קטנה — כולי עלמא לא פליגי\u0004 \u0005[הכל אינם חלוקים]\u0006 ש\u0003סתמא\u0004 עומדת \u0003לשכיבה\u0004 ופסולה. \u0003כי פליגי\u0004 \u0005[כאשר נחלקו]\u0006 הרי זה \u0003בגדולה, תנא קמא\u0004 \u0005[התנא הראשון,\u0006 סתם משנה\u0005]\u0006 \u0003סבר: סתם גדולה\u0004 מיועדת ודאי \u0003לסיכוך, ור' אליעזר סבר: סתם גדולה נמי\u0004 \u0005[גם כן]\u0006 \u0003לשכיבה\u0004 היא מיועדת.","\u0003ומאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003עשאה לשכיבה דקאמר\u0004 \u0005[שהוא אומר]\u0006 — \u0003הכי קאמר\u0004 \u0005[כך אמר,\u0006 כך יש להבין\u0005]:\u0006 \u0003סתם עשייתה נמי\u0004 \u0005[גם כן]\u0006 \u0003לשכיבה\u0004 היא, \u0003עד דעביד\u0004 \u0005[שעושה]\u0006 מלכתחילה \u0003ל\u0004שם \u0003סיכוך.\u0004","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בתוספתא: \u0003מחצלת של שיפה\u0004 (מיני קנים ארוגים) \u0003ושל גמי\u0004 (קנים רכים ארוגים) אם היתה \u0003גדולה מסככין בה\u0004 שסתמה אינה עשויה למשכב. ואם היתה \u0003קטנה — אין מסככין בה,\u0004 שסתמה עשויה ודאי למשכב\u0003.\u0004 ואילו מחצלת \u0003של קנים\u0004 עבים \u0003ושל חילת\u0004 (קנים המיועדים לקליעה) שגם היא מחצלת גסה, אם \u0003גדו‍לה\u0004 — שעשויה מעשה קליעה, והיא גסה — \u0003מסככין בה,\u0004 שודאי אינה מיועדת לשכיבה. ואם היא \u0003ארוגה — אין מסככין בה,\u0004 שלא היו אורגים מחצלות אלא לצרכי שכיבה.","\u0003ר' ישמעאל בר' יוסי אומר משום אביו: אחת זו ואחת זו מסככין בה,\u0004 שסתמן של אלה לא לשכיבה הן עומדות, וטהורות הן. \u0003וכן היה ר' דוסא אומר כדבריו.\u0004","\u0003תנן התם\u0004 \u0005[שנינו שם\u0006 במשנה\u0005]:\u0006 \u0003כל החוצלות\u0004 (מין מחצלות) \u0003מטמאין טמא מת.\u0004 שיש להן דין כלי, ואם נגעו במת בכל דרך שהיא — הרי הן נטמאות ונעשות אב הטומאה, אלו \u0003דברי ר' דוסא. וחכמים אומרים:\u0004 טמאות טומאת \u0003מדרס,\u0004 כלומר: אם שכב או ישב עליהן הזב — נטמאו בגדר כלי מושבו ומשכבו של זב.","על לשון המשנה תוהים: האם בטומאת \u0003מדרס — אין\u0004 \u0005[כן]\u0006 הם כן מיטמאים, אבל בטומאת \u0003טמא מת — לא? והא אנן תנן\u0004 \u0005[והרי אנו שנינו\u0006 במשנה\u0005]:\u0006 \u0003כל\u0004 דבר \u0003המטמא\u0004 טומאת \u0003מדרס — מטמא\u0004 לכל שאר סוגי הטומאה ונעשה אף \u0003טמא מת.\u0004 אבל ההיפך אינו נכון תמיד. ואם כן, לכאורה אין טעם למחלוקתם בניסוח זה! ומתקנים: \u0003אימא\u0004 \u0005[אמור]\u0006 ותקן בלשון זו: טמאות \u0003אף מדרס.\u0004 כלומר: החוצלות אינן רק כלי פשוט המקבל טומאת מת, אלא יש להן גם דין כלי המיוחד למושב, הנטמא אף בטומאת זב.","במשנה הזכרנו חוצלות, ושואלים \u0003מאי\u0004 \u0005[מה\u0006 הן\u0005]\u0006 \u0003חוצלות\u0004 אלה? \u0003אמר רב אבדימי בר המדורי:\u0004 אלו הן \u0003מרזובלי.\u0004 אולם גם מלה זו לא היתה ידועה בכל מקום, ושאלו \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003מרזובלי? אמר ר' אבא:\u0004 הוא הדבר הקרוי בבבל \u0003מזבלי.\u0004 והן כעין כרים הארוגים מקני סוף. \u0003ר' שמעון בן לקיש אומר:\u0004 החוצלות הן \u0003מחצלות\u0004 רגילות \u0003ממש\u0004 ולא מין מיוחד, ואין כאן אלא שינוי לשון בלבד.","ומעירים, \u0003ואזדא\u0004 \u0005[והולך]\u0006 \u0003ריש לקיש לטעמיה\u0004 \u0005[לטעמו,\u0006 לשיטתו\u0005]\u0006 ש\u0003אמר ריש לקיש: הריני כפרת ר' חייא ובניו,\u0004 כלומר, אמר בלשון כבוד שהוא מכבדם עד כדי כך שהיה מוכן להיות תמורתן וכפרתן לסבול יסורים במקומם, ומדוע \u0003שבתחלה כשנשתכחה\u0004 חלק מהלכות ה\u0003תורה מישראל\u0004 שבארץ ישראל — \u0003עלה עזרא מבבל ויסדה. חזרה\u0004 התורה \u0003ונשתכחה\u0004 בארץ ישראל — \u0003עלה הלל הבבלי ויסדה, חזרה\u0004 התורה \u0003ונשתכחה — עלו ר' חייא ובניו ויסדוה.\u0004 וכל זה הקדים לחשיבותם ר' חייא ובניו, שבא לומר דבר הלכה בשמם, \u0003וכן אמר ר' חייא ובניו: לא נחלקו ר' דוסא וחכמים על\u0004 סוג ה\u0003מחצלות של אושא,\u0004 על סוג המחצלות הרכות כעין אלה שעושים בעיר אושא."],["\u0003שהן טמאות\u0004 אפילו טומאת מדרס, משום שהם מיוחדות לשכיבה, ועל מחצלות גסות \u0003של טבריא\u0004 \u0005[טבריה]\u0006 \u0003שהן טהורות,\u0004 שאינן עשויות אלא למחיצות ולסיכוך. \u0003על מה נחלקו — על\u0004 מחצלות של \u0003שאר מקומות. מר\u0004 \u0005[חכם זה,\u0006 חכמים\u0005]\u0006 \u0003סבר\u0004 כי \u0003כיון דליכא דיתיב עלייהו כדטבריא דמיין\u0004 \u0005[שאין מי שיושב עליהן,\u0006 שאין רגילים לשבת עליהן, \u0005הרי הן כמו\u0006 המחצלות \u0005של טבריה]\u0006 והן טהורות, \u0003ומר\u0004 \u0005[וחכם זה,\u0006 ר' דוסא\u0005]\u0006 \u0003סבר\u0004 כי \u0003כיון דמקרי ויתבי עלייהו, כדאושא דמיין\u0004 \u0005[שמזדמן שיושבים עליהן, הרי הן כמו\u0006 המחצלות \u0005של אושא]\u0006 וטמאות. אף שאין רגילים לשבת עליהן.","\u0003אמר מר\u0004 \u0005[החכם]:\u0006 \u0003כל החוצלות מטמאין טמא מת,\u0004 אלו \u0003דברי ר' דוסא.\u0004 הרי שלשיטתו, נחשבות הן ככלים ולכך הן מקבלות טומאה ואין לסכך בהן. ומקשים: \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003וכן היה ר' דוסא אומר כדבריו\u0004 של ר' ישמעאל בר' יוסי שכל המחצלות טהורות ומסככין בהן, והרי הדברים סותרים לכאורה זה את זה בהלכה זו!","ומשיבים: \u0003לא קשיא\u0004 \u0005[קשה]\u0006 אפשר ליישב את הסתירה ולומר: \u0003הא דאית ליה גדנפא\u0004 \u0005[זה כשיש לו\u0006 למחצלת זו \u0005שוליים מוגבהים]\u0006 היוצרים כעין בית קיבול ובשל כך הריהי נחשבת ככלי ולכן היא טמאה, \u0003הא דלית ליה גדנפא\u0004 \u0005[כאן כשאין לו שוליים מוגבהים],\u0006 אינה נחשבת ככלי והריהי טהורה.","\u0003מיתיבי\u0004 \u0005[מקשים]:\u0006 \u0003חוצלות של שעם ושל גמי ושל שק\u0004 \u0005[שיער עזים]\u0006 \u0003ושל ספירא\u0004 \u0005[שיער הסוס]\u0006 שאריגתן יפה ונוחה הישיבה והשכיבה על גביהן — \u0003מטמא טמא מת\u0004 ולא מדרס, שהם נחשבים ככלי ואינם עשויים לישיבה, אלו \u0003דברי ר' דוסא, וחכמים אומרים:\u0004 הריהן מיטמאות \u0003אף מדרס.\u0004","ושואלים: \u0003בשלמא למאן דאמר\u0004 \u0005[נניח ל\u0006שיטת \u0005מי שאמר]\u0006 שחוצלות הן \u0003מרזובלי\u0004 (מיני שקים), אפשר להסביר את המחלוקת, שהסובר שאינם מיטמאים מדרס משום שאינם ראויים לישיבה, מכל מקום הם נחשבים ככלי ולכך הם מיטמאים למת. שאם היו \u0003של שעם ושל גמי\u0004 — \u0003חזו לכינתא דפירי\u0004 \u0005[ראויים הם\u0006 להיות \u0005כסלי ירק].\u0006 ואם היו \u0003של שק ושל ספירא חזו\u0004 \u0005[ראויים]\u0006 הם \u0003לגולקי וצני\u0004 \u0005[לסלים קטנים],\u0006 כיון שאריגתן דקה יותר. \u0003אלא למאן דאמר\u0004 \u0005[ל\u0006שיטת \u0005האומר]\u0006 כי \u0003מחצלות ממש\u0004 ללא שולים מוגבהים ואין להן בית קיבול, מה טעם לחלוקה זו? שהרי המחצלות עצמן אינן ראויות אלא לשכיבה. \u0003בשלמא\u0004 \u0005[נניח]\u0006 מחצלות \u0003של שק\u0004 \u0005[שיער עיזים]\u0006 \u0003ושל ספירא\u0004 \u0005[שיער סוס] —\u0006 יכול אתה לומר שהם \u0003חזו לפרסי ונפוותא\u0004 \u0005[ראויים לעשות\u0006 מהם \u0005מסכים או נפות\u0006 לנפות בהן קמח\u0005],\u0006 \u0003אלא\u0004 מחצלות \u0003של שעם ושל גמי למאי חזו\u0004 \u0005[למה\u0006 הן \u0005ראויות]\u0006 עוד? ומשיבים: \u0003חזו לנזיאתא\u0004 \u0005[ראויות\u0006 הן לכיסויי \u0005גיגיות שיכר],\u0006 ולכן יש להם שימוש נוסף ככלי.","\u0003איכא דאמרי\u0004 \u0005[יש אומרים]\u0006 בלשון אחרת: \u0003בשלמא למאן דאמר\u0004 \u0005[נניח ל\u0006שיטת \u0005מי שאומר]\u0006 כי חוצלות הללו \u0003מחצלות ממש\u0004 הן, אם כן מחצלות \u0003של שעם ושל גמי חזו לנזיאתא\u0004 \u0005[ראויות\u0006 הן לכיסויי \u0005גיגיות שיכר],\u0006 ו\u0003של שק\u0004 \u0005[שיער עיזים]\u0006 \u0003ושל ספירא\u0004 \u0005[שיער סוס]\u0006 \u0003חזו לפרסי ונפוותא\u0004 \u0005[ראויות\u0006 הן \u0005למסכים ולנפות].\u0006 \u0003אלא למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי\u0006 ש\u0005אומר]\u0006 כי הן \u0003מרזובלי\u0004 (מיני שקים), \u0003בשלמא\u0004 \u0005[נניח]\u0006 מרזובלי, \u0003של שק ושל ספירא, חזו לגולקי וצני\u0004 \u0005[ראויים הם להכנים בהם כלים קטנים]\u0006 \u0003אלא\u0004 מחצלות \u0003של שעם ושל גמי למאי חזו\u0004 \u0005[למה הן ראויות],\u0006 ומדוע טמאות הן? ומשיבים: \u0003חזו לכינתא דפירי\u0004 \u0005[ראויים\u0006 הם \u0005לסל של פירות\u0006 גדולים\u0005].\u0006","\u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005]\u0006 \u0003אמר ר' חנניא: כשירדתי לגולה\u0004 (לבבל) \u0003מצאתי זקן אחד, ואמר לי: מסככין בבודיא\u0004 (מין מחצלת). \u0003וכשבאתי\u0004 חזרה לארץ ישראל \u0003אצל ר' יהושע\u0004 בן חנניא \u0003אחי אבא\u0004 \u0005[אחיו של אבי,\u0006 חנניא\u0005]\u0006 ואמרתי לו את דברי אותו זקן, \u0003הודה לדבריו. אמר רב חסדא: והוא\u0004 מדובר כאן במין בודיא \u0003דלית ליה גדנפא\u0004 \u0005[שאין לו דופן מוגבהת]\u0006 ואינה ראויה לשום שימוש, אלא לסיכוך.","\u0003אמר עולא: הני בודיתא\u0004 \u0005[אותם המחצלות]\u0006 של \u0003בני מחוזא, אלמלא קיר שלהן\u0004 שמקיף את סביבותיהן (\"גדנפא\"), היו \u0003מסככין בהן,\u0004 משום שהן עבות מאוד, ואינן מיועדות לישיבה. \u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 בברייתא \u0005גם כן כך]:\u0006 \u0003מסככין בבודיא, ואם יש להן קיר — אין מסככין בהן,\u0004 משום שעל ידי כך נעשו ככלי קיבול, ומקבלות טומאה.","","\u0003הישן תחת המטה בסוכה\u0004 — \u0003לא יצא ידי חובתו,\u0004 שהמיטה מהווה הפסק אוהל בינו ובין הסכך. \u0003אמר ר' יהודה: נוהגין היינו שהיינו ישנים תחת המטה בפני הזקנים, ולא אמרו לנו דבר\u0004 שאין אנו יוצאים ידי חובת סוכה, משמע שאין זה נחשב כאוהל לפסול. \u0003אמר ר' שמעון\u0004 וסיפר מעשה אחר, לסתור דברי ר' יהודה; \u0003מעשה בטבי עבדו של רבן גמליאל שהיה ישן תחת המטה, ואמר להן רבן גמליאל לזקנים\u0004 בצחוק: \u0003ראיתם טבי עבדי שהוא תלמיד חכם ויודע שעבדים פטורים מן הסוכה,\u0004 שהרי מצות עשה שהזמן גרמא היא ועבדים (כנשים) אינם חייבים בה, \u0003ולפיכך ישן הוא\u0004 בכוונה תחילה \u0003תחת המטה. ולפי דרכינו,\u0004 כלומר: אגב דברים אלה שלא נאמרו להורות הלכה, \u0003למדנו\u0004 שלדעתו \u0003הישן תחת המטה לא יצא ידי חובתו.\u0004","","נאמר במשנה שהישן תחת המיטה לא יצא ידי חובה. שהמיטה מהווה כעין אוהל וכחציצה בינו ובין הסכך. ושואלים: \u0003והא ליכא\u0004 \u0005[והרי אין]\u0006 \u0003עשרה\u0004 טפחים בגובה המיטה, ואין אוהל פחות מעשרה טפחים! ומשיבים: \u0003תרגמא\u0004 \u0005[הסבירה]\u0006 \u0003שמואל\u0004 שכאן אכן מדובר \u0003במטה\u0004 הגבוהה \u0003עשרה\u0004 טפחים.","ומעירים: \u0003תנן התם\u0004 \u0005[שנינו\u0006 במשנה \u0005שם]\u0006 לענין טומאת אוהל: \u0003אחד חור שחררוהו המים\u0004 בסלע, \u0003או\u0004 שעשו את החור \u0003שרצים, או שאכלתו\u0004 את הסלע \u0003מלחת\u0004 (חומר מלוח נמס) שהיה בו, \u0003וכן מדבך\u0004 (שורה סדורה) של \u0003אבנים וכן סואר\u0004 (ערימה מסודרת) \u0003של קורות,\u0004 כל אחד מאלה \u0003מאהיל על הטומאה,\u0004 טומאת המת שהיתה בחלל זה, ונחשב כאוהל המת ומביא טומאה לכל דבר שנמצא תחתיו. \u0003ר' יהודה אומר: כל אהל שאינו עשוי בידי אדם\u0004 — \u0003אינו\u0004 קרוי \u0003אהל,\u0004 וחור שנעשה מעצמו אינו קרוי אוהל, ואינו מביא את הטומאה. ושואלים: \u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003ר' יהודה\u0004 מהיכן למד דבר זה?",""],["\u0003יליף\u0004 \u0005[לומד\u0006 הוא\u0005]\u0006 בגזירה שווה \u0003\"אהל\" \"אהל\" ממשכן; כתיב הכא\u0004 \u0005[נאמר כאן]\u0006 בדין טומאת המת: \u0003\"זאת התורה אדם כי ימות באהל\"\u0004 (במדבר יט, יד), \u0003וכתיב התם\u0004 \u0005[ונאמר שם]\u0006 במשכן: \u0003\"ויפרש את האהל על המשכן\"\u0004 (שמות מ, יט), \u0003מה להלן\u0004 במשכן הוא אהל שנעשה \u0003בידי אדם, אף כאן\u0004 בטומאת המת הוא דווקא אהל שנעשה \u0003בידי אדם. ורבנן\u0004 \u0005[\u0006ולדעת \u0005חכמים];\u0006 \u0003\"אהל\" \"אהל\" ריבה,\u0004 שכיון שנאמרה המלה \"אהל\" כמה פעמים בדין טומאת המת, הרי זה לרבות כל דבר המאהיל ואף שאינו \"אהל\" במובן המקובל.","ומקשים: \u0003ו\u0004האם \u0003סבר ר' יהודה\u0004 כי \u0003כל אהל שאינו עשוי בידי אדם אינו\u0004 נחשב כ\u0003אהל? ורמינהי\u0004 \u0005[ומשליכים,\u0006 מראים סתירה\u0005]\u0006 ממה ששנינו: \u0003חצרות היו בנויות בירושלים על גבי הסלע, ותחתיהם,\u0004 תחת החצירות הללו, היה \u0003חלל\u0004 טפח ויותר, \u0003מפני קבר התהום.\u0004 כלומר: שאם יש טומאת מת לא ידועה עמוק באדמה תחת החצירות, הרי מכל מקום חלל זה מפסיק בין הטומאה שלמטה ובין החצרות שלמעלה. \u0003ומביאין נשים עוברות\u0004 (הרות) \u0003ויולדות שם\u0004 באותן החצירות \u0003ומגדלות בניהם שם,\u0004 ואינן יוצאות משם עד שגדלו הילדים, וכל זאת כדי שיהיו טהורים מכל טומאה ויוכלו לסייע במצות \u0003פרה\u0004 אדומה שבאפרה מטהרים טמאי מת.","ואחר שגדלו הילדים והיו בני שבע או שמונה שנים והיה באפשרותם לסייע למצוה זו, היו \u0003מביאין שוורים, ועל גביהן\u0004 של השוורים היו מניחים \u0003דלתות, והתינוקות\u0004 הללו \u0003יושבין על גביהן, וכוסות של אבן\u0004 שאינן מקבלות טומאה, היו מחזיקים \u0003בידיהם. הגיעו ל\u0004מעין ה\u0003שילוח — ירדו לתוך המים ומילאום\u0004 את הכוסות הללו במים, \u0003ועלו\u0004 בחזרה על הדלתות שעל גבי השוורים \u0003וישבו להם,\u0004 ומכאן היו המים שבהם נתנו את אפר הפרה, ובהם היזו. \u0003ר' יוסי אומר:\u0004 לא היה התינוק יורד מן השור כלל, אלא \u0003ממקומו היה משלשל\u0004 את הכלי בחבל \u0003וממלא, מפני קבר התהום.\u0004 כלומר: שמא טמונה טומאת מת מתחת לאותה דרך שהולכים ממקום עמידת השוורים אל המעיין.","\u0003ותניא\u0004 \u0005[ושנויה\u0006 ברייתא\u0005]\u0006 אחרת, \u0003ר' יהודה אומר: לא היו מביאין דלתות, אלא שוורים\u0004 בלבד מספיקים לכך. כי שדרתם וחלל גופם של השוורים רחבים דיים כדי להוות אהל וחציצה מפני טומאת המת. ואם כן יש כאן סתירה; \u0003והא\u0004 \u0005[והרי]\u0006 \u0003שוורים\u0004 ש\u0003אהל שאינו עשוי בידי אדם הוא, וקתני\u0004 \u0005[ושנינו],\u0006 \u0003ר' יהודה אומר: לא היו מביאין דלתות אלא שוורים!\u0004 הרי שאף אהל שאינו עשוי בידי אדם, נחשב כאהל!","\u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רב דימי\u0004 מארץ ישראל לבבל, \u0003אמר\u0004 בשם \u0003ר' אלעזר: מודה ר' יהודה כמלא אגרוף.\u0004 ששיטת ר' יהודה שאהל שאינו עשוי בידי אדם אינו קרוי אהל אינה אלא ביחס לחללים קטנים, שהם כמלוא טפח, אבל בחלל גדול כאגרוף שהוא יותר מטפח, ובגדול ממנו, מודה ר' יהודה שאף שאינו עשוי בידי אדם — הריהו נחשב כאהל. \u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך]:\u0006 \u0003ומודה ר' יהודה בשקיפין\u0004 (מערות) \u0003ובנקיקי\u0004 (חורים עמוקים) \u0003הסלעים\u0004 שיש להם דין אהל, אף שלא נעשו בידי אדם.","ומקשים: \u0003והרי דלת\u0004 המונחת על גבי השור \u0003ש\u0004הרי ודאי \u0003יש בה\u0004 (בינה לבין הקרקע) חלל בן \u0003כמה אגרופין\u0004 לפחות, \u0003וקתני\u0004 \u0005[ושנינו]\u0006 כי \u0003ר' יהודה אומר: לא היו מביאין דלתות אלא שוורים\u0004 ולכאורה נראה מכאן שהדלת כיון שאינה מבנה של קבע אינה יוצרת אהל! על קושיה זו \u0003אמר אביי\u0004 לא שר' יהודה פסל את הדלתות, אלא לדבריו \u0003לא הוצרכו להביא דלתות\u0004 למעשה, כי השוורים רחבים למדי ודי בכך.","\u0003רבא אמר\u0004 טעם אחר: \u0003לא היו מביאין דלתות כל עיקר שמפני שדעתו של תינוק גסה עליו,\u0004 שאם יושב על הדלת הרחבה הרי הוא חש עצמו בטוח כל כך במקום ישיבתו עד שהוא מתנועע לצדדים, ו\u0003שמא יוציא ראשו או אחד מאבריו\u0004 מחוץ לתחום הדלת \u0003ויטמא\u0004"],["\u0003בקבר התהום.\u0004","ומעירים: אכן \u0003תניא כוותיה\u0004 \u0005[שנויה\u0006 ברייתא \u0005כשיטתו]\u0006 של \u0003רבא; ר' יהודה אומר: לא היו מביאין דלתות כל עיקר, מפני שדעתו של תינוק גסה עליו\u0004 ו\u0003שמא יוציא\u0004 את \u0003ראשו או אחד מאבריו ויטמא בקבר התהום. אלא מביאין שוורים המצרים שכרסותיהן רחבות, והתינוקות יושבין על גביהן, וכוסות של אבן בידיהן. הגיעו לשילוח — ירדו ומלאום, עלו וישבו להן על גביהן.\u0004","ומקשים שוב מתוך דברי ר' יהודה עצמם: \u0003והרי מטה\u0004 בסוכה \u0003שיש בה\u0004 (בחלל שבין מקום השכיבה לבין הקרקע) \u0003כמה אגרופים, ותנן\u0004 \u0005[ושנינו\u0006 במשנתנו\u0005],\u0006 \u0003ר' יהודה אומר: נוהגים היינו שהיינו ישנים תחת המטה מפני הזקנים,\u0004 הרי שהמיטה אינה קרויה אהל, אף שהיא גדולה! ודוחים: \u0003שאני\u0004 \u0005[שונה]\u0006 \u0003מטה, הואיל ולגבה\u0004 היא \u0003עשויה.\u0004 כלומר: אין המיטה עשויה אלא להשתמש על גבה, ולא לצורך הדברים שמתחתיה, ולכן אף אין לומר שהחלל שתחתיה יוצר אהל. ומקשים: אם כן, הרי ה\u0003שוורים\u0004 שנסתייעו בהם להבאת המים לפרה האדומה \u0003נמי\u0004 \u0005[גם כן]\u0006 הלא \u0003לגבן\u0004 הן \u0003עשוין,\u0004 ובכל זאת מחשיבים את כריסי השוורים כאהל אף לדברי ר' יהודה!","\u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רבין\u0004 מארץ ישראל לבבל \u0003אמר\u0004 בשם \u0003ר' אלעזר: שאני\u0004 \u0005[שונים]\u0006 ה\u0003שוורים\u0004 שתחתם נחשב כאהל \u0003הואיל ומגינים על הרועים ב\u0004ימות ה\u0003חמה מפני החמה וב\u0004ימות ה\u0003גשמים מפני הגשמים,\u0004 שלפעמים שוכבים הרועים תחת כריסות השוורים כדי להנצל מן החום ומן הגשם. ומקשים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 שהגנה זו נחשבת כיוצרת אהל, אם כן \u0003מטה נמי\u0004 \u0005[גם כן]\u0006 ייחשב החלל שתחתיה כאהל \u0003הואיל ומגינה על מנעלים וסנדלים\u0004 שמניחים \u0003תחתיה!\u0004","\u0003אלא אמר רבא:\u0004 יש לדחות את ההסבר הקודם ו\u0003שאני\u0004 \u0005[שונים]\u0006 ה\u0003שוורים\u0004 שהם נחשבים אהל, \u0003הואיל ועשוין\u0004 כרים וגבם \u0003להגין על בני מעים שלהן, שנאמר: \"עור ובשר תלבישני ובעצמות וגידים תשככני\"\u0004 (איוב י, יא), וכיון שהעור והבשר נחשבים ככיסוי וסכך, כאמור בכתוב, לכן דינם כאהל.","\u0003ואי בעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 טעם אחר: \u0003ר' יהודה\u0004 הולך בענין זה \u0003לטעמיה\u0004 \u0005[לטעמו,\u0006 לשיטתו\u0005],\u0006 ש\u0003אמר: סוכה דירת קבע בעינן\u0004 \u0005[צריכים אנו]\u0006 ואין יוצאים בסוכה אלא אם כן היתה עשויה כדירת קבע, \u0003והוה לה\u0004 \u0005[ונעשתה]\u0006 \u0003מטה\u0004 זו שבסוכה \u0003דירת ארעי, וסוכה אהל קבע, ולא אתי\u0004 \u0005[\u0006יכול \u0005לבוא]\u0006 \u0003אהל ארעי\u0004 כמיטה זו \u0003ומבטל אהל קבע,\u0004 שהסוכה שצריכה להיות כבנין קבע מבטלת מתוך חשיבותה כל אהל ארעי העשוי בתוכה.","ומקשים: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003ר' שמעון\u0004 ש\u0003אמר נמי\u0004 \u0005[גם כן]\u0006 כפי שהסברנו (לעיל סוכה ז, ב) ש\u0003סוכה דירת קבע בעינן\u0004 \u0005[צריכים אנו],\u0006 ובכל זאת סבור הוא כי \u0003אתי\u0004 \u0005[בא]\u0006 \u0003אהל ארעי\u0004 כמיטה \u0003ומבטל אהל קבע\u0004 כסוכה! ומשיבים: \u0003אין\u0004 \u0005[כן]!\u0006 אכן \u0003בהא פליגי\u0004 \u0005[ב\u0006נושא \u0005זה\u0006 עצמו \u0005חלוקים הם];\u0006 \u0003מר\u0004 \u0005[חכם זה,\u0006 ר' שמעון\u0005]\u0006 \u0003סבר\u0004 כי \u0003אתי\u0004 \u0005[\u0006יכול \u0005לבוא]\u0006 \u0003אהל ארעי ומבטל אהל קבע, ומר\u0004 \u0005[וחכם זה,\u0006 ר' יהודה\u0005]\u0006 \u0003סבר\u0004 ש\u0003לא אתי\u0004 \u0005[\u0006יכול \u0005לבוא]\u0006 \u0003אהל ארעי ומבטל אהל קבע.\u0004","מסופר במשנה ש\u0003אמר ר' שמעון\u0004 והביא מעשה כדי לסתור את דברי ר' יהודה; \u0003מעשה בטבי עבדו\u0004 של רבן גמליאל שהיה ישן תחת המיטה, ולטענת רבן גמליאל היה זה מפני שהיה תלמיד חכם וידע שעבדים פטורים ממצות סוכה. \u0003תניא\u0004 \u0005[שנינו\u0006 בברייתא\u0005],\u0006 \u0003אמר ר' שמעון: משיחתו של רבן גמליאל למדנו שני דברים; למדנו שעבדים פטורים מן הסוכה, ולמדנו שהישן תחת המטה לא יצא ידי חובתו.\u0004","בלשון ברייתא זו מדקדקים: \u0003ולימא\u0004 \u0005[ושיאמר]:\u0006 \u0003\"מדבריו של רבן גמליאל\"\u0004 ומדוע השתמש בביטוי המיוחד \"שיחתו\"? ומשיבים: אכן, בכוונה השתמש בביטוי זה כי \u0003מילתא אגב אורחיה קא משמע לן\u0004 \u0005[דבר בדרך אגב השמיע לנו]\u0006 \u0003כי הא\u0004 \u0005[כמו זו]\u0006 ש\u0003אמר רב אחא בר אדא, ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 ש\u0003אמר\u0004 זאת \u0003רב אחא בר אדא אמר רב המנונא אמר רב: מנין שאפילו שיחת תלמידי חכמים\u0004 שאין בכוונת המדבר לכאורה להורות הלכה וכדומה, מניין שאף היא \u0003צריכה תלמוד\u0004 ויש בה ערך — \u0003שנאמר\u0004 בצדיקים: \u0003\"\u0004אשר פריו יתן בעיתו \u0003ועלהו לא יבול\"\u0004 (תהלים א, ג), ללמד שאצל תלמיד חכם לא רק פרי יצירתו העיקרי הוא חשוב אלא גם דברים צדדיים הנובעים ממנו (\"עלהו\") יש בהם ברכה.","\u0003הסומך סוכתו בכרעי המטה,\u0004 כלומר: שמשעין את הסכך על גבי מוטות הקבועים לצד המיטה — \u0003כשרה. ר' יהודה אומר: אם\u0004 סוכה זו \u0003אינה יכולה לעמוד בפני עצמה\u0004 ללא המיטה — הרי זו \u0003פסולה.\u0004","שואלים: \u0003מאי טעמיה\u0004 \u0005[מה טעמו]\u0006 של \u0003ר' יהודה\u0004 הפוסל סוכה זו? \u0003פליגי\u0004 \u0005[נחלקו]\u0006 \u0003בה,\u0004 בביאור הדבר \u0003ר' זירא ורב אבא בר ממל. חד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 \u0003אמר:\u0004 פסולה סוכה זו \u0003מפני שאין לה קבע,\u0004 שהרי סוכה זו מיטלטלת בהסטת המיטה, אין מיטה חזקה דיה לסמוך את הסוכה והרי כבר אמרנו שר' יהודה סבור שסוכה צריכה להיות כדירת קבע, ואם עשאה בכרעי המיטה אין זה קבע. \u0003וחד\u0004 \u0005[ואחד\u0006 מהם\u0005]\u0006 \u0003אמר:\u0004 פסולה \u0003מפני שמעמידה בדבר המקבל טומאה,\u0004 שלא רק סכך המקבל טומאה פוסל את הסוכה, אלא גם כל דבר אחר המקבל טומאה ועשוי להעמיד את הסכך.","ושואלים: \u0003מאי בינייהו\u0004 \u0005[מה\u0006 ההבדל \u0005ביניהם]\u0006 בין שני החכמים המסבירים את דברי ר' יהודה, הלכה למעשה? ומסבירים: \u0003כגון שנעץ\u0004 בקרקע \u0003שפודין של ברזל וסיכך עליהם, ו\u0004לדעת \u0003מאן דאמר\u0004 \u0005[מי שאמר]\u0006 שטעם הפסול הוא \u0003לפי שאין לה קבע, הרי יש לה קבע\u0004 בשיפודים אלה וכשירה. אולם \u0003למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאמר]\u0006 שהטעם הוא \u0003מפני שמעמידה בדבר המקבל טומאה, הרי\u0004 אף כאן \u0003מעמידה בדבר המקבל טומאה\u0004 ופסולה.","\u0003אמר אביי: לא שנו\u0004 מחלוקת זו \u0003אלא\u0004 כאשר \u0003סמך\u0004 את הסכך למוטות המיטה וכרעי המיטה משמשים כדופן לסוכה, כאשר הסוכה כולה נשענת על כך. \u0003אבל\u0004 אם \u0003סיכך על גבי המטה,\u0004 שאם הניח כמה מיטות בשלושה צדדים כדי שתשמשנה כדפנות לסוכה וסיכך את החלל שביניהן — סוכה זו לדעת הכל \u0003כשרה. מאי טעמא\u0004 \u0005[מה הטעם]\u0006 כשרה, משום שאין בה פסול לשני אופני ההסבר. \u0003למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאמר]\u0006 במשנה שאותה סוכה פסולה \u0003לפי שאין לה קבע, הרי\u0004 זו \u0003יש לה קבע\u0004 שאינה נשענת על כרעי המיטה. \u0003ולמאן דאמר\u0004 \u0005[ולמי שאמר]\u0006 \u0003מפני שמעמידה בדבר המקבל טומאה\u0004 אולם כאן \u0003הרי אין מעמידה בדבר המקבל טומאה\u0004 שעמידת הסוכה עצמה אינה בדבר המקבל טומאה."],["\u0003סוכה המדובללת ושצילתה\u0004 (הצל שבה) \u0003מרובה מחמתה\u0004 — \u0003כשרה.\u0004 סוכה שסככה \u0003מעובה\u0004 וצפופה \u0003כמין\u0004 גג \u0003בית, אף על פי\u0004 שהסכך צפוף כל כך עד \u0003שאין הכוכבים נראין מתוכה\u0004 — הרי זו \u0003כשרה.\u0004","ושאלו: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 סוכה \u0003המדובללת? אמר רב:\u0004 הכוונה היא ל\u0003סוכה ענייה.\u0004 כלומר: סוכה שסככה דליל (אבל אין בו חללים בני שלושה טפחים). \u0003ושמואל אמר:\u0004 מדובללת פירושה שהסכך איננו מונח ישר אלא באופן ש\u0003קנה\u0004 (ענף) חלק מן הסכך \u0003עולה וקנה יורד.\u0004","ומסבירים: \u0003רב תני\u0004 \u0005[שנה]\u0006 את הקטע הראשון של המשנה כהלכה בענין \u0003חדא\u0004 \u0005[\u0006סוכה \u0005אחת],\u0006 \u0003ושמואל תני\u0004 \u0005[שנה]\u0006 קטע זה כהלכה לענין \u0003תרתי\u0004 \u0005[שתים,\u0006 שתי סוכות\u0005].\u0006 כיצד? \u0003רב תני חדא\u0004 \u0005[שנה\u0006 בענין סוכה \u0005אחת]:\u0006 \u0003סוכה\u0004 ה\u0003מדובללת\u0004 ו\u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003מדובללת — מדולדלת,\u0004 משמע מכאן, שכל עוד \u0003שצילתה מרובה מחמתה\u0004 — \u0003כשרה. ושמואל תני תרתי\u0004 \u0005[שנה\u0006 בענין \u0005שתים,\u0006 שתי סוכות\u0005]\u0006 ו\u0003מאי מדובללת — מבולבלת ותרתי קתני\u0004 \u0005[ושני\u0006 דברים \u0005שנו]:\u0006 \u0003סוכה מבולבלת — כשרה, ו\u0004זו ש\u0003צילתה מרובה מחמתה\u0004 — \u0003כשרה.\u0004","\u0003אמר אביי: לא שנו\u0004 היתר זה בסוכה שסככה עולה ויורד, \u0003אלא שאין בין זה לזה,\u0004 כלומר: בין הענפים העליונים ובין הענפים התחתונים, מרחק \u0003שלשה טפחים, אבל\u0004 אם \u0003יש בין זה לזה\u0004 מרחק \u0003שלשה טפחים\u0004 — הריהי \u0003פסולה,\u0004 שבמרחק כזה אין הסכך מצטרף ליחידה אחת. \u0003אמר רבא: אפילו יש בין זה לזה\u0004 מרחק \u0003שלשה טפחים נמי לא אמרינן\u0004 \u0005[גם כן אין אומרים]\u0006 שאין הסכך מצטרף, \u0003אלא\u0004 כ\u0003שאין בגגו טפח,\u0004 כלומר: שאין חלק הסכך העולה למעלה רחב טפח, \u0003אבל\u0004 אם \u0003יש בגגו טפח\u0004 אף אם המרחק ביניהם עולה על שלושה טפחים — \u0003כשרה. דאמרינן\u0004 \u0005[שאנו אומרים]\u0006 ומשתמשים בכלל: \u0003חבוט רמי\u0004 \u0005[\u0006ו\u0005השלך],\u0006 שמשמעו: רואים אנו כאילו חבטו (השליכו את הסכך העליון, והשפילוהו להשוותו לתחתון.","\u0003אמר רבא: מנא אמינא לה\u0004 \u0005[מניין אומר אני אותה]\u0006 את ההלכה המחודשת הזו \u0003דכי אית ביה\u0004 \u0005[שכאשר יש בו]\u0006 \u0003טפח אמרינן\u0004 \u0005[אומרים אנו]\u0006 \u0003חבוט רמי\u0004 \u0005[\u0006ו\u0005השלך],\u0006 \u0003וכי לית ביה\u0004 \u0005[וכאשר אין בו]\u0006 טפח \u0003לא אמרינן\u0004 \u0005[אין אנו אומרים]\u0006 \u0003חבוט רמי\u0004 \u0005[\u0006ו\u0005השלך].\u0006 וראייה לדבר מהלכות טומאת המת; \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003קורות\u0004 תיקרת \u0003הבית ו\u0004קורות תיקרת \u0003העליה\u0004 (הקומה השנייה שעל גבי הבית), \u0003שאין עליהן מעזיבה\u0004 (טיח) ולכן אין התיקרה כולה מחוברת כיחידה אחת, וכל קורה נדונה כגג קטן לעצמה, אם \u0003הן מכוונות\u0004 שקורות תיקרת העלייה מצויות בדיוק ממול לקורות תיקרת הבית ומאהילות עליהן, אם היתה \u0003טומאה\u0004 של מת \u0003תחת אחת מהן\u0004 מן הקורות התחתונות — \u0003תחתיה,\u0004 כלומר: כל המקום תחת אותה קורה \u0003טמא\u0004 בטומאת אהל המת. שהרי התיקרה שמעל לטומאת המת מחשיבה את החלל שתחתיה כאהל המלא כולו טומאה, ואין הטומאה עולה מעל לקורה, וכל דבר שאינו מצוי מתחת לקורה זו אלא לצידה או מעליה — טהור.","היתה הטומאה \u0003בין\u0004 הקורה \u0003התחתונה לעליונה,\u0004 כלומר: בחלל העליה — מה ש\u0003ביניהן,\u0004 בין שתי הקורות ומצוי בתוך חלל העליה, \u0003טמא,\u0004 ומה שמעל העליונה או מתחת לתחתונה ושמן הצד — טהור. היתה הטומאה מונחת \u0003על גבי\u0004 הקורה \u0003העליונה\u0004 מעל לתקרת העליה — הרי כל מה ש\u0003כנגדה עד לרקיע טמא.\u0004 אולם, אם \u0003היו\u0004 הקורות \u0003העליונות כבין התחתונות,\u0004 כלומר, שקורות העלייה היו מכוונות בדיוק כנגד החללים שבין קורות הבית, אם היתה \u0003טומאה תחתיהן\u0004 בתוך הבית — כל מה ש\u0003תחת כולן טמא,\u0004 שאנו מחשיבים כאילו ירדו קורות העליה עד לגובה קורות הבית ועל ידי כך נסתמו כל החללים, ויש כאן תיקרה אחת הנמשכת בכל מלוא הבית, וכל הנמצא תחת תיקרה זו טמא. ואם היתה הטומאה \u0003על גביהן,\u0004 על גבי הקורות העליונות — הרי כל מה ש\u0003כנגדן עד הרקיע טמא.\u0004","\u0003ותני עלה\u0004 \u0005[ושנוייה\u0006 בתוספתא \u0005עליה],\u0006 על משנה זו כדברי ביאור: \u0003במה דברים אמורים\u0004 — \u0003בזמן שיש בהן\u0004 באותן קורות רוחב \u0003טפח, ו\u0004הרווח \u0003ביניהן פותח טפח\u0004 (חלל שרוחבו טפח), \u0003אבל\u0004 אם \u0003אין ביניהן פותח טפח\u0004 שהיו הקורות צפופות יותר, אם היתה מונחת ה\u0003טומאה תחת אחת מהן — תחתיה\u0004 בלבד \u0003טמא,\u0004 ואילו מה ש\u0003ביניהן\u0004 בין הקורות \u0003ועל גביהן — טהור. אלמא\u0004 \u0005[מכאן\u0006 נסיק\u0005]\u0006 \u0003כי אית ביה\u0004 \u0005[כאשר יש בו]\u0006 בקורה העליונה \u0003טפח אמרינן\u0004 \u0005[אומרים אנו]:\u0006 \u0003חבוט רמי\u0004 \u0005[\u0006ו\u0005השלך]\u0006 את הקורות העליונות כאילו היו למטה, \u0003וכי לית ביה\u0004 \u0005[וכאשר אין בו]\u0006 \u0003טפח לא אמרינן\u0004 \u0005[אין אנו אומרים]\u0006 \u0003חבוט רמי\u0004 \u0005[\u0006ו\u0005השלך]!\u0006 ומסכמים: אכן, \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שכן הוא.","מסופר: לאחר זמן \u0003יתיב\u0004 \u0005[ישב]\u0006 \u0003רב כהנא\u0004 בישיבה \u0003וקאמר להא שמעתא\u0004 \u0005[ואמר את ההלכה הזו]\u0006 של רבא, שכל שיש בסכך העליון טפח, אפילו אם המרחק בינו לבין התחתון גדול משלושה טפחים, מחשיבים אנו אותם כאילו הם מצורפים. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אשי לרב כהנא: וכל היכא דלית ביה\u0004 \u0005[וכל מקום שאין בו]\u0006 רוחב \u0003טפח לא אמרינן\u0004 \u0005[אין אנו אומרים]:\u0006 \u0003חבוט רמי\u0004 \u0005[\u0006ו\u0005השלך];\u0006","\u0003והא תניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]\u0006 בהלכות עירובין, שאחד האופנים להכשיר מבוי סתום לטלטל בו בשבת הוא על ידי הנחת קורה רחבה טפח בפתחו של המבוי, בתוך עשרים אמה לקרקע ולא למטה מעשרה טפחים. ואמרו, אם היתה \u0003קורה היוצאת מכותל זה ואינה נוגעת בכותל זה\u0004 שכנגדו, \u0003וכן\u0004 אם היו \u0003שתי קורות אחת יוצאה מכותל זה ואחת יוצאה מכותל זה\u0004 ואף אחת מהן אינה מגיעה עד לכותל שכנגד \u0003ואינן נוגעות זו בזו,\u0004 אם היה הרווח בין הקורה והכותל או בין הקורות עצמן \u0003פחות משלשה\u0004 טפחים — \u0003אינו צריך להביא קורה אחרת\u0004 לפי שאנו אומרים כאן דין לבוד, אולם אם היה המרחק \u0003שלשה\u0004 טפחים — \u0003צריך להביא קורה אחרת\u0004 להשלים את החסר.","ואילו \u0003רבן שמעון בן גמליאל אומר:\u0004"],["\u0003פחות מארבעה\u0004 טפחים — \u0003אין צריך להביא קורה אחרת,\u0004 ואם היה \u0003ארבעה\u0004 טפחים — \u0003צריך להביא קורה אחרת.\u0004 שלדעתו דין לבוד הוא עד ארבעה טפחים (ולא שלושה).","\u0003וכן\u0004 אם היו באותו מבוי \u0003שתי קורות המתאימות\u0004 (מקבילות זו לזו) \u0003ולא בזו\u0004 רוחב \u0003כדי לקבל\u0004 (להחזיק) \u0003אריח\u0004 שהוא חצי לבינה (ולבינה עשויה כריבוע בן שלושה על שלושה טפחים) \u0003ולא בזו כדי לקבל אריח,\u0004 הרי \u0003אם מקבלות\u0004 שתי הקורות יחד במידתן \u0003אריח לרחבו,\u0004 ששתיהן יחד מגיעות לרוחב \u0003טפח,\u0004 אף על פי ששולי האריח יוצאים משתי הצדדים — \u0003אין צריך להביא קורה אחרת\u0004 כדי להכשיר את המבוי, \u0003ואם לאו\u0004 אם הן צרות יותר — \u0003צריך להביא קורה אחרת,\u0004 ואילו","\u0003רבן שמעון בן גמליאל אומר:\u0004 אפילו אם אין ברוחב הקורות הצמודות גם יחד כדי מידת טפח לקבל עליהם רוחב אריח, מכל מקום \u0003אם\u0004 לאחר שמרחיקים אותן זו מזו הם \u0003מקבלות\u0004 יחד \u0003אריח לארכו,\u0004 כלומר: שקצהו האחד מונח על אחת מהן והשני על השניה ואורכו הוא \u0003שלשה טפחים —\u0004 די בכך ושוב \u0003אין צריך להביא קורה אחרת. ואם לאו\u0004 שהן רחוקות יותר — \u0003צריך\u0004 להוסיף ו\u0003להביא קורה אחרת.\u0004","\u0003היו\u0004 שתי הקורות הללו בלתי מקבילות, והיתה \u0003אחת למעלה ואחת למטה, ר' יוסי בר' יהודה אומר: רואין\u0004 את הקורה \u0003העליונה כאילו היא למטה, ואת התחתונה כאילו היא למעלה.\u0004 כלומר: מחשיבים אותו כאילו היו מקבילות זו לזו, \u0003ובלבד שלא תהא\u0004 קורה \u0003עליונה\u0004 זו מצויה \u0003למעלה מעשרים אמה\u0004 שאז היא פסולה מכוח עצמה, וכן שלא תהא \u0003התחתונה למטה מעשרה\u0004 טפחים שגם זה הוא למטה משיעור המכשיר בקורה. ומכאן נסיק: \u0003הא\u0004 \u0005[הרי]\u0006 אם \u0003זה וזה,\u0004 שתי הקורות, \u0003בתוך עשרים\u0004 אמה \u0003אמרינן\u0004 \u0005[אומרים אנו]\u0006 \u0003חבוט רמי\u0004 \u0005[\u0006ו\u0005השלך]\u0006 \u0003אף על גב\u0004 \u0005[אף על פי]\u0006 \u0003דלית ביה\u0004 \u0005[שאין בה]\u0006 בקורה העליונה רוחב \u0003טפח,\u0004 ומכאן קשה לשיטת רבא שאין אומרים \"חבוט רמי\" אלא בדבר הרחב טפח!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רב כהנא: \u0003תריץ ואימא הכי\u0004 \u0005[ישב\u0006 את גירסת הברייתא \u0005ואמור כך]:\u0006 \u0003ובלבד שלא תהא\u0004 הקורה ה\u0003עליונה למעלה מעשרים\u0004 אמה, \u0003אלא בתוך עשרים והתחתונה סמוכה לה בפחות משלשה\u0004 טפחים, שאז אנו מחשיבים אותן כצמודות לא מדין \"חבוט\" אלא מתורת לבוד. \u0003אי נמי\u0004 \u0005[או גם כן]:\u0006 \u0003בלבד שלא תהא\u0004 ה\u0003תחתונה למטה מעשרה אלא למעלה מעשרה, ו\u0004ה\u0003עליונה סמוכה לה בפחות משלשה, אבל\u0004 אם היה המרחק בין הקורות \u0003שלשה\u0004 טפחים \u0003כיון דלית ביה\u0004 \u0005[שאין בה]\u0006 בקורה \u0003טפח\u0004 רוחב \u0003לא אמרינן\u0004 \u0005[אין אנו אומרים]\u0006 \u0003חבוט רמי\u0004 \u0005[\u0006ו\u0005השלך],\u0006 וכל קורה תיחשב בפני עצמה.","שנינו במשנה: סוכה \u0003שצילתה מרובה מחמתה כשרה.\u0004 ונדייק מלשון המשנה: \u0003הא כי הדדי\u0004 \u0005[הרי\u0006 אם היו הצל והחמה \u0005זה כמו זה,\u0006 שווים\u0005]\u0006 — הריהי \u0003פסולה.\u0004 ומקשים: \u0003והא תנן באידך פירקין\u0004 \u0005[והרי שנינו ב\u0006משנה \u0005בפרק האחר שלנו,\u0006 במסכת זו\u0005]:\u0006 סוכה \u0003שחמתה מרובה מצילתה פסולה,\u0004 ואם נדייק בדברי אותה משנה, נסיק: \u0003הא כי הדדי\u0004 \u0005[הרי\u0006 אם היו הצל והחמה \u0005זה כמו זה,\u0006 שווים\u0005]\u0006 — הריהי \u0003כשרה,\u0004 ואם כן קיימת סתירה לכאורה בדיוק הדברים בין כאן לשם!","ומשיבים: \u0003לא קשיא\u0004 \u0005[אין זה קשה];\u0006 \u0003כאן\u0004 שדייקו שכשהחמה והצל שווים בדיוק הסוכה פסולה, הרי זה \u0003מלמעלה\u0004 בסכך עצמו, ואילו \u0003כאן\u0004 שאמרו שכשהם שווים הריהי כשרה, הרי זה \u0003מלמטה.\u0004 ושני הדברים מתאימים זה לזה, כי ככל שהם יורדים למטה כתמי האור הולכים ומתרחבים, וכשהצל שווה לאור החמה כשהוא למטה, ודאי שהסכך שלמעלה צפוף דיו והוא רב על הרווחים שבו. \u0003אמר רב פפא: היינו דאמרי אינשי\u0004 \u0005[הוא שאומרים אנשים\u0006 בפתגם עממי\u0005]:\u0006 \u0003כזוזא מלעיל כאיסתרא מלתחת\u0004 \u0005[\u0006גודל של \u0005זוז מלמעלה\u0006 נעשה גדול \u0005כ\u0006מטבע של \u0005איסתרא מלמטה].\u0006","שנינו במשנה שסוכה שסככה \u0003מעובה כמין בית\u0004 — כשרה. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 סוכה \u0003המעובה\u0004 בסככה \u0003כמין בית, אף על פי\u0004 שצפופה כל כך עד \u0003שאין הכוכבים נראין מתוכה — כשרה.\u0004 אולם אם גם \u0003אין כוכבי חמה נראין מתוכה,\u0004 שהסכך צפוף שאפילו ניצוצות אור השמש אינם נראים שם — \u0003בית שמאי פוסלין ובית הלל מכשירין.\u0004","\u0003העושה סוכתו בראש העגלה או בראש הספינה\u0004 — אף על פי שהיא מיטלטלת, הרי זו סוכה \u0003כשרה,\u0004 שדי לסוכה שתהא כדירת ארעי. \u0003ועולין לה\u0004 (נכנסים אליה) אף \u0003ביום טוב.\u0004 עשה סוכתו \u0003בראש האילן או על גבי גמל\u0004 — הסוכה מצד עצמה \u0003כשרה, ו\u0004אולם \u0003אין עולין לה ביום טוב\u0004 לפי שאסרו חכמים לעלות או להשתמש ביום טוב באילן או בבהמה.","\u0003היו שתים\u0004 מדפנות הסוכה \u0003באילן, ואחת\u0004 עשויה \u0003בידי אדם\u0004 למטה בקרקע, \u0003או\u0004 שהיו \u0003שתים\u0004 עשויות \u0003בידי אדם ואחת באילן\u0004 — הסוכה מצד עצמה \u0003כשרה,\u0004 אולם \u0003אין עולין לה ביום טוב\u0004 לפי שאסור להשתמש באילן. אולם אם היו \u0003שלש\u0004 מן הדפנות עשויות \u0003בידי אדם ואחת באילן,\u0004 כיוון שיש בה הכשר סוכה בידי אדם — הרי זו סוכה \u0003כשרה, ו\u0004אף \u0003עולין לה ביום טוב.\u0004"],["\u0003זה הכלל: כל שינטל האילן ויכולה\u0004 הסוכה \u0003לעמוד בפני עצמה\u0004 ללא האילן — הרי זו סוכה \u0003כשרה ו\u0004אף \u0003עולין לה ביום טוב,\u0004 שהרי אין עיקר משענתה על האילן.","ומעירים: \u0003מני מתניתין\u0004 \u0005[כ\u0006שיטת \u0005מי משנתנו]\u0006 — כשיטת \u0003ר' עקיבא היא. דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003העושה סוכתו בראש הספינה — רבן גמליאל פוסל, ור' עקיבא מכשיר.\u0004","\u0003מעשה ברבן גמליאל ור' עקיבא שהיו באין בספינה, עמד ר' עקיבא ועשה סוכה בראש הספינה. למחר נשבה רוח ועקרתה. אמר לו רבן גמליאל: עקיבא! היכן סוכתך?\u0004 כלומר: מעיקרה לא היתה זו סוכה כשרה.","\u0003אמר אביי: דכולי עלמא\u0004 \u0005[לדעת הכל]\u0006 \u0003היכא\u0004 \u0005[היכן,\u0006 במקום\u0005]\u0006 ש\u0003אינה יכולה לעמוד ברוח מצויה\u0004 של ה\u0003יבשה,\u0004 שרוח מפילה אותה — \u0003לא כלום היא,\u0004 שודאי אינה נחשבת אף כדירת ארעי. ואם \u0003יכולה לעמוד\u0004 אפילו \u0003ב\u0004רוח \u0003שאינה מצויה\u0004 של ה\u0003יבשה, כולי עלמא לא פליגי\u0004 \u0005[הכל אינם חלוקים]\u0006 ודעתם שהיא \u0003כשרה. כי פליגי\u0004 \u0005[כאשר נחלקו]\u0006 היה זה \u0003ב\u0004ש\u0003יכולה לעמוד ברוח מצויה\u0004 של ה\u0003יבשה,\u0004 אבל \u0003אינה יכולה לעמוד ברוח שאינה מצויה\u0004 של ה\u0003יבשה\u0004 שהיא כרוח המצויה בים. \u0003רבן גמליאל סבר: סוכה דירת קבע בעינן\u0004 \u0005[צריכים אנו]\u0006 שתהיה, ולכן \u0003כיון שאינה יכולה לעמוד\u0004 ברוח שאינה מצוייה של היבשה שהיא כאותה \u0003רוח מצויה\u0004 של ה\u0003ים\u0004 — \u0003לא כלום היא,\u0004 ומעיקרה אינה סוכה. \u0003ר' עקיבא סבר: סוכה דירת עראי בעינן\u0004 \u0005[צריכים אנו]\u0006 \u0003וכיון\u0004 ש\u0003יכולה לעמוד ברוח מצויה ביבשה — כשרה\u0004 אף שאינה עומדת ברוח מצויה שבים.","שנינו במשנה שאם עשה סוכתו בראש האילן \u0003או על גבי גמל\u0004 — כשרה. ומעירים: \u0003מתניתין מני\u0004 \u0005[משנתנו\u0006 כשיטת \u0005מי היא]\u0006 — כשיטת \u0003ר' מאיר היא. דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003העושה סוכתו על גבי בהמה — ר' מאיר מכשיר, ור' יהודה פוסל.\u0004 ושואלים: \u0003מאי טעמיה\u0004 \u0005[מה טעמו]\u0006 של \u0003ר' יהודה?\u0004 ומסבירים: \u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"חג הסכת תעשה לך שבעת ימים\"\u0004 (דברים, טז, יג) ומכאן נלמד: \u0003סוכה הראויה לשבעה\u0004 ימים שלמים, \u0003שמה סוכה. סוכה שאינה ראויה לשבעה, לא שמה סוכה.\u0004 וכיון שאסור לעלות על גבי בהמה ביום טוב הרי סוכה זו יכולה לשמש רק לששה ימים בלבד ולא לשבעה, ולכן איננה כשרה.","\u0003ו\u0004אילו \u0003לר' מאיר, הא נמי\u0004 \u0005[זו גם כן] —\u0006 \u0003מדאורייתא מיחזא חזי\u0004 \u0005[מן התורה ראויה היא],\u0006 שהרי אין איסור מן התורה להשתמש בבהמה בשבת וביום טוב, אלא \u0003רבנן הוא\u0004 \u0005[חכמים הם]\u0006 ש\u0003גזרו בה,\u0004 ואף שאסור מדברי חכמים להשתמש בה, אין איסור זה פוסל את הסוכה מעיקרה.","אולם אם \u0003עשאה לבהמה\u0004 כ\u0003דופן לסוכה,\u0004 לא שהעמיד את הסוכה כולה על גבי הבהמה אלא קשר בהמה שתשמש דופן לסוכה — \u0003ר' מאיר פוסל ור' יהודה מכשיר. שהיה ר' מאיר אומר: כל דבר שיש בו רוח חיים, אין עושין אותו לא דופן לסוכה, ולא לחי\u0004 שמתקינים בצד פתחי \u0003המבוי\u0004 להכשירו לטלטל בו בשבת, \u0003ולא פסין\u0004 (כעין עמודים) שעושים מסביב \u0003לביראות\u0004 (בורות המים השייכות לציבור), כדי לעשות את מקומם כרשות היחיד ולהתיר לשאוב מהם בשבת, \u0003ולא גולל\u0004 (כיסוי) \u0003לקבר. משום ר' יוסי הגלילי אמרו: אף אין כותבין עליו\u0004 על בעל חיים \u0003גיטי נשים.\u0004","ושואלים: \u0003מאי טעמיה\u0004 \u0005[מה טעמו]\u0006 של \u0003ר' מאיר\u0004 הפוסל דבר שיש בו רוח חיים מלשמש כמחיצה בכל ענין הדורש מחיצה? \u0003אביי אמר:\u0004 הטעם הוא \u0003שמא תמות\u0004 הבהמה, ונמצא שאין דופן לסוכה. \u0003ור' זירא אמר:\u0004 יש לחשוש \u0003שמא תברח.\u0004 ומסבירים את ההבדל בטעמי ההלכה לעניינים שונים; אם עשה דופן זו \u0003בפיל קשור, כולי עלמא לא פליגי\u0004 \u0005[הכל אינם חלוקים]\u0006 שכשרה, \u0003דאי נמי מיית\u0004 \u0005[שאם גם כן ימות]\u0006 ויפול \u0003יש\u0004 אף \u0003בנבלתו\u0004 גובה \u0003עשרה\u0004 טפחים שיכולים להיחשב כמחיצה לכל ענין. \u0003כי פליגי\u0004 \u0005[כאשר נחלקו]\u0006 הרי זה \u0003בפיל שאינו קשור.\u0004 ושם יש הבדל בשיטה: \u0003למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאמר]\u0006 כי הטעם הוא משום החשש \u0003שמא תמות\u0004 — \u0003לא חיישינן\u0004 \u0005[אין אנו חוששים],\u0006 שהרי לדעתו אף אם ימות עדיין משמש הוא כמחיצה, כאמור. \u0003ולמאן דאמר\u0004 \u0005[ו\u0006לדעת \u0005מי שאמר]\u0006 שהטעם הוא משום \u0003גזרה שמא תברח\u0004 — \u0003חיישינן\u0004 \u0005[חוששים אנו].\u0006 ומקשים: כיצד אפשר להסביר כך את הדברים?","ו\u0003למאן דאמר\u0004 \u0005[\u0006ו\u0005למי שאמר]\u0006 שהוא משום \u0003גזירה שמא תמות, ניחוש\u0004 \u0005[נחשוש]\u0006 על כל פנים, \u0003שמא תברח,\u0004 שהרי חשש זה קיים בודאי! \u0003אלא\u0004 יש לחזור ממה שאמרנו ולהסביר את הדברים כך: \u0003בפיל שאינו קשור, כולי עלמא לא פליגי\u0004 \u0005[הכל אינם חלוקים]\u0006 שאין לעשות בו מחיצה, שמא יברח. \u0003כי פליגי\u0004 \u0005[כאשר נחלקו]\u0006 הרי זה \u0003בבהמה קשורה,\u0004 וכך יש לומר: \u0003למאן דאמר\u0004 \u0005[\u0006לדעת \u0005מי שאמר]\u0006 \u0003גזרה שמא תמות\u0004 — \u0003חיישינן\u0004 \u0005[חוששים אנו]\u0006 שאף שאינה יכולה לברוח, הרי יכולה היא למות ובנבלת בהמה רגילה הלא אין גובה עשרה טפחים. אולם \u0003למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאמר]\u0006 \u0003גזרה שמא תברח\u0004 — \u0003לא חיישינן\u0004 \u0005[אין אנו חוששים],\u0006 שהרי קשור הוא.","ושואלים \u0003ו\u0004אף ל\u0003מאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאמר]\u0006 \u0003גזרה שמא תברח,\u0004 מדוע לא \u0003ניחוש\u0004 \u0005[נחשוש]\u0006 \u0003שמא תמות?\u0004 ומשיבים: לזאת לא חשש, כי כלל בידינו: \u0003מיתה לא שכיחא\u0004 \u0005[מצויה]\u0006 ובדבר שאינו מצוי אין חכמים גוזרים. ושואלים: על כל פנים ולכל הדעות, \u0003והא איכא רווחא דביני ביני\u0004 \u0005[והרי יש ריוח שבינתיים]\u0006 בין הרגלים, שהיא כפירצה בדופן וכיצד אפשר לעשות דופן שרובה פרוצה? ומשיבים: \u0003דעביד ליה בהוצא ודפנא\u0004 \u0005[שעושה\u0006 וסותם את המחיצה \u0005ב\u0006מחיצה קלה של \u0005עלי דקל ודפנה].\u0006","ושואלים עוד: והרי יש עוד מקום לחשש \u0003ודלמא רבעה\u0004 \u0005[ושמא תרבץ]\u0006 הבהמה ותשבר דופן זו? ומשיבים: צריכים לומר \u0003דמתיחא\u0004 \u0005[מתוחה,\u0006 קשורה\u0005]\u0006 הבהמה \u0003באשלי מלעילא\u0004 \u0005[בחבלים מלמעלה]\u0006 ואינה יכולה לרבוץ. כיון שהגענו להסביר שמדובר במצב מיוחד זה, שואלים: \u0003ולמאן דאמר\u0004 \u0005[ול\u0006דעת \u0005מי שאמר]\u0006 \u0003גזרה שמא תמות נמי\u0004 \u0005[גם כן]\u0006 הרי אין כל מקום לחשש; \u0003הא מתיחא באשלי מלעילא\u0004 \u0005[הרי מתוחה היא בחבלים מלמעלה]\u0006 וגם אם תמות הבהמה, עדיין היא עומדת כפי שהיתה וממלאת את המקום! ומשיבים: \u0003זמנין דמוקים\u0004 \u0005[פעמים שמעמיד]\u0006 את הבהמה הזו כדופן \u0003פחות משלשה סמוך לסכך\u0004 שאין גובה הבהמה מגיע אלא לשבעה טפחים ומשהו, ואת הסכך צריך להניח לפחות בגובה עשרה טפחים כדי שתהא הסוכה כשרה,"],["\u0003וכיון דמייתא\u0004 \u0005[שהיא מתה] —\u0006 \u0003כווצא ולאו אדעתיה\u0004 \u0005[מתכווצת\u0006 מעט \u0005ואינו\u0006 מעלה \u0005על דעתו]\u0006 שיש צורך לתקן, ונמצא חלל יותר משלושה בין הדופן והסכך ונפסלת הסוכה.","ושואלים: \u0003ומי\u0004 \u0005[והאם]\u0006 \u0003אמר אביי\u0004 כי \u0003ר' מאיר חייש\u0004 \u0005[חושש]\u0006 \u0003למיתה\u0004 כשיטתו בענין הדופן, \u0003ור' יהודה לא חייש\u0004 \u0005[חושש]?\u0006 \u0003והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]:\u0006 \u0003בת ישראל שנשאת לכהן והלך בעלה למדינת הים\u0004 — ממשיכה בת ישראל זו להיות \u0003אוכלת בתרומה\u0004 כדין אשת כהן, שכן \u0003בחזקת שהוא\u0004 (בעלה) עדיין חי ו\u0003קיים\u0004 ובזכות בעלה היא אוכלת. ומכאן שאנו סבורים שכל אדם שלא נודע שמת נחשב כעודנו חי.","\u0003ורמינן עלה\u0004 \u0005[ומשליכים,\u0006 מראים סתירה \u0005עליה]\u0006 ממשנה אחרת, שנאמר בה: הנוסע ממקומו, וכדי שלא להותיר את אשתו עגונה, נתן לה גט ואמר לה: \u0003הרי זה גיטך,\u0004 ויחול הגט \u0003שעה אחת קודם מיתתי — אסורה לאכול בתרומה מיד\u0004 שאנו חוששים שמא ימות בעוד שעה. משמע שחוששים שמא ימות בכל רגע!","\u0003ואמר אביי\u0004 בתירוץ הסתירה: \u0003לא קשיא\u0004 \u0005[אין זה קשה];\u0006 \u0003הא\u0004 \u0005[זו]\u0006 שאמרנו שבת ישראל שנישאה לכהן אוכלת בתרומה בחזקת שהוא קיים, כשיטת \u0003ר' מאיר דלא חייש\u0004 \u0005[שאינו חושש]\u0006 \u0003למיתה, הא\u0004 \u0005[וזו]\u0006 שחוששים למיתה בכל שעה, הריהי כשיטת \u0003ר' יהודה, דחייש\u0004 \u0005[שהוא חושש]\u0006 \u0003למיתה.\u0004","וראיה לכך שאלו שיטותיהם; \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003הלוקח יין מבין הכותים\u0004 (השומרונים) ויש לחשוש שיין זה לא הופרשו ממנו תרומות ומעשרות, ואין סיפק בידו להפריש עכשיו את התרומות, אם היו מאה לוג יין בחביות, הרי זה \u0003אומר: שני לוגין שאני עתיד להפריש\u0004 כתרומה גדולה (ששיעורה כרגיל אחד מחמישים) \u0003הרי הן תרומה, עשרה\u0004 לוגין \u0003מעשר ראשון,\u0004 ועשירית מן הנותר שהם \u0003תשעה\u0004 לוגין, יהיו \u0003מעשר שני, ומיחל\u0004 ומחלל על כסף את המעשר השני שעתיד להפריש \u0003ושותה מיד,\u0004 ויכול לסמוך על ההפרשה שיעשה לאחר מכן, אלו \u0003דברי ר' מאיר.\u0004"],["\u0003ר' יהודה ור' יוסי ור' שמעון אוסרין,\u0004 משום שהם חוששים שמא יבקע נוד היין וישפך הכל לפני שיספיק להפריש בפועל ונמצא שותה טבל. הרי שר' מאיר הוא שאינו חושש לתקלה. שתארע לאחר מכן, ור' יהודה הוא החושש אף לבקיעת הנוד, וכל שכן למיתה!","ומשיבים: \u0003איפוך\u0004 \u0005[הפוך]\u0006 את הגירסות ואמור שכך הסביר אביי: \u0003ר' מאיר חייש\u0004 \u0005[חושש]\u0006 \u0003למיתה, ור' יהודה לא חייש\u0004 \u0005[חושש]\u0006 \u0003למיתה, דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003עשאה לבהמה דופן לסוכה, ר' מאיר פוסל\u0004 מן הטעם שאמרנו, שהוא חושש למיתה, \u0003ור' יהודה מכשיר.\u0004","ושואלים: \u0003אם כן קשיא\u0004 \u0005[קשה]\u0006 לדברי \u0003ר' מאיר\u0004 בענין סוכה שחושש למיתה, על דברי \u0003ר' מאיר\u0004 לענין הפרשת מעשרות, שרואים שאינו חושש לתקלה מאוחרת בבקיעת הנוד! ומשיבים: \u0003אמר\u0004 \u0005[\u0006יכול היה \u0005לומר]\u0006 \u0003לך ר' מאיר\u0004 ולתרץ: \u0003מיתה שכיחא\u0004 \u0005[מצויה],\u0006 שהרי כל חי סופו למות, ואילו \u0003בקיעת הנוד לא שכיחא\u0004 \u0005[אינה מצויה],\u0006 כי \u0003אפשר דמסר ליה\u0004 \u0005[שימסור אותו,\u0006 את הנוד\u0005]\u0006 \u0003לשומר\u0004 שישמרנו שלא יבקע עד שיפריש ממנו.","ומקשים: הלא \u0003קשיא\u0004 מדברי \u0003ר' יהודה\u0004 בענין סוכה שאינו חושש למיתה על דברי \u0003ר' יהודה\u0004 לענין מעשרות, שחושש לבקיעת הנוד!","ומתרצים: \u0003טעמא\u0004 \u0005[הטעם]\u0006 של \u0003ר' יהודה\u0004 במעשרות \u0003לאו\u0004 \u0005[\u0006האם \u0005לא]\u0006 \u0003משום דחייש\u0004 \u0005[שהוא חושש]\u0006 \u0003לבקיעת\u0004 ה\u0003נוד, אלא משום דלית ליה\u0004 \u0005[שאינו\u0006 מקבל את העקרון\u0005]\u0006 של \u0003\"ברירה\",\u0004 שהרי דרך ההפרשה שהציע ר' מאיר מבוססת על הנחה עקרונית, שלאחר שהפריש מתברר שאותו חלק אותו הפריש היה תרומות ומעשרות ראויים מעיקרם. ואילו ר' יהודה אינו מקבל עיקרון זה, ולדעתו אין אומרים שלאחר מעשה יתברר מה מהותם של הדברים לפני כן.","ושואלים: וכי זהו הטעם? \u0003ולא חייש\u0004 \u0005[חושש]\u0006 \u0003ר' יהודה לבקיעת נוד? והא מדקתני סיפא\u0004 \u0005[והרי ממה ששנה בסופה]\u0006 של אותה ברייתא בענין מעשרות: \u0003אמרו לו\u0004 חכמים \u0003לר' מאיר: אי אתה מודה שמא יבקע הנוד ונמצא זה שותה טבלים למפרע? ואמר להו\u0004 \u0005[להם]\u0006 ר' מאיר לחכמים: איני חושש, ו\u0003לכשיבקע\u0004 הנוד תהיה זו בעיה. \u0003מכלל\u0004 הדברים אתה למד \u0003דחייש\u0004 \u0005[שחושש]\u0006 \u0003ר' יהודה\u0004 החולק על ר' מאיר \u0003לבקיעת הנוד!\u0004","ומתרצים: \u0003התם\u0004 \u0005[שם]\u0006 \u0003ר' יהודה הוא דקאמר\u0004 \u0005[שאמר]\u0006 \u0003לר' מאיר\u0004 כך: \u0003לדידי\u0004 \u0005[לשיטתי]\u0006 כלשעצמי \u0003לית לי\u0004 \u0005[אין לי,\u0006 איני מקבל\u0005]\u0006 את עקרון ה\u0003ברירה,\u0004 ולכן אי אפשר להפריש תרומות ומעשרות לאחר שתיית היין. \u0003אלא\u0004 אף \u0003לדידך\u0004 \u0005[לשיטתך]\u0006 ש\u0003יש ברירה אי אתה מודה\u0004 שיש לחשוש \u0003שמא יבקע הנוד? אמר ליה\u0004 \u0005[לו]\u0006 ר' מאיר: \u0003לכשיבקע.\u0004 כלומר: איני חושש לכך.","ומוסיפים לשאול: \u0003ולא חייש\u0004 \u0005[חושש]\u0006 \u0003ר' יהודה למיתה? והתנן\u0004 \u0005[והרי שנינו]\u0006 במשנה במסכת יומא, שאמרו חכמים: מכינים ממלא מקום לכהן הגדול ביום הכיפורים, \u0003ור' יהודה אומר:\u0004 כיון שחייב הכהן הגדול שיהיה נשוי ביום הכיפורים \u0003אף אשה אחרת מתקינין לו, שמא תמות אשתו.\u0004 משמע שהוא חושש למיתה! ומשיבים: \u0003הא איתמר עלה\u0004 \u0005[הרי\u0006 כבר \u0005נאמר עליה]\u0006 על אותה משנה, שאין היא מבטאה שיטה כללית, אלא \u0003אמר רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003ר' יהושע: מעלה עשו בכפרה\u0004 לחשוש בה לדברים שאין חוששים להם בענין אחר.","לאחר בירור זה של שיטות התנאים, חוזרים לדון בנושא הקודם. ושואלים: \u0003בין למאן דאמר\u0004 \u0005[בין ל\u0006דעת \u0005מי שאומר]\u0006 שאין עושים מחיצה מבעלי חיים מפני הטעם \u0003שמא תמות\u0004 הבהמה, \u0003בין למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאמר]\u0006 שהטעם הוא \u0003שמא תברח,\u0004 הלא מדבריהם נשמע כי \u0003מדאורייתא\u0004 \u0005[מן התורה]\u0006 \u0003מחיצה מעליא\u0004 \u0005[מעולה,\u0006 גמורה\u0005]\u0006 \u0003היא,\u0004 אלא \u0003רבנן הוא\u0004 \u0005[חכמים הם]\u0006 ש\u0003גזרו בה,\u0004 שמא תארע תקלה. \u0003אלא מעתה,\u0004 לפי הסבר זה, \u0003לר' מאיר תטמא\u0004 הבהמה שעשאוה גולל גם \u0003משום גולל\u0004 לקבר, \u0003אלמה תנן\u0004 \u0005[ומדוע שנינו]\u0006 כי \u0003ר' יהודה מטמא\u0004 בהמה שהעמיד אותה על גבי הקבר \u0003משום גולל, ור' מאיר מטהר.\u0004 שאם לדעת ר' מאיר אין עושים זאת בבהמה אלא מפני חשש מוגדר שמא תמות, אולם מלכתחילה לכאורה אין כל חיסרון מהותי בעשייתה לגולל, ואם כן קשה מדוע לדבריו אין הטומאה חלה עליה?","\u0003אלא אמר רב אחא בר יעקב\u0004 עלינו לדחות את כל מה שאמרנו קודם, ולומר: \u0003קסבר\u0004 \u0005[סבור]\u0006 \u0003ר' מאיר: כל מחיצה שעומדת ב\u0004אמצעות \u0003רוח\u0004 בלבד, שאין לה חיזוק חיצוני, אלא עומדת רק על דבר שאיננו נתפס במישוש (כדבר חי העומד ברוח חיים) — \u0003אינה מחיצה,\u0004 ולשיטה זו, בהמה אינה חשובה מחיצה מעצם מהותה. \u0003איכא דאמרי\u0004 \u0005[יש אומרים]\u0006 בלשון אחרת קצת, \u0003אמר רב אחא בר יעקב: קסבר ר' מאיר כל מחיצה שאינה עשויה בידי אדם\u0004 — \u0003אינה מחיצה.\u0004","ושואלים \u0003מאי בינייהו\u0004 \u0005[מהו\u0006 ההבדל המעשי \u0005ביניהם],\u0006 בין שתי הלשונות הללו בדברי רב אחא בר יעקב? ומשיבים: \u0003איכא בינייהו\u0004 \u0005[יש ביניהם]\u0006 הבדל למעשה באופן \u0003דאוקמה\u0004 \u0005[שהעמיד אותה]\u0006 את המחיצה \u0003בנוד\u0004 ה\u0003תפוח\u0004 ברוח, שנפחו ומילאו אויר. \u0003למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 כי \u0003מחיצה\u0004 שאינה \u0003עומדת\u0004 אלא \u0003ברוח, אינה מחיצה\u0004 — \u0003הרי\u0004 אף מחיצה זו \u0003עומדת ברוח\u0004 ופסולה היא, \u0003למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 \u0003שאינה עשויה בידי אדם\u0004 פסולה —"],["\u0003הרי עשויה\u0004 מחיצה זו \u0003בידי אדם\u0004 שהרוח שבנוד בידי אדם היא.","\u0003אמר מר\u0004 \u0005[החכם]\u0006 בברייתא בענין שימוש בבעלי חיים. \u0003משום ר' יוסי הגלילי אמרו: אף אין כותבין עליו,\u0004 על דבר שיש בו רוח חיים, \u0003גיטי נשים.\u0004 ושואלים: \u0003מאי טעמיה\u0004 \u0005[מה טעמו]\u0006 של \u0003ר' יוסי הגלילי,\u0004 מהיכן למד הוא איסור זה? ומשיבים: \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005];\u0006 נאמר: \"וכתב לה \u0003ספר\u0004 כריתות\" (דברים כד, א), \u0003אין לי אלא ספר,\u0004 כלומר: קלף כתוב וגלול, \u0003מנין לרבות כל דבר\u0004 שאפשר לכתוב עליו — \u0003תלמוד לומר: \"וכתב לה\"\u0004 משמע \u0003מכל מקום,\u0004 כל דבר שאפשר לכתוב עליו.","\u0003אם כן, מה תלמוד לומר \"ספר\",\u0004 אם יכול לכתוב על כל דבר? \u0003לומר לך\u0004 ש\"ספר\" הוא דוגמא לדברים שכותבים עליהם גט, \u0003מה ספר — דבר שאין בו רוח חיים, ואינו אוכל\u0004 (דבר מאכל), \u0003אף כל דבר שאין בו רוח חיים ואינו אוכל,\u0004 ולכן אין לכתוב גט על בהמה.","ושואלים: \u0003ורבנן\u0004 \u0005[וחכמים]\u0006 המתירים לכתוב גט על בעלי חיים, כיצד הם מפרשים? ומסבירים: לדעתם \u0003אי כתב\u0004 \u0005[אילו נאמר]\u0006 בתורה \u0003\"\u0004וכתב \u0003בספר\",\u0004 היינו אומרים \u0003כדקאמרת\u0004 \u0005[כמו שאמרת].\u0006 \u0003השתא דכתיב\u0004 \u0005[עכשיו שנאמר]\u0006 \u0003\"ספר\",\u0004 אין משמעות \"ספר\" לשם עצם מסויים אלא הוא שם מופשט, ומשמעו: \u0003לספירת\u0004 (לסיפור) \u0003דברים בעלמא\u0004 \u0005[בלבד]\u0006 \u0003הוא דאתא\u0004 \u0005[שבא],\u0006 ו\"ספר כריתות\" משמעו סיפור עניין הכריתות.","ושואלים: \u0003ורבנן\u0004 \u0005[וחכמים]\u0006 \u0003האי\u0004 \u0005[זה]\u0006 שנאמר \u0003\"וכתב\" מאי דרשי ביה\u0004 \u0005[מה דורשים הם בו]?\u0006 כיון שלפירושם \"ספר\" כולל את ענין סיפור הדברים ואין משמעו דבר שכותבים עליו! ומשיבים: \u0003ההוא מיבעיא להו\u0004 \u0005[\u0006דבר \u0005זה נחוץ להם]\u0006 ללמוד כי \u0003בכתיבה\u0004 בלבד אשה \u0003מתגרשת ואינה מתגרשת בכסף.\u0004 כי \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]:\u0006 \u0003הואיל ואיתקש\u0004 \u0005[והושוותה\u0006 בכתוב\u0005]\u0006 \u0003יציאה\u0004 מן הבעל \u0003להויה,\u0004 לנישואין לאיש, היינו יכולים להעלות על הדעת: \u0003מה הויה\u0004 בקידושין נעשית (בין השאר) על ידי מתן \u0003כסף, אף יציאה\u0004 תהא יכולה להתבצע \u0003בכסף, קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שאין גירושין אלא בכתיבה.","ושואלים: \u0003ור' יוסי הגלילי האי סברא מנא ליה\u0004 \u0005[סברה זו מניין לו]\u0006 שאין גירושין אלא בכתיבה? ומשיבים: \u0003מ\"ספר כריתת\" נפקא ליה\u0004 \u0005[יוצא לו\u0006 הדבר\u0005]\u0006 שהוא מדייק: \u0003ספר — כורתה, ואין דבר אחר\u0004 כגון מתן כסף \u0003כורתה.\u0004","ושואלים: \u0003ואידך\u0004 \u0005[והאחרים]\u0006 וחכמים כיצד דורשים הם לשון \"כריתות\" שבמקרא? ומשיבים: \u0003ההוא מיבעי ליה\u0004 \u0005[\u0006דבר \u0005זה צריך להם]\u0006 שהגט יהיה \u0003דבר הכורת בינו לבינה.\u0004 כלומר: שנוסח הגט צריך להיות כזה שמנתק לחלוטין את כל הקשרים בינו ובינה. \u0003כדתניא\u0004 \u0005[\u0006ו\u0005כפי\u0006 ש\u0005שנינו\u0006 בברייתא\u0005]:\u0006 האומר לאשתו \u0003הרי זה גיטך על מנת שלא תשתי יין, ועל מנת שלא תלכי לבית אביך לעולם\u0004 — \u0003אין זה כריתות,\u0004 כיוון שהיא נשארת קשורה בו לענין מסויים על ידי התנאי שבגט לכל ימי חייה, ולכן אין אתה יכול להחשיבו כגט כריתות. אולם אם אמר לה: אל תלכי לבית אביך \u0003כל שלשים יום\u0004 — \u0003הרי זה כריתות,\u0004 כיון שלאחר אותו זמן נפסק כל קשר ביניהם.","ושואלים: \u0003ואידך\u0004 \u0005[והאחר]\u0006 ר' יוסי הגלילי מניין למד הוא שאין לעשות תנאי כזה בגיטין? ומשיבים: \u0003מ\"כרת\" \"כריתת\" נפקא\u0004 \u0005[יוצא\u0006 הדבר\u0005].\u0006 שהרי יכול היה לכתוב \"ספר כרת\", וכיון שאמר לשון \"כריתות\", למדים אנו מכאן שני דברים. ושואלים: \u0003ואידך\u0004 \u0005[והאחר]\u0006 וחכמים מה למדים הם מהכפילות? ומשיבים: \u0003\"כרת\" \"כריתות\" לא דרשי\u0004 \u0005[דורשים],\u0006 שאינם רואים בכך שינוי מהותי בלשון הכתוב שניתן ללמוד ממנו.","\u0003העושה סוכתו בין האילנות והאילנות\u0004 משמשים כ\u0003דפנות לה\u0004 — הרי זו סוכה \u0003כשרה.\u0004","\u0003אמר רב אחא בר יעקב: כל מחיצה שאינה יכולה לעמוד ברוח מצויה\u0004 — \u0003אינה\u0004 קרויה \u0003מחיצה.\u0004","ומעירים: \u0003תנן\u0004 \u0005[שנינו\u0006 במשנתנו\u0005]:\u0006 \u0003העושה סוכתו בין האילנות והאילנות דפנות לה\u0004 — \u0003כשרה.\u0004 ויש לשאול: \u0003והא קאזיל ואתי\u0004 \u0005[והרי הולכים ובאים]\u0006 האילנות מחמת הרוח! ומשיבים: \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים] —\u0006 \u0003ב\u0004אילנות זקנים שהם עבים ו\u0003קשין\u0004 ואינם נעים ברוח.","ושואלים: \u0003והא איכא\u0004 \u0005[והרי יש]\u0006 את \u0003נופו\u0004 של האילן שהוא ודאי נע ברוח ואם הוא משמש כחלק מדופן הסוכה יש לפוסלה! ומשיבים: \u0003דעביד ליה בהוצא ודפנא\u0004 \u0005[שעושה אותו,\u0006 קושר אותו, \u0005בענפי דקלים ודפנה],\u0006 עד שנעשה כמחיצה שאינה נעה עוד ברוח. ואומרים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 שהאילן קשור ואיננו נע כלל, \u0003מאי למימרא\u0004 \u0005[מה יש לומר]\u0006 בכך, מה החידוש שבדבר במשנתנו? ומשיבים: \u0003מהו דתימא\u0004 \u0005[שתאמר]\u0006 \u0003ניגזר דלמא אתי לאשתמושי\u0004 \u0005[נגזור שמא יבוא להשתמש]\u0006 \u0003באילן\u0004 בשבת, כיון שהוא משמש כדופן לסוכה, ולכן נאסור אותו בכלל, לכן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שאין לחשוש לכך.","\u0003תא שמע\u0004 \u0005[בוא ושמע]\u0006 ממקור אחר להוכיח שמחיצה הנעה ברוח קרויה מחיצה, שאמרנו לגבי הפסים המקיפים באר ועושים אותה כרשות היחיד ובכך מתירים לשאוב ממנה בשבת, שאם \u0003היה\u0004 עומד \u0003שם\u0004 באחד מן הזוויות \u0003אילן\u0004 שעוביו אמה לכל צד, \u0003או גדר\u0004 אבנים מרובעת אמה על אמה, \u0003או מחיצת הקנים\u0004 — \u0003נידון משום דיומד\u0004 \u0005[עמוד כפול]\u0006 בצד הבאר ומשמש כמחיצה חלקית לשני צדדים. הרי הוכחה שאף מחיצה העשוייה לנוע ברוח, כגון מחיצת הקנים, נחשבת כמחיצה גמורה! ודוחים: \u0003התם נמי\u0004 \u0005[שם גם כן]\u0006 נחשבת היא כמחיצה גמורה \u0003משום דעביד ליה בהוצא ודפנא\u0004 \u0005[שעושה,\u0006 קושר \u0005אותה בעלי דקל ודפנה]\u0006","ומציעים שוב: \u0003תא שמע:\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה ממה ששנינו: \u0003אילן המיסך על הארץ\u0004 שנופו רחב וענפיו יורדים וסוככים עד לארץ, \u0003אם אין נופו גבוה מן הארץ שלשה טפחים\u0004 — הריהו יוצר תחתיו כעין סוכה עגולה שלימה ולכן \u0003מטלטלין תחתיו\u0004 כרשות היחיד גמורה. ולכאורה \u0003אמאי\u0004 \u0005[מדוע]\u0006 מתייחסים לנוף האילן כמחיצה \u0003הא קא אזיל ואתי\u0004 \u0005[והרי הוא הולך ובא]\u0006 ברוח? ומשיבים: \u0003התם נמי דעביד ליה בהוצא ודפנא\u0004 \u0005[שם גם כן שעושה אותו בעלי דקל ודפנה]\u0006","ושואלים: אם מדובר שעשה אותו במחיצה גמורה, \u0003אי הכי\u0004 \u0005[אם כן]\u0006\u0003ניטלטל בכוליה\u0004 \u0005[שיטלטל בכולו]\u0006 תחת האילן כולו, שהרי הוא כרשות היחיד, \u0003אלמה\u0004 \u0005[מדוע]\u0006 \u0003אמר רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003ר' יהושע: אין מטלטלין בו\u0004 תחת אילן זה,"],["\u0003אלא\u0004 רק בשטח של \u0003בית סאתים\u0004 שזהו השיעור בו התירו חכמים את הטלטול במקום שיש לו מחיצות אבל לא הוקף מתחילה לדור בו (כמידת חצר המשכן). והרי אם קשר את הנוף עד שאיננו נע, אם כן הרי זו מחיצה גמורה ויותר הטלטול איפוא תחת כולו!","ומשיבים: \u0003משום דהוי\u0004 \u0005[שהוא]\u0006 אילן זה בכל אופן \u0003דירה שתשמישיה לאויר\u0004 בלבד, שהרי אין זו דירה ממש לדור בתוכה ונעשתה רק לצורך החלל (אויר) שמחוץ לה, כגון לצורך שמירה, \u0003וכל דירה שתשמישיה לאויר אין מטלטלין בו אלא סאתים,\u0004 שאינו חשוב כדירה גמורה.","\u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה ממקום אחר: \u0003שבת בתל שהוא גבוה עשרה\u0004 טפחים מן השטח שסביב לו, ושטחו \u0003הוא מארבע אמות עד בית סאתים, וכן\u0004 אם שבת \u0003בנקע\u0004 (שקע, מקום עמוק) \u0003שהוא עמוק עשרה\u0004 טפחים מסביבתו, \u0003ו\u0004שטחו \u0003הוא מארבע אמות עד בית סאתים, וכן\u0004 אם היה במקום שיש בו \u0003קמה קצורה ושיבולות\u0004 (שבולים) \u0003מקיפות אותה\u0004 והן בגובה עשרה טפחים — הרי זה כמקום דירה ו\u0003מהלך את כולה ו\u0004עוד \u0003חוצה לה אלפים אמה\u0004 כתחום שבת ומשמע שהשיבולים משמשות כמחיצה \u0003אף על גב דאזיל ואתי\u0004 \u0005[אף על פי שהולך ובא]\u0006 ברוח! ודוחים: \u0003התם נמי דעביד ליה בהוצא ודפנא\u0004 \u0005[שם גם כן\u0006 מדובר \u0005שעשה את\u0006 השיבולים קשורות זו לזו \u0005בעלי דקל ודפנה]\u0006 והן איפוא מחיצה גמורה.","\u0003שלוחי מצוה\u0004 ההולכים ממקום למקום לצורך מצוה — \u0003פטורין מן הסוכה. חולין ומשמשיהן\u0004 (המטפלים בהם) — \u0003פטורין מן הסוכה.\u0004 וכל אדם \u0003אוכלין ושותין ארעי\u0004 סעודה שאינה של קבע \u0003חוץ לסוכה.\u0004","ושואלים: \u0003מנא הני מילי\u0004 \u0005[מניין דברים אלה]\u0006 שהעוסק במצוה פטור ממצות סוכה? \u0003דתנו רבנן\u0004 \u0005[ששנו חכמים]\u0006 בברייתא; נאמר בתורה כי יש לקרוא קריאת שמע \"בשבתך בביתך ובלכתך בדרך ובשכבך ובקומך\" (דברים ו, ז). ודורשים: \u0003\"בשבתך בביתך\" — פרט לעוסק במצוה\u0004 שאינו יושב בביתו, \u0003\"ובלכתך בדרך\" — פרט לחתן\u0004 שהוא טרוד במצותו ואינו הולך בדרכים. \u0003מכאן אמרו: הכונס\u0004 (הנושא) \u0003את הבתולה\u0004 — \u0003פטור\u0004 מקריאת שמע בלילה הראשון לנישואיו, \u0003ו\u0004הכונס \u0003את האלמנה — חייב.\u0004","ושואלים: \u0003מאי משמע\u0004 \u0005[מה,\u0006 כיצד \u0005משמע]\u0006 מתוך הפסוק הלכות אלה? \u0003אמר רב הונא:\u0004 \"בדרך\" משמעו \u0003כדרך, מה דרך\u0004 שאדם הולך בה סתם היא ענין של \u0003רשות, אף כל\u0004 העוסק בענייני \u0003רשות, לאפוקי האי\u0004 \u0005[להוציא את זה]\u0006 החתן ש\u0003במצוה\u0004 הוא \u0003עסוק.\u0004","ותוהים: הלא נאמר בכתוב בלשון סתמית \"בדרך\", \u0003מי לא עסקינן דקאזיל\u0004 \u0005[האם אין אנו עוסקים\u0006 גם כן במי \u0005שהולך]\u0006 \u0003לדבר מצוה וקא אמר רחמנא ליקרי\u0004 \u0005[ואמרה התורה שיקרא]!\u0006 ודוחים: \u0003אם כן לימא קרא\u0004 \u0005[שיאמר הכתוב]\u0006 \u0003\"בשבת ובלכת\", מאי\u0004 \u0005[מה]\u0006 משמעות ההדגשה \u0003\"בשבתך\" \"ובלכתך\",\u0004 לומר: \u0003בלכת\u0004 (בהליכה) \u0003דידך\u0004 \u0005[שלך]\u0006 \u0003הוא דמחייבת\u0004 \u0005[שאתה חייב]\u0006 \u0003הא בלכת דמצוה פטירת\u0004 \u0005[הרי בהליכה של מצוה פטור אתה].\u0006","ושואלים: אם הוא נפטר משום שהוא עסוק במצוה, \u0003אי הכי\u0004 \u0005[אם כך]\u0006 \u0003אפילו כונס את האלמנה נמי\u0004 \u0005[גם כן]\u0006 הרי מקיים הוא אותה מצוה, ומדוע חייב הוא בקריאת שמע? ומשיבים: \u0003כונס את הבתולה טריד\u0004 \u0005[טרוד]\u0006 במחשבה ובדאגה שמא לא תמצא בתולה, ולכן אין דעתו פנויה לכוון בקריאת שמע, אבל ה\u0003כונס\u0004 את ה\u0003אלמנה לא טריד\u0004 \u0005[טרוד]\u0006 בכך.","ותוהים: \u0003וכל היכא דטריד, הכי נמי\u0004 \u0005[וכי כל מי שהוא מוטרד בדבר כך גם כן]\u0006 תאמר שהוא \u0003פטור?! אלא מעתה\u0004 מי ש\u0003טבעה ספינתו בים דטריד\u0004 \u0005[שהוא טרוד\u0006 ומודאג\u0005],\u0006 \u0003הכי נמי\u0004 \u0005[כך גם כן]\u0006 תאמר שהוא \u0003פטור?! וכי תימא הכי נמי\u0004 \u0005[ואם תאמר כך הוא גם כן],\u0006 שאכן הוא פטור \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003ר' אבא בר זבדא אמר רב: אבל חייב בכל המצות האמורות בתורה חוץ\u0004 מהנחת \u0003תפלין, שהרי נאמר בהן \"פאר\"\u0004 ואין ראוי לאבל לפאר עצמו. משמע שאפילו אבל המודאג וטרוד באבלו, חייב בקריאת שמע!","ודוחים: אין להשוות, כי \u0003הכא\u0004 \u0005[כאן]\u0006 בחתן \u0003טריד\u0004 \u0005[טרוד,\u0006 מודאג\u0005]\u0006 \u0003טירדא\u0004 של \u0003מצוה,\u0004 שהוא עומד לעשות, \u0003התם\u0004 במי שטבעה ספינתו \u0003טריד\u0004 \u0005[טרוד,\u0006 מודאג\u0005]\u0006 \u0003טרדא\u0004 של \u0003רשות,\u0004 שהרי אינו חייב לדאוג על כך, ולכן אינו נפטר מן המצווה.","ושואלים: \u0003ודין זה שהעוסק במצוה פטור מן המצוה מהכא נפקא\u0004 \u0005[מכאן יוצא,\u0006 נלמד\u0005]\u0006 הדבר? והרי \u0003מהתם נפקא\u0004 \u0005[משם\u0006 ממקור אחר \u0005יוצא]\u0006 \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 נאמר: \u0003\"ויהי אנשים אשר היו טמאים לנפש אדם\u0004 ולא יכלו לעשות הפסח ביום ההוא\u0003\"\u0004 (במדבר ט, ו). לפני שאנו מסיימים את הדיון שואלים אנו שאלה להבהרה: \u0003אותם אנשים\u0004 שנטמאו למת \u0003מי היו?\u0004 ומשיבים: \u0003נושאי ארונו של יוסף\u0004 שהלך עמם במדבר \u0003היו,\u0004 אלו \u0003דברי ר' יוסי הגלילי.\u0004"],["\u0003ר' עקיבא אומר: מישאל ואלצפן היו\u0004 אלה \u0003שהיו עוסקין בנדב ואביהוא\u0004 שהרי הם שהוציאום כשנשרפו בקודש הקדשים (ויקרא י, ד). \u0003ר' יצחק אומר:\u0004 שאין מקום לזיהויים הללו, כי \u0003אם נושאי ארונו של יוסף היו, כבר היו יכולין להיטהר\u0004 שהרי חנו במקום די זמן כדי שיוכלו להיטהר. ו\u0003אם מישאל ואלצפן היו, יכולים היו\u0004 אף הם \u0003ליטהר,\u0004 שהרי בראש חודש ניסן הוקם המשכן והוא היה יום שמיני למילואים ובו נשרפו בני אהרון ומאז היו להם יותר משבעה ימים, עד ערב פסח שהוא בארבעה עשר בחודש ניסן.","\u0003אלא\u0004 היו אלה אנשים אחרים שלא נתפרשו שמותיהם, ו\u0003עוסקין במת מצוה היו,\u0004 שהזדמן להם לקבור מת באותם ימים \u0003שחל שביעי שלהן להיות\u0004 בדיוק \u0003בערב הפסח, שנאמר: \"ולא יכלו לעשות הפסח ביום ההוא\"\u0004 (במדבר ט, ו), וההדגשה היא \u0003ביום ההוא,\u0004 הוא ש\u0003אין יכולין לעשות, הא\u0004 \u0005[הרי]\u0006 \u0003למחר\u0004 — \u0003יכולין\u0004 היו \u0003לעשות,\u0004 ולכן באו לשאול אם מותר לשחוט עבורם קרבן פסח, שהרי אף שיוכלו לאוכלו בלילה, מכל מקום בשעת שחיטתו וזריקת דמו עדיין אינם טהורים. ומכל מקום למדנו מכאן שהעוסק במצוה פטור ממצוה אחרת המוטלת עליו. שהרי מוטל היה עליהם לקיים מצוה זו של קבורת המת, אף על פי שבשלה ייאלצו להמנע מהקרבת קרבן פסח שהיא מצוה חמורה!","ומשיבים: \u0003צריכא\u0004 \u0005[צריך]\u0006 לשני המקורות ללמוד מהם, \u0003דאי אשמעינן התם\u0004 \u0005[שאילו היה משמיע לנו\u0006 רק \u0005שם]\u0006 בטמאי מתים, היינו אומרים: \u0003משום\u0004 ש\u0003לא מטא\u0004 \u0005[הגיע]\u0006 \u0003זמן חיובא\u0004 \u0005[חיוב]\u0006 ה\u0003פסח\u0004 בשעה שעסקו בקבורת המת ומחובתם אכן היה לקיים מצוה זו שהיא באה ראשונה, \u0003אבל הכא\u0004 \u0005[כאן]\u0006 \u0003דמטא\u0004 \u0005[שהגיע]\u0006 כבר \u0003זמן קריאת שמע\u0004 בתוך זמן הנישואין — שמא חלה על החתן חובת קריאת שמע. על כן \u0003צריכא\u0004 \u0005[הוצרכה]\u0006 לומר. ולהיפך: \u0003ואי אשמעינן הכא\u0004 \u0005[ואילו היה משמיע לנו\u0006 רק \u0005כאן]\u0006 בקריאת שמע, היינו אומרים שמתירים שלא לקרוא כיון שאין המצוה חמורה כל כך \u0003דליכא\u0004 \u0005[שאין\u0006 בה\u0005]\u0006 עונש \u0003כרת, אבל התם\u0004 \u0005[שם]\u0006 בפסח שיש בו עונש \u0003כרת\u0004 למי שלא עשאו \u0003אימא\u0004 \u0005[אמור]\u0006 ש\u0003לא\u0004 ייפטרו מלעשותו, על כן \u0003צריכא\u0004 \u0005[נצרכה]\u0006 לומר גם בענין זה.","\u0003גופא\u0004 \u0005[לגופו]\u0006 של דבר, כיון שהזכרנו הלכות אבל, \u0003אמר ר' אבא בר זבדא אמר רב: אבל חייב בכל מצות האמורות בתורה, חוץ מתפילין, שהרי נאמר בהן \"פאר\"\u0004 ואין ראוי לאבל לפאר את עצמו. והמקור לדבר: \u0003מדאמר ליה רחמנא\u0004 \u0005[מ\u0006מה \u0005שאמר לו הקדוש ברוך הוא]\u0006 \u0003ליחזקאל\u0004 \"האנק דום מתים אבל לא תעשה \u0003פארך חבוש עליך\u0004 ונעליך תשים ברגליך\" (יחזקאל כד, יז), שיחזקאל נצטווה שלא להתאבל על מות אשתו כשאר בני אדם, ומכאן נלמד: \u0003את\u0004 \u0005[אתה]\u0006 \u0003הוא דמחייבת\u0004 \u0005[שמחוייב]\u0006 להניח תפילין (\"פאר\") אף בזמן אבלך, \u0003אבל כולי עלמא פטירי\u0004 \u0005[כל העולם פטורים].\u0006","ומעירים: \u0003והני מילי\u0004 \u0005[ודברים אלה]\u0006 שהאבל פטור מן התפילין, הרי זה דווקא \u0003ביום\u0004 ה\u0003ראשון\u0004 של האבל, \u0003דכתיב\u0004 \u0005[\u0006משום \u0005שנאמר]:\u0006 \u0003\"\u0004ושמתיה כאבל יחיד \u0003ואחריתה כיום מר\"\u0004 (עמוס ח, י), ומכאן למדו כי עיקר המרירות באבל נמשכת רק יום אחד (\"יום מר\").","\u0003ו\u0004בענין דומה \u0003אמר ר' אבא בר זבדא אמר רב: אבל חייב בסוכה.\u0004 ותוהים: \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן\u0005]\u0006 ומדוע ייפטר? ומסבירים: \u0003מהו דתימא\u0004 \u0005[שתאמר]\u0006 \u0003הואיל ואמר ר' אבא בר זבדא אמר רב: מצטער פטור מן הסוכה,\u0004 שכל מי שישיבתו בסוכה גורמת לו צער פטור מלשבת בה, הייתי אומר כי \u0003האי נמי\u0004 \u0005[זה גם כן]\u0006 \u0003מצטער הוא,\u0004 ויפטר, \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שאף על פי כן חייב הוא במצות סוכה. וטעמו: שאין הדברים דומים, כי \u0003הני מילי צערא דממילא\u0004 \u0005[דברים אלה\u0006 שפטור, אמורים באופן \u0005שהצער\u0006 בא לו \u0005מן הדבר]\u0006 מעצם ישיבתו בסוכה (כגון שקר או חם לו בה, או שהסכך מדיף ריח רע), \u0003אבל הכא איהו הוא דקא מצטער נפשיה\u0004 \u0005[כאן,\u0006 באבל, ש\u0005הוא הוא שמצער את עצמו],\u0006 \u0003מיבעי ליה ליתובי דעתיה\u0004 \u0005[צריך הוא ליישב את דעתו]\u0006 ויוכל לקיים את המצווה כראוי.","\u0003ואמר ר' אבא בר זבדא אמר רב: החתן והשושבינין\u0004 (רעיו המלוים אותו) \u0003וכל בני החופה\u0004 המשמשים ומסייעים בשמחת החופה — \u0003פטורין מן הסוכה כל שבעה\u0004 ימי משתה החתונה. ושואלים: \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר? \u0003משום דבעו למיחדי\u0004 \u0005[שהם רוצים לשמוח].\u0006 ושואלים: אם בשמחה תלוי הדבר, אם כן \u0003ליכלו\u0004 \u0005[יאכלו]\u0006 \u0003בסוכה וליחדו\u0004 \u0005[וישמחו]\u0006 \u0003בסוכה!\u0004 ומשיבים: \u0003אין שמחה\u0004 של חתונה \u0003אלא בחופה\u0004 עצמה. ושואלים: \u0003וליכלו\u0004 \u0005[ושיאכלו]\u0006 כשאר אנשים \u0003בסוכה וליחדו\u0004 \u0005[וישמחו]\u0006 \u0003בחופה!\u0004 ומשיבים: \u0003אין שמחה אלא במקום סעודה,\u0004 ולכן כיון שצריכים לשמוח בחופה, צריכים הם גם לעשות שם סעודתם.","ושואלים: \u0003וליעבדו\u0004 \u0005[ושיעשו]\u0006 \u0003חופה בסוכה\u0004 עצמה? \u0003אביי אמר:\u0004 אין עושים כן \u0003משום ייחוד,\u0004 שאם יעשו כן שמא יזדמן שתשאר הכלה ביחידות עם אדם זר המצוי בסוכה, ויעברו על האיסור להתייחד עם אשת איש. \u0003ורבא אמר:\u0004 הטעם הוא \u0003משום צער\u0004 ה\u0003חתן,\u0004 משום שהסוכה אינה סגורה מכל צד ולכן לא יוכל החתן להיות ביחידות עם כלתו, וייגרם לו בכך צער. ושואלים: \u0003מאי בינייהו\u0004 \u0005[מהו\u0006 ההבדל המעשי \u0005ביניהם]?\u0006 ומשיבים: \u0003איכא בינייהו דשכיחא אינשי דנפקי ועיילי להתם\u0004 \u0005[יש ביניהם, שמצויים אנשים שיוצאים ונכנסים לשם];\u0006 \u0003למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 שהטעם הוא \u0003משום ייחוד\u0004 — \u0003ליכא\u0004 \u0005[אין\u0006 כאן\u0005]\u0006 מקום לחשוש, שהרי תמיד יש שם עוברים ושבים. אולם \u0003למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 שהטעם הוא \u0003משום צער חתן\u0004 — \u0003איכא\u0004 \u0005[יש]\u0006 טעם לחשוש אף אז.","\u0003אמר ר' זירא: אנא\u0004 \u0005[אני]\u0006 עצמי נשאתי אשה בערב חג הסוכות ו\u0003אכלי\u0004 \u0005[אכלתי]\u0006 \u0003בסוכה וחדי\u0004 \u0005[ושמחתי]\u0006 \u0003בחופה, וכל שכן דחדי ליבאי דקא עבידנא תרתי\u0004 \u0005[ששמח ליבי שעשיתי שתים],\u0006 גם חתונה וגם מצות סוכה. אלא שאין הוא מחייב את הכל.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 ה\u0003חתן ו\u0004ה\u0003שושבינין וכל בני\u0004 ה\u0003חופה, פטורין מן התפילה ומן התפילין,\u0004 שאין דעתם פנויה ומסוגלת לכך מפני השמחה היתירה וקלות הראש העשויה להיות שם, אבל \u0003חייבין בקריאת שמע\u0004"]]};
